BASE_DIR = Path(__file__).resolve().parent.parent.parent
RAW_DIR = BASE_DIR / "data" / "raw"
BLINDED_DIR = BASE_DIR / "data" / "blinded_cases"
ANSWER_KEY_PATH = BASE_DIR / "data" / "answer_key.json"
FROZEN_MANIFEST_PATH = BASE_DIR / "data" / "frozen_manifest.json"

FS = 4096
CASE_DURATION = 8.0  # seconds
CASE_SAMPLES = int(CASE_DURATION * FS)  # 32,768 samples
RANDOM_SEED = 420012


def sha256_file(filepath: Path) -> str:
    """Compute SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while chunk := f.read(65536):
            h.update(chunk)
    return h.hexdigest()


def build_blinded_dataset(verbose: bool = True) -> Dict[str, Any]:
    """Build and freeze the 8 blinded cases."""
    BLINDED_DIR.mkdir(parents=True, exist_ok=True)
