"""Tests for dataset generation, blinding, and manifest freezing."""

import hashlib
import json
from pathlib import Path
import numpy as np
import pytest

from src.dataset.manifest import (
    load_blinded_case,
    FROZEN_MANIFEST_PATH,
    ANSWER_KEY_PATH,
    sha256_file,
    FS,
    CASE_DURATION,
)


def test_frozen_manifest_exists_and_hashes_match():
    assert FROZEN_MANIFEST_PATH.exists(), "Frozen manifest must exist"
    with open(FROZEN_MANIFEST_PATH, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    assert len(manifest["cases"]) == 8, "Must contain exactly 8 blinded cases"
    
    # Check each file's sha256 matches the manifest record
    blinded_dir = FROZEN_MANIFEST_PATH.parent / "blinded_cases"
    for cid, meta in manifest["cases"].items():
        case_file = blinded_dir / meta["file"]
        assert case_file.exists(), f"File {case_file} must exist"
        actual_hash = sha256_file(case_file)
        assert actual_hash == meta["sha256"], f"SHA256 mismatch for {cid}"


def test_blinded_cases_have_zero_hidden_labels():
    """Verify strict isolation: model-visible case files must have NO labels or timestamps."""
    for i in range(1, 9):
        cid = f"CASE_{i:02d}"
        case = load_blinded_case(cid)
        
        # Required blinded fields
        assert case["case_id"] == cid
        assert case["fs"] == FS
        assert case["duration"] == CASE_DURATION
        assert len(case["strain_h1"]) == int(FS * CASE_DURATION)
        assert len(case["strain_l1"]) == int(FS * CASE_DURATION)
        
        # Verify no hidden labels exist in dictionary
        forbidden_keys = [
            "ground_truth", "label", "category", "target", "event_name",
            "gps_start", "source_dataset", "injection_meta", "notes"
        ]
        for key in forbidden_keys:
            assert key not in case, f"Blinded payload {cid} leaked forbidden field '{key}'"


def test_answer_key_categories():
    """Verify answer key contains proper class balance."""
    with open(ANSWER_KEY_PATH, "r", encoding="utf-8") as f:
        answer_key = json.load(f)

    categories = [v["category"] for v in answer_key.values()]
    assert categories.count("CATALOGED_EVENT") >= 2
    assert categories.count("INDEPENDENT_NOISE") >= 2
    assert categories.count("WAVEFORM_INJECTION") >= 2
    assert categories.count("FALSE_ALARM_DECOY") >= 2
