"""Cheap Analytical Feasibility Checker for Gatebreak Proposals.

Uses Google's exact `fixed_point_model` and `relative_error` arithmetic from
`nr_reference_circuit.py` to evaluate whether a precision setting satisfies the
verifier's 2^-24 relative tolerance constraint across the domain.

Supports:
1. Fast sample check (~7,100 points, ~2.5 ms) for rapid candidate screening.
2. Full domain check (3,133,452 points, ~3.8 s) for definitive confirmation.
"""

from __future__ import annotations

import dataclasses
import math
import sys
from pathlib import Path
from typing import Any, Dict, Optional, Tuple

import numpy as np

# Ensure path to official nr_reference_circuit
_VERIFIERS_DIR = Path(__file__).resolve().parent / "official_data" / "verifiers" / "invsqrt"
_KICKMIX_DIR = Path(__file__).resolve().parent / "official_data" / "kickmix"
if str(_VERIFIERS_DIR) not in sys.path:
    sys.path.insert(0, str(_VERIFIERS_DIR))
if str(_KICKMIX_DIR) not in sys.path:
    sys.path.insert(0, str(_KICKMIX_DIR))

try:
    import nr_reference_circuit as nr
except ImportError:
    # If running in environment without kickmix.so, provide pure-python fallback for fixed_point_model
    nr = None


TOLERANCE_24_BITS = 2.0**-24  # 5.9604644775390625e-08
DEFAULT_N_P = 10
MAX_X = 3 * (2**DEFAULT_N_P - 2) ** 2  # 3,133,452

# Cache precomputed sample points
_SAMPLE_XS: Optional[np.ndarray] = None


def get_diagnostic_sample_xs(n_p: int = DEFAULT_N_P) -> np.ndarray:
    """Constructs a high-coverage ~7,100 point diagnostic sample.

    Spans:
    - Dense low-x region [1, 2048] where 1/sqrt(x) has maximum gradient.
    - Powers of two and adjacent values.
    - Interval boundary probes (M ~ 1.0, 1.5, 2.0, 3.0, 4.0).
    - Historically observed worst-case x values from verifier runs.
    - Uniform stratified sample across the full range [1, MAX_X].
    """
    global _SAMPLE_XS
    if _SAMPLE_XS is not None and n_p == DEFAULT_N_P:
        return _SAMPLE_XS

    max_x = 3 * (2**n_p - 2) ** 2
    pts = set()

    # 1. Dense low-x
    pts.update(range(1, min(2049, max_x + 1)))

    # 2. Powers of 2 and neighbours
    for p in range(1, 2 * n_p + 2):
        val = 1 << p
        for offset in (-2, -1, 0, 1, 2):
            x = val + offset
            if 1 <= x <= max_x:
                pts.add(x)

    # 3. Known historical verifier worst-case points
    known_worst = [729, 11766, 284670, 2588411, 2995800, max_x]
    for kw in known_worst:
        if 1 <= kw <= max_x:
            pts.add(kw)

    # 4. Stratified uniform grid (5,000 points)
    grid = np.linspace(1, max_x, 5000, dtype=np.int64)
    pts.update(grid.tolist())

    sorted_pts = np.array(sorted(pts), dtype=np.int64)
    if n_p == DEFAULT_N_P:
        _SAMPLE_XS = sorted_pts
    return sorted_pts


def evaluate_precision_analytical(
    delta_bits: int,
    coef_bits: int,
    square_bits: int,
    product_bits: int,
    result_bits: int,
    n_p: int = DEFAULT_N_P,
    xs: Optional[np.ndarray] = None,
) -> Dict[str, Any]:
    """Runs the exact fixed_point_model from nr_reference_circuit on `xs`.

    Returns dictionary with feasibility status, max error, margin, and worst x.
    """
    if nr is None:
        raise RuntimeError("nr_reference_circuit could not be imported. Ensure kickmix and paths are configured.")

    prec = nr.Precision(
        delta_bits=delta_bits,
        coef_bits=coef_bits,
        square_bits=square_bits,
        product_bits=product_bits,
        result_bits=result_bits,
    )

    if xs is None:
        xs = get_diagnostic_sample_xs(n_p)

    try:
        errs = nr.relative_error(n_p, prec, xs)
        max_idx = int(np.argmax(errs))
        max_err = float(errs[max_idx])
        worst_x = int(xs[max_idx])
        is_feasible = bool(max_err <= TOLERANCE_24_BITS)
        log2_err = float(math.log2(max_err)) if max_err > 0 else -99.0
        margin_ratio = float(max_err / TOLERANCE_24_BITS)

        return {
            "feasible": is_feasible,
            "max_relative_error": max_err,
            "log2_max_error": log2_err,
            "tolerance": TOLERANCE_24_BITS,
            "margin_ratio": margin_ratio,
            "worst_x": worst_x,
            "overflow": False,
            "error_msg": None,
            "points_checked": len(xs),
        }
    except OverflowError as e:
        return {
            "feasible": False,
            "max_relative_error": float("inf"),
            "log2_max_error": float("inf"),
            "tolerance": TOLERANCE_24_BITS,
            "margin_ratio": float("inf"),
            "worst_x": None,
            "overflow": True,
            "error_msg": f"OverflowError: {e}",
            "points_checked": len(xs),
        }
    except Exception as e:
        return {
            "feasible": False,
            "max_relative_error": float("inf"),
            "log2_max_error": float("inf"),
            "tolerance": TOLERANCE_24_BITS,
            "margin_ratio": float("inf"),
            "worst_x": None,
            "overflow": False,
            "error_msg": f"{type(e).__name__}: {e}",
            "points_checked": len(xs),
        }
"""Offline Fake-Model Replay Loop for Gatebreak Circuit Exploration.

Implements the complete closed-loop workflow:
  Proposal -> Validate -> Generate Circuit -> Diagnostic Verifier -> Feedback -> Revised Proposal

Features:
- Offline fake-model replay simulating multi-turn hypothesis refinement.
- Persistent receipts saved with SHA-256 hashes in `gatebreak_receipts.json`.
- Restart safety: atomic writes and `--resume` support.
- Explicit `--execute` safety guard: strictly enforces zero paid calls, zero network
  requests, and refuses to read secrets/.env while advertising the future spend cap.
"""

from __future__ import annotations

import argparse
