"""Structural Circuit Generator for Gatebreak Initial-Guess Polynomial Pipeline.

Applies a schema-validated StructuralProposal to generate a verifiable kickmix circuit.
Does NOT execute arbitrary code; builds purely through structured AST/builder calls.
Includes full provenance tracking (proposal SHA-256, generator SHA-256, output circuit SHA-256).
"""

from __future__ import annotations

import argparse
import dataclasses
import hashlib
import json
import math
import sys
import time
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

import numpy as np

# Ensure path to kickmix and verifier
_WORKSPACE_DIR = Path(__file__).resolve().parent
_VERIFIERS_DIR = _WORKSPACE_DIR / "official_data" / "verifiers" / "invsqrt"
_KICKMIX_DIR = _WORKSPACE_DIR / "official_data" / "kickmix"
for p in (_WORKSPACE_DIR, _VERIFIERS_DIR, _KICKMIX_DIR):
    if str(p) not in sys.path:
        sys.path.insert(0, str(p))

import kickmix as km
import nr_reference_circuit as nr
from gatebreak_structural_schema import (
    HornerStageSpec,
    StructuralProposal,
    validate_structural_proposal,
)


def compute_file_sha256(filepath: Path) -> str:
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while chunk := f.read(65536):
            h.update(chunk)
    return h.hexdigest()


def compute_str_sha256(data: str) -> str:
    return hashlib.sha256(data.encode("utf-8")).hexdigest()


# ---------------------------------------------------------------------------
# Exact Analytical Model for Structural Proposals
# ---------------------------------------------------------------------------

def structural_fixed_point_model(
    n_p: int,
    proposal: StructuralProposal,
    xs: np.ndarray,
) -> np.ndarray:
    """Exact fixed-point model mirroring the structural Horner circuit."""
    prec = proposal.baseline_precision
    width = 2 * n_p + 2
    d = prec["delta_bits"]
    wc = prec["coef_bits"]
    wsq = prec["square_bits"]
    wz = prec["product_bits"]
    wp = prec["result_bits"]

    xs = np.asarray(xs, dtype=np.int64)
    if not ((1 <= xs) & (xs < 2**width)).all():
        raise ValueError("x must lie in [1, 2^(width - 1)).")

    def bit(v: np.ndarray, i: int) -> np.ndarray:
        return (v >> i) & 1

    def product(
        rows: List[Tuple[np.ndarray, int]],
        operand: np.ndarray,
        out_bits: int,
        operand_bits: int,
        limit: int,
    ) -> np.ndarray:
        acc = np.zeros_like(xs)
        for ctl, weight in rows:
            e = out_bits - operand_bits + weight
            acc += ctl * (operand << e if e >= 0 else operand >> -e)
        if (acc >= 2**limit).any():
            raise OverflowError("Intermediate register overflow.")
        return acc

    # 1. Normalize
    s = (width - (np.floor(np.log2(xs)).astype(np.int64) + 1)) // 2
    x_norm = xs << (2 * s)
    top = bit(x_norm, width - 1)
    second = bit(x_norm, width - 2)
    third = bit(x_norm, width - 3)

    # 2. Initial guess via Structural Horner Pipeline
    nr_prec = nr.Precision(**prec)
    table = np.array(nr_prec.coefficient_table(), dtype=np.int64)
    reg_state: Dict[str, np.ndarray] = {
        f"c{j}": table[np.where(top == 0, third, 2 + second), j] for j in range(4)
    }

    # Execute structural stages
    for stage in proposal.stages:
        mult_val = reg_state[stage.mult_reg]
        acc_val = reg_state[stage.acc_reg]

        # Build delta rows specific to this stage's active_delta_bits
        delta_rows: List[Tuple[np.ndarray, int]] = []
        for b in stage.active_delta_bits:
            if b == 1:
                delta_rows.append((top & third, -1))
            else:
                delta_rows.append((bit(x_norm, width - 2 - b), -b))

        prod = product(delta_rows, mult_val, wc, wc, wc)
        if stage.operation == "sub_product":
            acc_val = acc_val - prod
        else:
            raise ValueError(f"Unsupported operation {stage.operation}")

        if ((acc_val <= 0) | (acc_val >= 2**wc)).any():
            raise OverflowError(f"Horner intermediate in stage {stage.stage_id} out of bounds.")
        reg_state[stage.acc_reg] = acc_val

    y0 = reg_state["c0"]

    # 3. Newton-Raphson
    y = {k: bit(y0, wc - k) for k in range(1, wc + 1)}
    square = np.zeros_like(xs)
    for k in range(1, wc + 1):
        if 2 * k <= wsq:
            square += y[k] << (wsq - 2 * k)
        for l in range(k + 1, wc + 1):
            if k + l - 1 <= wsq:
                square += (y[k] & y[l]) << (wsq - (k + l - 1))

    m_rows = [(bit(x_norm, i), i - width + 2) for i in range(width)]
    z = product(m_rows, square, wz, wsq, wz + 2)
    correction = (3 << wz) - z
    p = product([(y[k], -k) for k in range(1, wc + 1)], correction, wp, wz, wp + 1)
    return p << s


def structural_relative_error(
    n_p: int,
    proposal: StructuralProposal,
    xs: np.ndarray,
) -> np.ndarray:
    """Computes exact relative error of the structural candidate against 1/sqrt(x)."""
    exact = 1.0 / np.sqrt(np.asarray(xs, dtype=np.float64))
    prec = proposal.baseline_precision
    output_bits = prec["result_bits"] + n_p + 1
    approx = structural_fixed_point_model(n_p, proposal, xs) / (2.0**output_bits)
    return np.abs(approx - exact) / exact


# ---------------------------------------------------------------------------
# Quantum Circuit Construction with Kickmix
# ---------------------------------------------------------------------------

def _structural_horner(
    builder: km.CircuitBuilder,
    inverse: bool,
    proposal: StructuralProposal,
    x: km.array,
    selectors: km.array,
    coef_regs: Dict[str, km.array],
    scratch: km.array,
) -> None:
    """Emits the stage-tapered Horner evaluation circuit."""
    width = len(x)
    wc = proposal.baseline_precision["coef_bits"]
    stages = list(reversed(proposal.stages)) if inverse else list(proposal.stages)

    horner_block = builder.mark("structural_horner")
    with horner_block:
        for stage in stages:
            acc = coef_regs[stage.acc_reg]
            mult = coef_regs[stage.mult_reg]

            # Construct stage-specific delta taps
            delta_taps: List[Tuple[km.q, int]] = []
            for b in stage.active_delta_bits:
                if b == 1:
                    delta_taps.append((selectors[2], 1))
                else:
                    delta_taps.append((x[width - 2 - b], b))

            with builder.mark(stage.stage_id):
                for control, m in delta_taps:
                    terms = [(mult[i], i - m) for i in range(m, wc)]
                    nr._add_row(
                        builder,
                        inverse,
                        control,
                        terms,
                        acc,
                        scratch,
                        subtract=True,
                    )


def build_structural_circuit(
    n_p: int,
    proposal: StructuralProposal,
    *,
    compute_only: bool = False,
) -> km.Circuit:
    """Builds the complete kickmix circuit incorporating the structural proposal."""
    if n_p < 1:
        raise ValueError(f"n_p must be positive, got {n_p}")
    width = 2 * n_p + 2
    prec = proposal.baseline_precision
    out_bits = prec["result_bits"] + n_p + 1
    builder = km.CircuitBuilder()

    def alloc(length: int, name: str) -> km.array:
        if compute_only:
            return builder.create_quantum_register(length, name=name)
        return builder.alloc_qubits(length)

    x = builder.create_quantum_register(width, name="x")
    y1 = alloc(out_bits, "y1")
    flags = alloc(n_p, "flags")
    selectors = alloc(3, "selectors")
    coef_regs: Dict[str, km.array] = {
        f"c{j}": alloc(prec["coef_bits"], f"c{j}") for j in range(4)
    }
    square = alloc(prec["square_bits"], "square")
    z = alloc(prec["product_bits"] + 2, "z")
    scratch = alloc(
        max(prec["square_bits"], prec["product_bits"] + 2, prec["result_bits"] + 1),
        "scratch",
    )

    nr_prec = nr.Precision(**prec)
    y0 = coef_regs["c0"]
    p = y1[: len(y1) - len(flags)]
    all_coefs = [coef_regs[f"c{j}"] for j in range(4)]

    def compute_pipeline(inverse: bool) -> None:
        with builder.mark("uncompute_y1" if inverse else "compute_y1"):
            if inverse:
                with builder.mark("denormalize"):
                    nr._denormalize(builder, inverse, flags, y1)
                with builder.mark("multiply_y0"):
                    nr._multiply_y0(builder, inverse, y0, z, p, scratch)
                with builder.mark("correct"):
                    nr._correct(builder, inverse, z)
                with builder.mark("multiply_m"):
                    nr._multiply_m(builder, inverse, x, square, z, scratch)
                with builder.mark("square"):
                    nr._square(builder, inverse, y0, square, scratch)
                _structural_horner(builder, inverse, proposal, x, selectors, coef_regs, scratch)
                with builder.mark("load_coefficients"):
                    nr._load_coefficients(builder, nr_prec, x, selectors, all_coefs)
                with builder.mark("select_interval"):
                    nr._select_interval(builder, inverse, x, selectors)
                with builder.mark("normalize"):
                    nr._normalize(builder, inverse, x, flags)
            else:
                with builder.mark("normalize"):
                    nr._normalize(builder, inverse, x, flags)
                with builder.mark("select_interval"):
                    nr._select_interval(builder, inverse, x, selectors)
                with builder.mark("load_coefficients"):
                    nr._load_coefficients(builder, nr_prec, x, selectors, all_coefs)
                _structural_horner(builder, inverse, proposal, x, selectors, coef_regs, scratch)
                with builder.mark("square"):
                    nr._square(builder, inverse, y0, square, scratch)
                with builder.mark("multiply_m"):
                    nr._multiply_m(builder, inverse, x, square, z, scratch)
                with builder.mark("correct"):
                    nr._correct(builder, inverse, z)
                with builder.mark("multiply_y0"):
                    nr._multiply_y0(builder, inverse, y0, z, p, scratch)
                with builder.mark("denormalize"):
                    nr._denormalize(builder, inverse, flags, y1)

    compute_pipeline(False)
    if not compute_only:
        nr._phase_by_bits(builder, y1)
        compute_pipeline(True)
        for reg in (y1, flags, selectors, *all_coefs, square, z, scratch):
            builder.free(reg)

    return builder.finish_circuit()


