def get_deterministic_proposal() -> StructuralProposal:
    valid, err, proposal = validate_structural_proposal(DETERMINISTIC_CANDIDATE_RAW)
    if not valid or proposal is None:
        raise ValueError(f"Deterministic proposal validation failed: {err}")
    return proposal


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", help="Path to write the output .kmb circuit file")
    parser.add_argument("--proposal-json", help="Path to proposal JSON (defaults to deterministic candidate)")
    parser.add_argument("--diagnostic-check", action="store_true", help="Run analytical error check")
    args = parser.parse_args()

    if args.proposal_json:
        with open(args.proposal_json, "r") as f:
            raw = json.load(f)
        valid, err, proposal = validate_structural_proposal(raw)
        if not valid or proposal is None:
            print(f"Error: Invalid proposal: {err}", file=sys.stderr)
            sys.exit(1)
        raw_str = json.dumps(raw, sort_keys=True)
    else:
        proposal = get_deterministic_proposal()
        raw_str = json.dumps(DETERMINISTIC_CANDIDATE_RAW, sort_keys=True)

    proposal_hash = compute_str_sha256(raw_str)
    gen_hash = compute_file_sha256(Path(__file__).resolve())

    if args.diagnostic_check:
        print("Running analytical check on diagnostic sample (31,335 points)...")
        t0 = time.time()
        xs = np.arange(1, 3133453, 100)
        errs = structural_relative_error(10, proposal, xs)
        max_err = float(errs.max())
        log2_err = math.log2(max_err)
        dt = time.time() - t0
        print(f"Max relative error: {max_err:.4e} (2^{log2_err:.2f}) across {len(xs)} points in {dt:.3f}s")
        if max_err > 2**-24:
            print(f"FAILED analytical check: error exceeds 2^-24 ({2**-24:.4e})", file=sys.stderr)
            sys.exit(1)
        print("PASS analytical check.")

    circuit = build_structural_circuit(10, proposal)
    out_path = Path(args.output)
    circuit.to_file(str(out_path), format="kmb")
    circuit_hash = compute_file_sha256(out_path)
    stats = circuit.operation_statistics()

    provenance = {
        "proposal_id": proposal.proposal_id,
        "proposal_sha256": proposal_hash,
        "generator_sha256": gen_hash,
        "circuit_file": str(out_path.name),
        "circuit_sha256": circuit_hash,
        "num_qubits": circuit.num_qubits,
        "num_toffoli_like": stats.num_toffoli_like,
    }
    print(json.dumps(provenance, indent=2))


if __name__ == "__main__":
    main()
