class TestProposalSchema(unittest.TestCase):
    def setUp(self):
        self.valid_payload = {
            "proposal_id": "test_proposal_001",
            "rationale": "Trimming Horner delta register by 1 bit while preserving 24-bit phase fidelity.",
            "precision": {
                "delta_bits": 13,
                "coef_bits": 17,
                "square_bits": 28,
                "product_bits": 28,
                "result_bits": 28,
            },
        }

    def test_valid_proposal(self):
        valid, err, proposal = gs.validate_proposal(self.valid_payload)
        self.assertTrue(valid, f"Expected valid proposal, got error: {err}")
        self.assertIsNotNone(proposal)
        self.assertEqual(proposal.delta_bits, 13)
        self.assertEqual(proposal.result_bits, 28)

    def test_reject_unknown_root_keys(self):
        payload = dict(self.valid_payload)
        payload["malicious_script"] = "import os; os.system('ls')"
        valid, err, _ = gs.validate_proposal(payload)
        self.assertFalse(valid)
        self.assertIn("Unknown top-level keys rejected", err)

    def test_reject_unknown_precision_keys(self):
        payload = dict(self.valid_payload)
        payload["precision"] = dict(self.valid_payload["precision"])
        payload["precision"]["bogus_register_bits"] = 10
        valid, err, _ = gs.validate_proposal(payload)
        self.assertFalse(valid)
        self.assertIn("Unknown precision fields rejected", err)

    def test_reject_out_of_bounds(self):
        # delta_bits min is 10
        payload = dict(self.valid_payload)
        payload["precision"] = dict(self.valid_payload["precision"])
        payload["precision"]["delta_bits"] = 8
        valid, err, _ = gs.validate_proposal(payload)
        self.assertFalse(valid)
        self.assertIn("out of bounds", err)

        # delta_bits max is 18
        payload["precision"]["delta_bits"] = 25
        valid, err, _ = gs.validate_proposal(payload)
        self.assertFalse(valid)
        self.assertIn("out of bounds", err)

    def test_reject_non_integer_and_booleans(self):
        payload = dict(self.valid_payload)
        payload["precision"] = dict(self.valid_payload["precision"])
        # In Python, isinstance(True, int) is True, so validator must explicitly reject booleans
        payload["precision"]["delta_bits"] = True
        valid, err, _ = gs.validate_proposal(payload)
        self.assertFalse(valid)
        self.assertIn("must be an integer", err)

        payload["precision"]["delta_bits"] = 13.5
        valid, err, _ = gs.validate_proposal(payload)
        self.assertFalse(valid)
        self.assertIn("must be an integer", err)

    def test_reject_suspicious_rationale(self):
        for bad_snippet in [
            "Check out http://evil.com/hack for details.",
            "Run import os; os.system('echo pwned')",
            "Execute sh -c `cat /etc/passwd`",
            "eval('2+2') in python",
        ]:
            payload = dict(self.valid_payload)
            payload["rationale"] = f"Valid rationale text with bad snippet: {bad_snippet}"
            valid, err, _ = gs.validate_proposal(payload)
            self.assertFalse(valid, f"Failed to reject suspicious snippet: {bad_snippet}")
            self.assertIn("Security rejection", err)

    def test_rationale_length_limits(self):
        payload = dict(self.valid_payload)
        payload["rationale"] = "Too short"
        valid, err, _ = gs.validate_proposal(payload)
        self.assertFalse(valid)
        self.assertIn("too short", err)

        payload["rationale"] = "A" * 501
        valid, err, _ = gs.validate_proposal(payload)
        self.assertFalse(valid)
        self.assertIn("exceeds maximum allowed length", err)


