class TestReplayLoopAndRestartSafety(unittest.TestCase):
    def setUp(self):
        self.test_dir = tempfile.mkdtemp()
        self.receipts_file = Path(self.test_dir) / "test_receipts.json"

    def tearDown(self):
        shutil.rmtree(self.test_dir, ignore_errors=True)

    def test_replay_and_resume(self):
        engine = gr.GatebreakReplayEngine(receipts_path=self.receipts_file)
        self.assertEqual(len(engine.receipts), 0)

        # Turn 1: Aggressive failing proposal
        turn1_raw = gr.OFFLINE_REPLAY_TURNS[0]["proposal_raw"]
        r1 = engine.execute_turn(1, turn1_raw, diagnostic_max_x=512)
        self.assertEqual(r1["outcome"], "ANALYTICAL_FAILED")
        self.assertTrue(self.receipts_file.exists())
        self.assertEqual(len(engine.receipts), 1)

        # Turn 2: Refined passing proposal
        turn2_raw = gr.OFFLINE_REPLAY_TURNS[1]["proposal_raw"]
        r2 = engine.execute_turn(2, turn2_raw, diagnostic_max_x=512)
        self.assertEqual(r2["outcome"], "VERIFIED_SUCCESS")
        self.assertEqual(len(engine.receipts), 2)

        # Restart safety test: create new engine pointing to existing receipts
        resumed_engine = gr.GatebreakReplayEngine(receipts_path=self.receipts_file)
        self.assertEqual(len(resumed_engine.receipts), 2)
        done_turns = {r["turn_number"] for r in resumed_engine.receipts}
        self.assertIn(1, done_turns)
        self.assertIn(2, done_turns)


