"""Benchmark I: pairwise Coulomb phasing by `beta / sqrt(x)` (arXiv:2308.12352)."""
"""Reference Newton-Raphson circuit for Benchmark I (see `verify_submission_invsqrt.py`).

Implements the three-step algorithm of the paper with kickmix arithmetic, for `beta = 1`:

1. Normalize. Count the leading zero *pairs* `s` of `x` into a unary register and shift
   `x` in place to `x_norm = x 2^(2s)`, so that `M = x_norm / 2^(2 n_p)` lies in `[1, 4)`
   and `1 / sqrt(x) = 2^(s - n_p) / sqrt(M)`.
2. Initial guess. `y0 ~ 1 / sqrt(M)` from one of four cubic polynomials, chosen by the top
   three bits of `x_norm` (coefficients loaded by a Clifford network from two AND bits),
   evaluated by Horner's rule on `delta = M - {1, 1.5, 2, 3}` with column-truncated
   multipliers: `r1 = c2 - T(c3 delta)`, `r2 = c1 - T(r1 delta)`, `y0 = c0 - T(r2 delta)`.
3. Newton-Raphson. `p = T(y0 (3 - T(M T(y0^2)))) = 2 / sqrt(M)`, then de-normalize with
   a unary-controlled shift: `y1 = p 2^s`, so `y1 / 2^F = 1 / sqrt(x)` with
   `F = wp + n_p + 1` fractional bits of a turn.

`y1` is then used to phase with one `Z_POW` per bit and steps 1-3 are uncomputed in
reverse. `T(.)` drops every partial-product bit below the output register's least
significant bit, so all arithmetic is exactly reproduced by `fixed_point_model`, which
the tests compare against the simulated circuit and which `main` uses to report the
worst-case relative error over the whole domain.

Usage:
    python invsqrt/nr_reference_circuit.py nr.kmb [--n-p 10] [--format kmb|kmx]
"""

from __future__ import annotations

import argparse
import dataclasses
import math
from fractions import Fraction

import kickmix as km
import numpy as np

# Cubic coefficients of the paper for 1/sqrt(x) on [1, 1.5] (`A`, around 1) and
# [1.5, 2] (`B`, around 1.5), with alternating signs supplied by the circuit.
POLY_A = (0.99994132489119882162, 0.49609891915903542303, 0.33261112772430493331, 0.14876762006038398086)
POLY_B = (0.81648515205385221995, 0.27136515484240234115, 0.12756148214815175348, 0.044753028579153842218)


@dataclasses.dataclass(frozen=True)
class Precision:
    """Fractional bit widths of the pipeline's registers.

    The defaults were tuned with `fixed_point_model` for `n_p = 10`: worst case relative
    error `2.84e-8` (`2^-24` is `5.96e-8`) at ~3.9k Toffolis per direction.
    """
    delta_bits: int = 14  # Bits of `delta = M - {1, 1.5, 2, 3}` used by the Horner multipliers (M has 2 n_p).
    coef_bits: int = 17  # Coefficients and Horner intermediates `r1`, `r2`, `y0`.
    square_bits: int = 28  # `y0^2`.
    product_bits: int = 28  # `M y0^2` and `3 - M y0^2` (plus two integer bits).
    result_bits: int = 29  # `p = y0 (3 - M y0^2)` (plus one integer bit).

    def coefficient_table(self) -> list[list[int]]:
        """`table[case][j]` = coefficient magnitude `j` for interval `case`, times `2^coef_bits`.

        Cases are `[1, 1.5)`, `[1.5, 2)`, `[2, 3)`, `[3, 4)`; the last two reuse the
        polynomials on `M / 2` with `delta` left unscaled, which divides coefficient `j` by
        `2^j sqrt(2)`. Coefficients are rounded to nearest.
        """
        cases = [POLY_A, POLY_B,
                 [a / (2**j * math.sqrt(2)) for j, a in enumerate(POLY_A)],
                 [b / (2**j * math.sqrt(2)) for j, b in enumerate(POLY_B)]]
        return [[round(c * 2**self.coef_bits) for c in case] for case in cases]

    def output_bits(self, n_p: int) -> int:
        return self.result_bits + n_p + 1


# Classical model.


def fixed_point_model(n_p: int, prec: Precision, xs: np.ndarray) -> np.ndarray:
    """`y1` as computed by `build_nr_circuit` for each `x` in `xs` (`1 <= x < 2^(2 n_p + 2)`).

    `y1 / 2^prec.output_bits(n_p)` approximates `1 / sqrt(x)`. Raises if an intermediate
    would overflow its register, which the circuit would silently wrap.
    """
    width, d, wc, wsq, wz, wp = 2 * n_p + 2, *dataclasses.astuple(prec)
    xs = np.asarray(xs, dtype=np.int64)
    if not ((1 <= xs) & (xs < 2**width)).all():
        raise ValueError('x must lie in [1, 2^(width - 1)).')

    def bit(v: np.ndarray, i: int) -> np.ndarray:
        return (v >> i) & 1

    def product(rows: list[tuple[np.ndarray, int]], operand: np.ndarray, out_bits: int,
                operand_bits: int, limit: int) -> np.ndarray:
        """`T(sum_rows ctl 2^weight operand)` in units of `2^-out_bits`, checked `< 2^limit`."""
        acc = np.zeros_like(xs)
        for ctl, weight in rows:
            e = out_bits - operand_bits + weight
            acc += ctl * (operand << e if e >= 0 else operand >> -e)
        if (acc >= 2**limit).any():
            raise OverflowError('Intermediate register overflow.')
        return acc

    # 1. Normalize: s leading zero pairs, M = x_norm / 2^(width - 2) in [1, 4).
    s = (width - (np.floor(np.log2(xs)).astype(np.int64) + 1)) // 2
    x_norm = xs << (2 * s)
    top, second, third = bit(x_norm, width - 1), bit(x_norm, width - 2), bit(x_norm, width - 3)

    # 2. Initial guess: coefficients by case, delta bits of weight 2^-m for m = 1..d.
    table = np.array(prec.coefficient_table(), dtype=np.int64)
    c0, c1, c2, c3 = (table[np.where(top == 0, third, 2 + second), j] for j in range(4))
    delta = [(top & third, -1)] + [(bit(x_norm, width - 2 - m), -m) for m in range(2, min(d, width - 2) + 1)]
    y0, mult = c0, c3
    for acc in (c2, c1, c0):  # r1, r2, y0.
        y0 = mult = acc - product(delta, mult, wc, wc, wc)
        if ((y0 <= 0) | (y0 >= 2**wc)).any():
            raise OverflowError('Horner intermediate does not fit its register.')

    # 3. Newton-Raphson: y0^2 as diagonal bits plus doubled cross terms.
    y = {k: bit(y0, wc - k) for k in range(1, wc + 1)}  # Bit of weight 2^-k.
    square = np.zeros_like(xs)
    for k in range(1, wc + 1):
        if 2 * k <= wsq:
            square += y[k] << (wsq - 2 * k)
        for l in range(k + 1, wc + 1):
            if k + l - 1 <= wsq:
                square += (y[k] & y[l]) << (wsq - (k + l - 1))
    m_rows = [(bit(x_norm, i), i - width + 2) for i in range(width)]
    z = product(m_rows, square, wz, wsq, wz + 2)
    correction = (3 << wz) - z
    p = product([(y[k], -k) for k in range(1, wc + 1)], correction, wp, wz, wp + 1)
    return p << s


def relative_error(n_p: int, prec: Precision, xs: np.ndarray) -> np.ndarray:
    """`|y1 / 2^F - 1 / sqrt(x)| sqrt(x)` of the model for each `x` in `xs`."""
    exact = 1 / np.sqrt(np.asarray(xs, dtype=np.float64))
    approx = fixed_point_model(n_p, prec, xs) / 2.0**prec.output_bits(n_p)
    return np.abs(approx - exact) / exact


# Circuit construction. Each stage takes `inverse` and emits its own uncomputation:
# additions become subtractions, `init_and` becomes `del_and` (free), and the steps whose
# order matters run backwards.


def _and(builder: km.CircuitBuilder, inverse: bool, control1: km.q | km.array,
         control2: km.q | km.array, target: km.q | km.array) -> None:
    if inverse:
        builder.del_and(control1, control2, target)
    else:
        builder.init_and(control1, control2, target)


def _add_row(builder: km.CircuitBuilder, inverse: bool, control: km.q,
             terms: list[tuple[km.q, int]], target: km.array, scratch: km.array,
             subtract: bool = False) -> None:
    """`target += control * sum(2^index source)` for `(source, index)` in `terms`.

    ANDs `control` with the sources into `scratch` (aligned with `target`), adds the
    scratch slice from the lowest index up (its higher bits are clean), and uncomputes the
    ANDs by measurement.
    """
    sources = km.array([q for q, _ in terms])
    products = km.array([scratch[i] for _, i in terms])
    low = min(i for _, i in terms)
    builder.init_and(control, sources, products)
    if subtract != inverse:
        builder.isub(scratch[low:len(target)], target=target[low:])
    else:
        builder.iadd(scratch[low:len(target)], target=target[low:])
    builder.del_and(control, sources, products)


def _flag_zero_pair(builder: km.CircuitBuilder, inverse: bool, x: km.array, flag: km.q) -> None:
    """`flag := top pair of x == 00`."""
    top_pair = x[-2:]
    builder.x(top_pair)
    _and(builder, inverse, top_pair[0], top_pair[1], flag)
    builder.x(top_pair)


def _normalize(builder: km.CircuitBuilder, inverse: bool, x: km.array, flags: km.array) -> None:
    """`x := x 2^(2s)`, with `flags` the unary count `s` of leading zero pairs.

    Flag k is set iff the top pair is zero after k shifts (then the k lowest pairs are
    already zero), in which case the live even and odd bit lanes each rotate left by one.
    """
    for k in (reversed(range(len(flags))) if inverse else range(len(flags))):
        lanes = (x[2 * k::2], x[2 * k + 1::2])
        if inverse:
            for lane in lanes:
                builder.right_rotate(lane, 1, control=flags[k])
            _flag_zero_pair(builder, inverse, x, flags[k])
        else:
            _flag_zero_pair(builder, inverse, x, flags[k])
            for lane in lanes:
                builder.left_rotate(lane, 1, control=flags[k])


def _select_interval(builder: km.CircuitBuilder, inverse: bool, x: km.array, selectors: km.array) -> None:
    """`selectors := (t_a, t_b, half) = (!top & third, top & second, top & third)`.

    `t_a` and `t_b` select the coefficient set; `half` is the 1/2 bit of `delta`.
    """
    width = len(x)
    top, second, third = x[width - 1], x[width - 2], x[width - 3]
    builder.x(top)
    _and(builder, inverse, top, third, selectors[0])
    builder.x(top)
    _and(builder, inverse, top, km.array([second, third]), selectors[1:])


def _load_coefficients(builder: km.CircuitBuilder, prec: Precision, x: km.array,
                       selectors: km.array, coefs: list[km.array]) -> None:
    """XORs the coefficients of the interval selected by `(top, t_a, t_b)` into `coefs`.

    Clifford, and its own inverse.
    """
    top, t_a, t_b = x[len(x) - 1], selectors[0], selectors[1]
    table = prec.coefficient_table()
    for j, reg in enumerate(coefs):
        for control, value in ((True, table[0][j]), (top, table[0][j] ^ table[2][j]),
                               (t_a, table[0][j] ^ table[1][j]), (t_b, table[2][j] ^ table[3][j])):
            builder.gf2_iadd(value, target=reg, control=control)


def _horner(builder: km.CircuitBuilder, inverse: bool, prec: Precision, x: km.array,
            selectors: km.array, coefs: list[km.array], scratch: km.array) -> None:
    """`c2 -= T(c3 delta)`, `c1 -= T(c2 delta)`, `c0 -= T(c1 delta)`, leaving `y0` in `c0`."""
    width, wc = len(x), len(coefs[0])
    delta = [(selectors[2], 1)]  # (qubit, m) with weight 2^-m: the half bit, then bits of M.
    delta += [(x[width - 2 - m], m) for m in range(2, min(prec.delta_bits, width - 2) + 1)]
    c0, c1, c2, c3 = coefs
    steps = ((c2, c3), (c1, c2), (c0, c1))
    horner_step = builder.mark('horner_step')
    for acc, mult in (reversed(steps) if inverse else steps):
        with horner_step:
            for control, m in delta:
                _add_row(builder, inverse, control, [(mult[i], i - m) for i in range(m, wc)], acc,
                         scratch, subtract=True)


def _square(builder: km.CircuitBuilder, inverse: bool, y0: km.array, square: km.array,
            scratch: km.array) -> None:
    """`square := T(y0^2)`: diagonal bits by CNOT into the clean register, cross terms doubled."""
    wc, wsq = len(y0), len(square)
    y = {k: y0[wc - k] for k in range(1, wc + 1)}  # Bit of weight 2^-k.
    diagonal = [k for k in range(1, wc + 1) if 2 * k <= wsq]
    controls = km.array([y[k] for k in diagonal])
    targets = km.array([square[wsq - 2 * k] for k in diagonal])
    if not inverse:
        builder.cx(controls, targets)
    for k in range(1, wc + 1):
        terms = [(y[l], wsq - (k + l - 1)) for l in range(k + 1, wc + 1) if k + l - 1 <= wsq]
        if terms:
            _add_row(builder, inverse, y[k], terms, square, scratch)
    if inverse:
        builder.cx(controls, targets)


def _multiply_m(builder: km.CircuitBuilder, inverse: bool, x: km.array, square: km.array,
                z: km.array, scratch: km.array) -> None:
    """`z := T(M square)`, where bit i of `x_norm` has weight `2^(i - width + 2)` in `M`."""
    width, wsq, wz = len(x), len(square), len(z) - 2
    for i in range(width):
        e = wz - wsq + i - width + 2
        _add_row(builder, inverse, x[i], [(square[j], j + e) for j in range(max(0, -e), wsq)], z, scratch)


def _correct(builder: km.CircuitBuilder, inverse: bool, z: km.array) -> None:
    """`z := 3 - z`, in two's complement."""
    constant = (3 << (len(z) - 2)) + 1
    if inverse:
        builder.isub(constant, target=z)
        builder.x(z)
    else:
        builder.x(z)
        builder.iadd(constant, target=z)


def _multiply_y0(builder: km.CircuitBuilder, inverse: bool, y0: km.array, z: km.array,
                 p: km.array, scratch: km.array) -> None:
    """`p := T(y0 z)`."""
    wc, wz, wp = len(y0), len(z) - 2, len(p) - 1
    for k in range(1, wc + 1):  # Bit of weight 2^-k.
        e = wp - wz - k
        _add_row(builder, inverse, y0[wc - k], [(z[j], j + e) for j in range(max(0, -e), wz + 2)], p, scratch)


def _denormalize(builder: km.CircuitBuilder, inverse: bool, flags: km.array, y1: km.array) -> None:
    """`y1 := y1 2^s`, one unary-controlled shift per flag."""
    wp = len(y1) - len(flags) - 1
    for k in (reversed(range(len(flags))) if inverse else range(len(flags))):
        lane = y1[k:k + wp + 2]
        if inverse:
            builder.right_rotate(lane, 1, control=flags[k])
        else:
            builder.left_rotate(lane, 1, control=flags[k])


def _compute_y1(builder: km.CircuitBuilder, inverse: bool, prec: Precision, x: km.array,
                flags: km.array, selectors: km.array, coefs: list[km.array], square: km.array,
                z: km.array, y1: km.array, scratch: km.array) -> None:
    """Computes `y1 = 2^F / sqrt(x)` from `x` (`x` ends holding `x_norm`), or uncomputes it."""
    y0, p = coefs[0], y1[:len(y1) - len(flags)]
    with builder.mark('uncompute_y1' if inverse else 'compute_y1'):
        if inverse:
            with builder.mark('denormalize'):
                _denormalize(builder, inverse, flags, y1)
            with builder.mark('multiply_y0'):
                _multiply_y0(builder, inverse, y0, z, p, scratch)
            with builder.mark('correct'):
                _correct(builder, inverse, z)
            with builder.mark('multiply_m'):
                _multiply_m(builder, inverse, x, square, z, scratch)
            with builder.mark('square'):
                _square(builder, inverse, y0, square, scratch)
            with builder.mark('horner'):
                _horner(builder, inverse, prec, x, selectors, coefs, scratch)
            with builder.mark('load_coefficients'):
                _load_coefficients(builder, prec, x, selectors, coefs)
            with builder.mark('select_interval'):
                _select_interval(builder, inverse, x, selectors)
            with builder.mark('normalize'):
                _normalize(builder, inverse, x, flags)
        else:
            with builder.mark('normalize'):
                _normalize(builder, inverse, x, flags)
            with builder.mark('select_interval'):
                _select_interval(builder, inverse, x, selectors)
            with builder.mark('load_coefficients'):
                _load_coefficients(builder, prec, x, selectors, coefs)
            with builder.mark('horner'):
                _horner(builder, inverse, prec, x, selectors, coefs, scratch)
            with builder.mark('square'):
                _square(builder, inverse, y0, square, scratch)
            with builder.mark('multiply_m'):
                _multiply_m(builder, inverse, x, square, z, scratch)
            with builder.mark('correct'):
                _correct(builder, inverse, z)
            with builder.mark('multiply_y0'):
                _multiply_y0(builder, inverse, y0, z, p, scratch)
            with builder.mark('denormalize'):
                _denormalize(builder, inverse, flags, y1)


def _phase_by_bits(builder: km.CircuitBuilder, y: km.array) -> None:
    """Applies `y / 2^len(y)` turns via per-bit `Z_POW`."""
    f = len(y)
    with builder.mark('phase_by_bits'):
        for j in range(f):
            builder.z_pow(y[j], Fraction(2) ** (j - f + 1))  # 2^(j - f) turns.


def build_nr_circuit(n_p: int, *, prec: Precision = Precision(),
                     compute_only: bool = False) -> km.Circuit:
    """The reference circuit; `compute_only` stops after step 3 with `y1` named (for tests)."""
    if n_p < 1:
        raise ValueError(f'n_p must be positive, got {n_p}.')
    width = 2 * n_p + 2
    out_bits = prec.output_bits(n_p)
    builder = km.CircuitBuilder()

    def alloc(length: int, name: str) -> km.array:  # Named in compute_only mode, for tests.
        if compute_only:
            return builder.create_quantum_register(length, name=name)
        return builder.alloc_qubits(length)

    x = builder.create_quantum_register(width, name='x')
    y1, flags, selectors = alloc(out_bits, 'y1'), alloc(n_p, 'flags'), alloc(3, 'selectors')
    coefs = [alloc(prec.coef_bits, f'c{j}') for j in range(4)]
    square, z = alloc(prec.square_bits, 'square'), alloc(prec.product_bits + 2, 'z')
    scratch = alloc(max(prec.square_bits, prec.product_bits + 2, prec.result_bits + 1), 'scratch')
    registers = (x, flags, selectors, coefs, square, z, y1, scratch)
    _compute_y1(builder, False, prec, *registers)
    if not compute_only:
        _phase_by_bits(builder, y1)
        _compute_y1(builder, True, prec, *registers)
        for reg in (y1, flags, selectors, *coefs, square, z, scratch):
            builder.free(reg)
    return builder.finish_circuit()


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('output', help='Path of the .kmb (or .kmx) file to write.')
    parser.add_argument('--n-p', type=int, default=10, help='Bits per momentum component (default: 10).')
    parser.add_argument('--format', choices=('kmb', 'kmx'), default='kmb',
                        help="Output circuit format: 'kmb' (binary, default) or 'kmx' (text).")
    args = parser.parse_args()

    max_x = 3 * (2**args.n_p - 2)**2
    prec = Precision()
    error = relative_error(args.n_p, prec, np.arange(1, max_x + 1))
    print(f'Model: max relative error 2^{math.log2(error.max()):.2f} at x={error.argmax() + 1} '
          f'(tolerance 2^-24).')
    circuit = build_nr_circuit(args.n_p, prec=prec)
    circuit.to_file(args.output, format=args.format)
    toffolis = circuit.operation_statistics().num_toffoli_like
    print(f'Wrote {args.output} ({args.format}): {toffolis:,} Toffolis, {circuit.num_qubits} qubits.')


if __name__ == '__main__':
    main()
"""Verifier for Benchmark I: phasing by `beta / sqrt(x)` (arXiv:2308.12352).

A submission is a kickmix circuit implementing, for every `x` in `[1, max_x]`,

    |x>|0...0>  ->  exp(2 pi i beta / sqrt(x)) |x>|0...0>

The benchmark instance has `n_p = 10` bits per momentum component: `x = |nu - nu'|^2` with
`max_x = 3 (2^n_p - 2)^2 = 3,133,452`, `width = 2 n_p + 2 = 22`, and `beta = 1`.

Registers:
    x               `width` qubits, little-endian. Must be restored.
`x` must consist of distinct qubits (not classical bits). All other qubits are scratch and
must return to |0>. No other registers are allowed.

Check: each shot is simulated from a basis state `|x>|0>`. `x` must be restored, scratch must
return to |0>, and the tracked phase `theta` (in turns) must be within
`tol(x) = 2^-24 * beta / sqrt(x)` of `beta / sqrt(x)` (mod 1). Phases are compared in 64-bit
fixed point (units of 2^-64 turns): rounding the tracked phase and the target moves the
pass/fail boundary by less than 2^-63 turns, a negligible fraction of `tol(max_x)` (which must
be at least 2^-48 turns).

Every `x` in `[1, max_x]` is run `shots_per_x` times (64 by default, 200M shots for the
benchmark instance), in passes over `x = 1..max_x`. Repeated shots of each `x` probe the seeded
outcomes of measurement-based uncomputation (`HMR` and `R`). `HMR` and `R` outcomes in
`km.Simulator` are seeded with the SHA-256 of the circuit's `.kmb` binary representation
(merged with `--salt` when given). Shots are simulated across CPU cores in batches of
`batch_size`.

Cost (counted across simulated shots in `km.Simulator`):
    Toffolis     Mean Toffoli-like (`CCX`, `CCZ`, `CSWAP`) gates executed per shot.
    Z_POW        Clifford angles are free, T angles cost 1 T, other angles cost
                 `0.56 log2(1/eps) + 5.3` T each (mixed fallback synthesis,
                 arXiv:2203.10064), with `eps` the synthesis error in operator norm up
                 to global phase. That allows a relative phase error of up to `2 eps`
                 radians per rotation. Synthesis error isn't simulated, so the
                 worst case `n_rot * 2 eps` must fit in the tolerance left over by the
                 simulated error, `2 pi min_x (tol(x) - |error(x)|)` radians. The
                 verifier uses the largest `eps` that fits, split evenly.
    C            Toffolis + T / 4.
    Q            `circuit.num_qubits`.
    score        Q * C.

Usage:
    python invsqrt/verify_submission_invsqrt.py submission.kmb [--shots-per-x N] [--salt STR] [--seed N]
"""

from __future__ import annotations

import argparse
import concurrent.futures
import dataclasses
import hashlib
import io
import json
import math
import multiprocessing as mp
import os
import sys
from fractions import Fraction

import numpy as np

import kickmix as km

T_PER_TOFFOLI = 4
ETA = 218  # Electrons in the benchmark system.
N_P = 10  # Bits per momentum component in the benchmark instance.
MASK64 = (1 << 64) - 1  # The check works in units of 2^-64 turns, as uint64 (mod 1 turn).
DEFAULT_BATCH_SIZE = 256
DEFAULT_SHOTS_PER_X = 64
BATCHES_PER_CHUNK = 64


# Problem specification.


@dataclasses.dataclass(frozen=True)
class ProblemSpecInvSqrt:
    """Specification of the Benchmark I problem instance."""
    width: int
    max_x: int
    beta: Fraction
    precision_bits: int
    shots_per_x: int
    system_qubits: int

    @classmethod
    def for_n_p(
        cls,
        n_p: int,
        *,
        beta: Fraction = Fraction(1),
        precision_bits: int = 24,
        shots_per_x: int = DEFAULT_SHOTS_PER_X,
        eta: int = ETA,
    ) -> ProblemSpecInvSqrt:
        """`x = |nu - nu'|^2` for momenta with components in `[-(2^(n_p-1) - 1), 2^(n_p-1) - 1]`,
        so `x <= 3 (2^n_p - 2)^2 < 2^(2 n_p + 2)`."""
        return cls(
            width=2 * n_p + 2,
            max_x=3 * (2**n_p - 2)**2,
            beta=beta,
            precision_bits=precision_bits,
            shots_per_x=shots_per_x,
            system_qubits=3 * eta * n_p,
        )

    @property
    def num_shots(self) -> int:
        return self.shots_per_x * self.max_x



# Mathematical and cost helpers.


def reference_values(spec: ProblemSpecInvSqrt, xs: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """`target mod 1` and `tol(x)` for each `x` in `xs`.

    Both are uint64 in units of 2^-64 turns, and come exactly from
    `r = floor(2^65 |beta| / sqrt(x)) = isqrt(floor(2^130 beta^2 / x))`: the target is `r`
    rounded to nearest at bit 0, the tolerance is floored and capped at 1/2 turn. Costs ~1 us
    per `x`, so `verify` tabulates all `x` once.
    """
    p, q = spec.beta.numerator, spec.beta.denominator
    num, den, shift, sign = p * p << 130, q * q, spec.precision_bits + 1, 1 if p >= 0 else -1
    rs = [math.isqrt(num // (den * x)) for x in xs.tolist()]
    target = [sign * ((r + 1) >> 1) & MASK64 for r in rs]
    tol = ([min(r >> shift, 1 << 63) for r in rs] if shift >= 0
           else [min(r << -shift, 1 << 63) for r in rs])
    return np.array(target, dtype=np.uint64), np.array(tol, dtype=np.uint64)


def half_turns_to_units(half_turns: int | Fraction) -> int:
    """The nearest multiple of 2^-64 turns (mod 1 turn) to a phase in half turns."""
    n, d = half_turns.as_integer_ratio()
    return (((n << 64) // d + 1) >> 1) & MASK64


def z_pow_class(half_turns: Fraction) -> str:
    if half_turns % Fraction(1, 2) == 0:
        return 'clifford'
    if half_turns % Fraction(1, 4) == 0:
        return 't'
    return 'rotation'


def rotation_t_count(eps: float) -> float:
    return 0.56 * math.log2(1 / eps) + 5.3


def _circuit_sha256(circuit: km.Circuit) -> str:
    """Returns the SHA-256 hex digest of the canonical `.kmb` serialization of `circuit`."""
    buf = io.BytesIO()
    circuit.to_file(buf, format='kmb')
    return hashlib.sha256(buf.getvalue()).hexdigest()


def _initial_seed(circuit_hash: str, salt: str) -> int:
    """Computes the initial RNG seed from `circuit_hash` and optional `salt`."""
    if not salt:
        return int(circuit_hash, 16)
    return int(hashlib.sha256(f'{circuit_hash}{salt}'.encode('utf-8')).hexdigest(), 16)



def to_bits(values: np.ndarray, width: int) -> np.ndarray:
    return (values[None, :] >> np.arange(width, dtype=np.uint64)[:, None]) & 1 == 1


def from_bits(bits: np.ndarray) -> np.ndarray:
    return (bits.astype(np.uint64) << np.arange(len(bits), dtype=np.uint64)[:, None]).sum(axis=0)


# Register validation.


def validate_registers(circuit: km.Circuit, spec: ProblemSpecInvSqrt
                       ) -> tuple[km.array, km.array]:
    """Validates the register schema; returns the `x` and scratch qubits."""
    registers = circuit.register_data
    if len(registers) != circuit.num_registers or list(registers) != ['x']:
        raise ValueError(f'Invalid register schema: {list(registers)}')
    x_reg = list(registers['x'])
    for e in x_reg:
        if not isinstance(e, km.q):
            raise ValueError(f"Register 'x' must contain only qubits, but contains {e!r}.")
    if len(x_reg) != spec.width:
        raise ValueError(f'Expected {spec.width} x qubits, got {len(x_reg)}.')
    io = set(x_reg)
    if len(io) != len(x_reg):
        raise ValueError('The x register must consist of distinct qubits.')
    scratch = km.array([km.q(i) for i in range(circuit.num_qubits) if km.q(i) not in io])
    return km.array(x_reg), scratch


# Shot sampling.


def sample_shots(spec: ProblemSpecInvSqrt, start: int, stop: int) -> np.ndarray:
    """The inputs `x` of shots `start..stop-1`: shot `i` is `x = i mod max_x + 1`."""
    return (np.arange(start, stop, dtype=np.uint64) % np.uint64(spec.max_x)) + np.uint64(1)


# Simulation and verification.


_WORKER_FN = None


def _call_worker(task):
    return _WORKER_FN(task)


def _run_parallel(fn, tasks: list, max_workers: int | None) -> list:
    global _WORKER_FN
    if max_workers is not None and max_workers <= 0:
        raise ValueError(f'max_workers must be positive, got {max_workers}.')
    cpus = getattr(os, 'process_cpu_count', os.cpu_count)() or 1
    workers = min(len(tasks), cpus if max_workers is None else max_workers)
    if workers <= 1 or 'fork' not in mp.get_all_start_methods():
        return [fn(t) for t in tasks]
    _WORKER_FN = fn
    try:
        with concurrent.futures.ProcessPoolExecutor(max_workers=workers, mp_context=mp.get_context('fork')) as pool:
            try:
                return list(pool.map(_call_worker, tasks))
            except Exception:
                pool.shutdown(wait=True, cancel_futures=True)
                raise
    finally:
        _WORKER_FN = None


def verify(circuit: km.Circuit, spec: ProblemSpecInvSqrt, *, seed: int | None = None,
           salt: str = '', batch_size: int = DEFAULT_BATCH_SIZE,
           max_workers: int | None = None) -> dict:
    """Verifies `circuit` on `spec.shots_per_x` shots of every `x`; raises on failure.

    `batch_size` shots are simulated together; it doesn't affect which shots are run.
    """
    if spec.max_x <= 0 or spec.shots_per_x <= 0:
        raise ValueError(f'max_x and shots_per_x must be positive, got {spec.max_x} and {spec.shots_per_x}.')
    if batch_size <= 0:
        raise ValueError(f'batch_size must be positive, got {batch_size}.')
    num_shots = spec.num_shots
    if num_shots % batch_size:
        raise ValueError(f'num_shots must be a multiple of batch_size={batch_size}, got {num_shots}.')

    circuit_hash = _circuit_sha256(circuit)
    x_reg, scratch = validate_registers(circuit, spec)

    # Reference values for every x, indexed by x - 1.
    target, tol = reference_values(spec, np.arange(1, spec.max_x + 1, dtype=np.uint64))
    if spec.beta and tol[-1] < 1 << 16:
        raise ValueError('The tolerance is too small for 64-bit phase arithmetic.')
    base_seed = _initial_seed(circuit_hash, salt) if seed is None else int(seed)

    def run_chunk(task: tuple[int, int, int]) -> tuple[int, tuple[float, int], int, int, int]:
        chunk_start, chunk_stop, sim_seed = task
        sim = km.Simulator(
            batch_size=batch_size,
            debug_print=False,
            counting_operations=True,
            seed=sim_seed,
        )
        min_margin = 1 << 64
        worst = (-1.0, 0)
        for start in range(chunk_start, chunk_stop, batch_size):
            xs = sample_shots(spec, start, start + batch_size)
            sim.clear_for_shot()
            sim.write_across_shots(x_reg, to_bits(xs, spec.width))
            sim.do(circuit)

            if not np.array_equal(from_bits(sim.read_across_shots(x_reg)), xs):
                raise AssertionError('x was not restored.')
            if len(scratch):
                dirty = sim.read_across_shots(scratch).any(axis=1)
                if dirty.any():
                    raise AssertionError(
                        f'Scratch qubit {scratch[int(np.argmax(dirty))]} did not return to |0>.')

            # Tracked phase as uint64 in units of 2^-64 turns, so arithmetic is mod 1 turn.
            theta = np.array([half_turns_to_units(sim.read_shot_phase(i)) for i in range(batch_size)],
                             dtype=np.uint64)
            allowed = tol[xs - np.uint64(1)]
            error = (theta - target[xs - np.uint64(1)]).view(np.int64)  # In [-1/2, 1/2) turns.
            used = np.abs(error).view(np.uint64)  # |-2^63| wraps to -2^63, i.e. 2^63 as uint64.
            bad = np.flatnonzero(used > allowed)
            if len(bad):
                i = bad[0]
                raise AssertionError(f'x={xs[i]}: phase error {error[i] / 2**64:.3e} turns '
                                     f'exceeds tolerance {allowed[i] / 2**64:.3e}.')
            ratio = np.divide(used, allowed, out=np.zeros(batch_size), where=allowed > 0)
            min_margin = min(min_margin, int((allowed - used).min()))
            worst = max(worst, (float(ratio.max()), -int(xs[ratio == ratio.max()].min())))

        stats = sim.operation_statistics()
        return (
            min_margin,
            worst,
            int(stats.num_toffoli_like),
            int(stats.num_t_like),
            int(stats.num_z_pow(min_clifford_hierarchy_level=4)),
        )

    chunk_shots = BATCHES_PER_CHUNK * batch_size
    starts = range(0, num_shots, chunk_shots)
    seeds = np.random.SeedSequence(base_seed, pool_size=8).generate_state(4 * len(starts), dtype=np.uint64).reshape(-1, 4)
    tasks = [(s, min(s + chunk_shots, num_shots), int.from_bytes(seeds[i], 'little')) for i, s in enumerate(starts)]
    results = _run_parallel(run_chunk, tasks, max_workers)

    min_margin = min(r[0] for r in results)  # Smallest `tol(x) - |error|` seen, in units of 2^-64 turns.
    worst = max(r[1] for r in results)  # `(|error| / tol(x), -x)` of the worst shot.

    # Cost. Each rotation may add `2 eps` radians; `n_rot * 2 eps <= 2 pi min_margin`.
    toffoli_count = sum(r[2] for r in results) / num_shots
    t_base = sum(r[3] for r in results) / num_shots
    n_rot = sum(r[4] for r in results) / num_shots
    eps = math.pi * min_margin / 2**64 / n_rot if n_rot else None
    if n_rot and not eps > 0:
        raise AssertionError('No tolerance left for rotation synthesis error.')
    t_count = t_base + (n_rot * rotation_t_count(eps) if n_rot else 0)
    toffolis = toffoli_count + t_count / T_PER_TOFFOLI
    return {
        'status': 'PASS',
        'score': circuit.num_qubits * toffolis,
        'toffoli_equivalent': toffolis,
        'toffoli_count': toffoli_count,
        'max_toffoli_count': circuit.operation_statistics().num_toffoli_like,
        't_count': t_base,
        'rotation_count': n_rot,
        'rotation_eps': eps,
        'num_qubits': circuit.num_qubits,
        'reaction_depth': circuit.reaction_depth(),
        'num_ops': len(circuit),
        'verified_shots': num_shots,
        'worst_error_over_tolerance': worst[0],
        'worst_x': -worst[1],
        'circuit_sha256': circuit_hash,
    }


# CLI.


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('circuit_file', help='Path to a submitted .kmb or .kmx circuit file.')
    parser.add_argument('--format', choices=('auto', 'kmb', 'kmx'), default='auto',
                        help="Input circuit file format (default: 'auto', auto-detects .kmb or .kmx).")
    parser.add_argument('--n-p', type=int, default=N_P,
                        help=f'Bits per momentum component (default: {N_P}).')
    parser.add_argument('--beta', type=Fraction, default=Fraction(1),
                        help='Phase scaling factor beta (default: 1).')
    parser.add_argument('--precision-bits', type=int, default=24,
                        help='Relative precision bits (default: 24).')
    parser.add_argument('--shots-per-x', type=int, default=DEFAULT_SHOTS_PER_X,
                        help=f'Shots per input value x (default: {DEFAULT_SHOTS_PER_X}).')
    parser.add_argument('--eta', type=int, default=ETA,
                        help=f'Number of electrons for system size (default: {ETA}).')
    parser.add_argument('--width', type=int, default=None,
                        help='Register width in bits (default: 2*n_p + 2).')
    parser.add_argument('--max-x', type=int, default=None,
                        help='Maximum input value (default: 3*(2^n_p - 2)^2).')
    parser.add_argument('--system-qubits', type=int, default=None,
                        help='Accompanying system qubits (default: 3*eta*n_p).')
    parser.add_argument('--salt', type=str, default='',
                        help='Optional salt merged with circuit_sha256 to derive the initial seed (default: empty).')
    parser.add_argument('--seed', type=int, default=None,
                        help='Explicit RNG seed overriding circuit_sha256 and --salt.')
    parser.add_argument('--batch-size', type=int, default=DEFAULT_BATCH_SIZE,
                        help=f'Simulator batch size (default: {DEFAULT_BATCH_SIZE}).')
    parser.add_argument('--max-workers', type=int, default=None,
                        help='Maximum worker processes (default: all available CPU cores).')
    args = parser.parse_args()

    n_p = args.n_p
    width = args.width if args.width is not None else 2 * n_p + 2
    max_x = args.max_x if args.max_x is not None else 3 * (2**n_p - 2)**2
    system_qubits = args.system_qubits if args.system_qubits is not None else 3 * args.eta * n_p
    spec = ProblemSpecInvSqrt(
        width=width,
        max_x=max_x,
        beta=args.beta,
        precision_bits=args.precision_bits,
        shots_per_x=args.shots_per_x,
        system_qubits=system_qubits,
    )
    try:
        summary = verify(km.Circuit.from_file(args.circuit_file, format=args.format), spec,
                         seed=args.seed, salt=args.salt, batch_size=args.batch_size,
                         max_workers=args.max_workers)
    except (AssertionError, ValueError, RuntimeError, OSError) as ex:
        print(json.dumps({'status': 'FAIL', 'error': str(ex)}, indent=2))
        sys.exit(1)
    print(json.dumps(summary, indent=2))


if __name__ == '__main__':
    main()
