"""Safe, gate-budgeted circuit-proposal evaluator for HorizonForge.

Example: python candidate_bench.py --proposal proposal.json --cutoff 2 --budget 100
No generated source code is evaluated. The proposal is plain JSON with CNOT edges.
"""

import argparse
import json
from pathlib import Path

import numpy as np
from scipy.optimize import minimize
from scipy.sparse.linalg import eigsh

from gauge_check import gauge_norm_squared, generators
from matrix_vqe_preflight import cnot, hamiltonian, ry


def validate_proposal(raw, qubits):
    if not isinstance(raw, dict) or set(raw) != {"edges"}:
        raise ValueError("proposal must be an object containing only 'edges'")
    edges = raw["edges"]
    if not isinstance(edges, list) or len(edges) != qubits - 1:
        raise ValueError(f"exactly {qubits - 1} CNOT edges per layer required")
    seen = set()
    for edge in edges:
        if (not isinstance(edge, list) or len(edge) != 2
                or any(type(q) is not int or q < 0 or q >= qubits for q in edge)
                or edge[0] == edge[1] or tuple(edge) in seen):
            raise ValueError("edges must be distinct valid [control, target] pairs")
        seen.add(tuple(edge))
    return edges


def circuit(parameters, edges, qubits, depth=2):
    state = np.zeros(1 << qubits)
    state[0] = 1.0
    for layer in range(depth):
        for q in range(qubits):
            state = ry(state, parameters[layer * qubits + q], q, qubits)
        for control, target in edges:
            state = cnot(state, control, target, qubits)
    return state


def evaluate(edges, h, gs, budget, seed, depth=2):
    qubits = int(np.log2(h.shape[0]))
    rng = np.random.default_rng(seed)
    initial = rng.uniform(-0.4, 0.4, qubits * depth)
    best = {"energy": float("inf"), "params": None, "evaluations": 0}

    def objective(params):
        state = circuit(params, edges, qubits, depth)
        energy = float(state @ (h @ state))
        best["evaluations"] += 1
        if energy < best["energy"]:
            best["energy"] = energy
            best["params"] = params.copy()
        return energy

    minimize(objective, initial, method="COBYLA",
             options={"maxiter": budget, "rhobeg": 0.5, "tol": 1e-5})
    state = circuit(best["params"], edges, qubits, depth)
    return {"seed": seed, "energy": best["energy"],
            "gauge_norm_squared": gauge_norm_squared(state, gs),
            "evaluations": best["evaluations"]}


def baseline(qubits, kind):
    half = qubits // 2
    if kind == "ring":
        edges = [[q, q + 1] for q in range(qubits - 1)]
    elif kind == "cross_budget":
        edges = [[q, q + half] for q in range(half)]
        within = [[q, q + 1] for q in range(half - 1)]
        within += [[q, q + 1] for q in range(half, qubits - 1)]
        edges += within[::2][:half - 1]
    else:
        raise ValueError(kind)
    return validate_proposal({"edges": edges}, qubits)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--proposal", type=Path)
    parser.add_argument("--baseline", choices=["ring", "cross_budget"])
    parser.add_argument("--cutoff", type=int, choices=[2, 4], default=2)
    parser.add_argument("--lambda", dest="lam", type=float, default=1.0)
    parser.add_argument("--budget", type=int, default=300)
    parser.add_argument("--seeds", type=int, default=3)
    args = parser.parse_args()
    if (args.proposal is None) == (args.baseline is None):
        parser.error("choose exactly one of --proposal or --baseline")
    if args.budget < 1 or args.seeds < 1 or args.seeds > 50:
        parser.error("budget and seeds must be positive; seeds capped at 50")
    qubits = 6 * int(np.log2(args.cutoff))
    edges = (validate_proposal(json.loads(args.proposal.read_text()), qubits)
             if args.proposal else baseline(qubits, args.baseline))
    h = hamiltonian(args.lam, args.cutoff)
    gs = generators(args.cutoff)
    exact = float(eigsh(h, k=1, which="SA", tol=1e-10)[0][0])
    trials = [evaluate(edges, h, gs, args.budget, seed)
              for seed in range(args.seeds)]
    print(json.dumps({"lambda": args.lam, "cutoff": args.cutoff,
                      "exact_energy": exact, "CNOT_per_layer": len(edges),
                      "RY_parameters": 2 * qubits, "edges": edges,
                      "trials": trials}, indent=2))


if __name__ == "__main__":
    main()
"""Audit concrete claims against saved HorizonForge experiments; no API calls.

The saved search is exploratory, so this audit is a worked example of the
claim-checking workflow, not a blinded discovery or a Meta-model result.
"""

import json
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
from scipy.sparse.linalg import norm

from gauge_check import generators
from matrix_vqe_preflight import hamiltonian


ROOT = Path(__file__).resolve().parent
SOURCE = ROOT / "local_search_results.json"
OUTPUT = ROOT / "claim_audit_results.json"


def median(values):
    return float(np.median(values))


def main():
    source = json.loads(SOURCE.read_text(encoding="utf-8"))
    rows = {(float(row["lambda"]), row["name"]): row for row in source["final"]}
    comparisons = []
    for lam in (0.5, 1.0, 2.0):
        fixed = rows[(lam, "cross_budget")]
        proposed = rows[(lam, "random_04")]
        pairwise = []
        for seed in source["seeds"]:
            a = next(t for t in fixed["trials"] if t["seed"] == seed)
            b = next(t for t in proposed["trials"] if t["seed"] == seed)
            pairwise.append({
                "seed": seed,
                "random_energy_better": b["energy"] < a["energy"],
                "random_gauge_better": b["gauge_norm_squared"] < a["gauge_norm_squared"],
            })
        e_fixed = median([t["energy"] - fixed["exact_energy"] for t in fixed["trials"]])
        e_random = median([t["energy"] - proposed["exact_energy"] for t in proposed["trials"]])
        g_fixed = median([t["gauge_norm_squared"] for t in fixed["trials"]])
        g_random = median([t["gauge_norm_squared"] for t in proposed["trials"]])
        comparisons.append({
            "lambda": lam,
            "fixed_median_energy_error": e_fixed,
            "random_median_energy_error": e_random,
            "random_energy_error_reduction_fraction": (e_fixed - e_random) / e_fixed,
            "fixed_median_gauge_norm_squared": g_fixed,
            "random_median_gauge_norm_squared": g_random,
            "paired_seed_energy_wins": sum(p["random_energy_better"] for p in pairwise),
            "paired_seed_gauge_wins": sum(p["random_gauge_better"] for p in pairwise),
            "paired_seed_details": pairwise,
        })

    # Exact gauge invariance would require [H,G_a] = 0 in this represented space.
    # Finite local Fock truncation does not in general preserve this algebra.
    h = hamiltonian(1.0, 4)
    gs = generators(4)
    commutator_norms = [float(norm(h @ g - g @ h)) for g in gs]
    muse_path = ROOT / "muse_local_results.json"
    muse_results = json.loads(muse_path.read_text(encoding="utf-8")) if muse_path.exists() else None
    physical_path = ROOT / "physical_results.json"
    physical_results = json.loads(physical_path.read_text(encoding="utf-8")) if physical_path.exists() else None
    report = {
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "input": SOURCE.name,
        "provenance": "Exploratory preflight data; no Muse calls; no quantum hardware; noiseless classical simulation.",
        "configuration": {
            "cutoff": 4, "qubits": 12, "cnot_per_layer": 11,
            "rotation_parameters": 24, "optimizer_evaluations_per_seed": source["final_budget"],
            "seeds": source["seeds"],
        },
        "comparisons": comparisons,
        "physics_integrity": {
            "lambda": 1.0,
            "hamiltonian_frobenius_norm": float(norm(h)),
            "commutator_frobenius_norms_H_G": commutator_norms,
            "exact_gauge_symmetry_in_truncated_representation": all(x < 1e-8 for x in commutator_norms),
            "interpretation": "Nonzero [H,G] means the finite-cutoff gauge metric is diagnostic only; it is not a proof of an exact physical-state constraint.",
        },
        "claim_verdicts": [
            {
                "claim": "The random_04 circuit is strictly better than cross_budget on energy and gauge score at all tested couplings.",
                "verdict": "rejected",
                "reason": "Its median gauge score is worse at lambda 0.5 and 1.0, despite lower energy error.",
            },
            {
                "claim": "The cutoff-4 gauge score certifies an exactly gauge-invariant state.",
                "verdict": "rejected",
                "reason": "The truncated Hamiltonian does not commute with the represented gauge generators.",
            },
            ({
                "claim": "The first Muse proposal is the best overall physical circuit.",
                "verdict": "rejected",
                "reason": "In the symmetry-preserving benchmark, it does not have the lowest energy error at lambda 0.5 and has lower singlet projection probability than both controls at all three couplings.",
            } if physical_results else {
                "claim": "Muse-guided search beats matched random search.",
                "verdict": "untested",
                "reason": "The symmetry-preserving comparison is not available yet.",
            }),
            *([{
                "claim": "A guided Muse search process beats a matched-budget random search process.",
                "verdict": "untested",
                "reason": "Only one Muse proposal has been tested; no matched-budget guided search has been run.",
            }] if muse_results else []),
        ],
    }
    if muse_results:
        report["muse_proposal_01"] = muse_results
    if physical_results:
        report["symmetry_preserving_comparison"] = physical_results
    OUTPUT.write_text(json.dumps(report, indent=2), encoding="utf-8")
    print(f"Wrote {OUTPUT}")
    for item in report["claim_verdicts"]:
        print(f"{item['verdict'].upper()}: {item['claim']}")


if __name__ == "__main__":
    main()
"""Adaptive 2-Call Loop Collector (CALL_07 and CALL_08) for Meta Muse Spark 1.3.

Scientific Protocol:
- CALL_07 receives frozen lambda=1.2 benchmark feedback and proposes an ordered 11-CNOT spanning tree.
- A separate step evaluates CALL_07 at training coupling lambda=1.2 (seeds [0,1,2], budget 300, cutoff 4).
  Target coupling lambda=1.7 is strictly untouched and prohibited from this script.
- CALL_08 receives exact CALL_07 edges and measured seed-level training feedback (or validator error),
  and proposes one structural revision.
- Hard safety constraints:
  1. At most one API call dispatched per invocation of `--execute-next`.
  2. Durable attempt markers prevent double-spending or retries across crashes.
  3. Atomic receipt-first write ensures responses and token usage are preserved before proposal generation.
  4. Max 1024 completion tokens, minimal reasoning effort, temp 0.2, max_retries=0, timeout 30s.
  5. Refuses to send CALL_08 before valid CALL_07 feedback (or validation failure) is present.
"""

import argparse
import hashlib
import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

from candidate_bench import validate_proposal

ROOT = Path(__file__).resolve().parent
MODEL = "muse-spark-1.3"
OUTPUT_DIR = ROOT / "muse_collection"

SCHEMA = {
    "type": "json_schema",
    "json_schema": {
        "name": "circuit_topology",
        "schema": {
            "type": "object",
            "properties": {
                "edges": {
                    "type": "array",
                    "items": {
                        "type": "array",
                        "items": {"type": "integer"},
                    },
                },
            },
            "required": ["edges"],
            "additionalProperties": False,
        },
    },
}

# Reference block chains for novelty / distance auditing
CRITIQUE_BLOCK_CHAIN_EDGES = [
    [0, 1], [1, 2], [2, 3], [3, 4], [4, 5],
    [6, 7], [7, 8], [8, 9], [9, 10], [10, 11],
    [2, 8]
]

HANDCODED_BLOCK_CHAIN_EDGES = [
    [0, 1], [1, 2], [2, 3], [3, 4], [4, 5],
    [6, 7], [7, 8], [8, 9], [9, 10], [10, 11],
    [0, 6]
]

# FROZEN CALL_07 PROMPT
CALL_07_PROMPT = (
    "Design an ordered 11-CNOT topology for a two-layer 12-qubit RY+CNOT "
    "variational circuit for an SU(2) two-matrix bosonic model. Qubits 0-5 "
    "encode X1, qubits 6-11 encode X2. A strict validator requires 11 distinct "
    "directed [control,target] edges whose undirected graph is a connected, "
    "acyclic spanning tree. The tree itself does not guarantee gauge symmetry; "
    "the simulator projects onto the exact singlet sector. At lambda=1.2, "
    "three-seed medians under 300 optimizer evaluations per seed were: initial "
    "Muse ladder energy error 0.021138, singlet probability 0.1225, utility "
    "4.6879; critique-guided Muse block chain with bridge [2,8] energy error "
    "0.000031, singlet probability 0.2437, utility 48.4338; hand-coded block "
    "chain with bridge [0,6] energy error 0.000154, singlet probability 0.2709, "
    "utility 52.5732; best random control energy error 0.000630, singlet "
    "probability 0.2525, utility 44.8543. Both block chains have intra-X1 "
    "edges [0,1],[1,2],[2,3],[3,4],[4,5] and intra-X2 edges "
    "[6,7],[7,8],[8,9],[9,10],[10,11]. Propose a structural alternative that "
    "tests a genuinely different way to balance low energy error and high "
    "singlet overlap. Prefer at least two undirected edge changes versus both "
    "block chains; do not merely change CNOT direction or edge order. Return "
    "only a JSON object with one key, edges, containing the ordered 11 pairs."
)

# FROZEN CALL_08 TEMPLATES
CALL_08_VALID_TEMPLATE = (
    "Your previous valid 12-qubit tree was {EDGES_JSON}. At lambda=1.2, total "
    "occupation <=4, seeds [0,1,2], 300 COBYLA evaluations each, its measured "
    "trials were {TRIALS_JSON}. Its median energy error was {DELTA_E}, median "
    "singlet probability {P_PHYS}, and regularized utility {UTILITY}. The "
    "hand-coded block chain reference had energy error 0.000154, singlet "
    "probability 0.2709, utility 52.5732. Diagnose the observed tradeoff and "
    "propose one revised ordered 11-CNOT spanning tree for the same 12-qubit "
    "two-layer RY+CNOT circuit. The tree must be connected, acyclic, and have "
    "11 distinct directed edges. Seek a structural change, ideally at least "
    "two undirected edge changes versus your previous tree. Return only JSON "
    "with key edges and 11 pairs. Do not infer gauge symmetry from graph shape."
)

CALL_08_INVALID_TEMPLATE = (
    "Your previous proposal {RAW_RESPONSE} failed strict "
    "tree validation: {VALIDATION_ERROR}. Correct the structural error and return "
    "one valid 11-edge spanning tree in JSON with only key edges."
)


def compute_sha256(filepath):
    p = Path(filepath)
    if not p.exists():
        return None
    return hashlib.sha256(p.read_bytes()).hexdigest()


def atomic_write_json(filepath, data):
    """Write JSON atomically via temporary file and replace."""
    target = Path(filepath)
    target.parent.mkdir(parents=True, exist_ok=True)
    temp_file = target.with_suffix(f".tmp_{os.getpid()}_{time.time_ns()}")
    temp_file.write_text(json.dumps(data, indent=2), encoding="utf-8")
    temp_file.replace(target)


def get_api_key():
    key = os.getenv("MODEL_API_KEY")
    if not key:
        env_file = ROOT / ".env"
        if env_file.exists():
            for line in env_file.read_text(encoding="utf-8").splitlines():
                if line.startswith("MODEL_API_KEY="):
                    key = line.split("=", 1)[1].strip()
                    break
    return key


def validate_tree(raw, qubits=12):
    """Enforces valid format, exactly qubits-1 edges, connected spanning tree (acyclic)."""
    edges = validate_proposal(raw, qubits)
    parent = list(range(qubits))

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    for control, target in edges:
        a, b = find(control), find(target)
        if a == b:
            raise ValueError("undirected CNOT graph contains a cycle or repeated edge")
        parent[a] = b
    if len({find(node) for node in range(qubits)}) != 1:
        raise ValueError("CNOT graph is disconnected")
    return edges


def compute_undirected_distance(edges_a, edges_b):
    """Computes the number of undirected edge changes between two 11-edge spanning trees."""
    set_a = {tuple(sorted(e)) for e in edges_a}
    set_b = {tuple(sorted(e)) for e in edges_b}
    return len(set_a - set_b)


def format_call08_prompt_valid(edges, trials, median_error, median_overlap, utility):
    """Formats the CALL_08 prompt for a valid CALL_07 candidate."""
    edges_str = json.dumps(edges)
    trials_str = json.dumps(trials)
    delta_e_str = f"{median_error:.6f}" if isinstance(median_error, (int, float)) else str(median_error)
    p_phys_str = f"{median_overlap:.4f}" if isinstance(median_overlap, (int, float)) else str(median_overlap)
    utility_str = f"{utility:.4f}" if isinstance(utility, (int, float)) else str(utility)

    return CALL_08_VALID_TEMPLATE.format(
        EDGES_JSON=edges_str,
        TRIALS_JSON=trials_str,
        DELTA_E=delta_e_str,
        P_PHYS=p_phys_str,
        UTILITY=utility_str,
    )


def format_call08_prompt_invalid(raw_response, validation_error):
    """Formats the CALL_08 prompt for an invalid CALL_07 candidate."""
    return CALL_08_INVALID_TEMPLATE.format(
        RAW_RESPONSE=str(raw_response).strip(),
        VALIDATION_ERROR=str(validation_error).strip(),
    )


def execute_call(call_id, candidate_id, prompt_text, client, output_dir=OUTPUT_DIR,
                 crash_before_receipt=False, temperature=0.2, max_completion_tokens=1024,
                 reasoning_effort="minimal"):
    """Dispatches a single API call with durable attempt marker and atomic receipt write."""
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    marker_file = output_dir / f"{call_id}.attempt_marker"
    receipt_file = output_dir / f"{call_id}_receipt.json"

    # 1. Check if receipt already exists
    if receipt_file.exists():
        try:
            return json.loads(receipt_file.read_text(encoding="utf-8")), "ALREADY_COMPLETED"
        except Exception:
            pass

    # 2. Check if attempt marker exists
    if marker_file.exists():
        marker_data = {}
        try:
            marker_data = json.loads(marker_file.read_text(encoding="utf-8"))
        except Exception:
            pass
        print(f"  [SAFETY STOP] Attempt marker found for {call_id} from {marker_data.get('timestamp_utc')}. Outcome unknown. Refusing automatic retry.")
        return {
            "call_id": call_id,
            "candidate_id": candidate_id,
            "status": "UNKNOWN_ATTEMPT_STOPPED",
            "validation": {"verdict": "ABORTED_PREVENT_DOUBLE_SPEND"},
            "marker_info": marker_data,
        }, "MARKER_EXISTS"

    # 3. Create durable attempt marker EXCLUSIVELY before dispatching
    marker_payload = {
        "call_id": call_id,
        "candidate_id": candidate_id,
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "status": "DISPATCHED_AWAITING_RESPONSE",
        "model": MODEL,
    }
    try:
        with open(marker_file, "x", encoding="utf-8") as f:
            f.write(json.dumps(marker_payload, indent=2))
            f.flush()
            os.fsync(f.fileno())
    except FileExistsError:
        marker_data = {}
        try:
            marker_data = json.loads(marker_file.read_text(encoding="utf-8"))
        except Exception:
            pass
        print(f"  [SAFETY STOP] Attempt marker collision for {call_id}. Refusing automatic retry.")
        return {
            "call_id": call_id,
            "candidate_id": candidate_id,
            "status": "UNKNOWN_ATTEMPT_STOPPED",
            "validation": {"verdict": "ABORTED_PREVENT_DOUBLE_SPEND"},
            "marker_info": marker_data,
        }, "MARKER_EXISTS"

    # 4. Dispatch call
    t0 = time.time()
    call_ts = datetime.now(timezone.utc).isoformat()
    receipt = {
        "call_id": call_id,
        "candidate_id": candidate_id,
        "timestamp_utc": call_ts,
        "model": MODEL,
        "temperature": temperature,
        "max_completion_tokens": max_completion_tokens,
        "reasoning_effort": reasoning_effort,
        "prompt_text": prompt_text,
    }

    try:
        response = client.chat.completions.create(
            model=MODEL,
            messages=[{"role": "user", "content": prompt_text}],
            response_format=SCHEMA,
            max_completion_tokens=max_completion_tokens,
            reasoning_effort=reasoning_effort,
            temperature=temperature,
        )
        elapsed = round(time.time() - t0, 2)
        usage = response.usage
        choice = response.choices[0]
        raw_content = choice.message.content
        finish_reason = choice.finish_reason

        receipt["elapsed_seconds"] = elapsed
        receipt["prompt_tokens"] = usage.prompt_tokens if usage else None
        receipt["completion_tokens"] = usage.completion_tokens if usage else None
        receipt["total_tokens"] = usage.total_tokens if usage else None
        details = getattr(usage, "completion_tokens_details", None) if usage else None
        receipt["reasoning_tokens"] = getattr(details, "reasoning_tokens", None)
        receipt["finish_reason"] = finish_reason
        receipt["raw_response"] = raw_content

        # Simulated crash point for offline testing
        if crash_before_receipt:
            raise RuntimeError("SIMULATED_CRASH_BEFORE_RECEIPT")

        # Tree validation
        valid_edges = None
        try:
            parsed = json.loads(raw_content)
            valid_edges = validate_tree(parsed, 12)
            dist_critique = compute_undirected_distance(valid_edges, CRITIQUE_BLOCK_CHAIN_EDGES)
            dist_handcoded = compute_undirected_distance(valid_edges, HANDCODED_BLOCK_CHAIN_EDGES)

            receipt["validation"] = {
                "verdict": "PASSED",
                "edges_count": len(valid_edges),
                "is_spanning_tree": True,
                "edges": valid_edges,
                "undirected_distance_from_critique_chain": dist_critique,
                "undirected_distance_from_handcoded_chain": dist_handcoded,
            }
        except Exception as ve:
            receipt["validation"] = {
                "verdict": "FAILED",
                "error": str(ve),
            }

        # 5. ATOMIC WRITE OF RECEIPT FIRST
        atomic_write_json(receipt_file, receipt)

        # 6. Save proposal JSON only if validation passed
        if valid_edges is not None:
            prop_file = output_dir / f"{candidate_id}.json"
            atomic_write_json(prop_file, {"edges": valid_edges})

        return receipt, "EXECUTED"

    except Exception as e:
        if isinstance(e, RuntimeError) and str(e) == "SIMULATED_CRASH_BEFORE_RECEIPT":
            raise
        receipt["elapsed_seconds"] = round(time.time() - t0, 2)
        receipt["error"] = str(e)
        receipt["validation"] = {"verdict": "CALL_ERROR"}
        atomic_write_json(receipt_file, receipt)
        return receipt, "CALL_ERROR"


def evaluate_call07_training(output_dir=OUTPUT_DIR):
    """Performs the exploratory training evaluation of CALL_07 at lambda=1.2.
    
    Prohibits evaluation of lambda=1.7.
    """
    output_dir = Path(output_dir)
    receipt_file = output_dir / "CALL_07_receipt.json"
    feedback_file = output_dir / "CALL_07_training_feedback.json"
    proposal_file = output_dir / "muse_adaptive_07.json"

    if not receipt_file.exists():
        print(f"ERROR: Cannot evaluate CALL_07. Receipt file not found: {receipt_file}")
        return None

    receipt = json.loads(receipt_file.read_text(encoding="utf-8"))
    val = receipt.get("validation", {})
    if val.get("verdict") != "PASSED":
        print(f"ERROR: CALL_07 did not pass tree validation (verdict={val.get('verdict')}). Cannot evaluate.")
        return None

    edges = val.get("edges")
    if not edges:
        print("ERROR: No valid edges found in CALL_07 receipt.")
        return None

    if not proposal_file.exists() or json.loads(proposal_file.read_text(encoding="utf-8")).get("edges") != edges:
        raise RuntimeError("CALL_07 proposal file is missing or differs from its receipt")

    receipt_hash = compute_sha256(receipt_file)
    proposal_hash = compute_sha256(proposal_file)
    if feedback_file.exists():
        saved = json.loads(feedback_file.read_text(encoding="utf-8"))
        if saved.get("source_receipt_sha256") != receipt_hash or saved.get("source_proposal_sha256") != proposal_hash:
            raise RuntimeError("Saved CALL_07 feedback does not match the current receipt and proposal")
        print("Training feedback already exists and matches CALL_07 inputs; no simulation rerun.")
        return saved

    print(f"Evaluating CALL_07 at training coupling lambda=1.2 (seeds=[0,1,2], budget=300, cutoff=4)...")
    from evaluate_physical import evaluate
    result = evaluate(edges=edges, lam=1.2, max_total=4, seeds=[0, 1, 2], budget=300)

    # Compute regularized utility S = P_phys / (Delta_E + 0.005)
    med_err = result["median_energy_error"]
    med_p = result["median_singlet_overlap_probability"]
    utility = med_p / (med_err + 0.005)
    result["regularized_utility"] = utility
    result["call_id"] = "CALL_07"
    result["candidate_id"] = "muse_adaptive_07"
    result["timestamp_utc"] = datetime.now(timezone.utc).isoformat()
    result["source_receipt_sha256"] = receipt_hash
    result["source_proposal_sha256"] = proposal_hash
    result["evaluator_sha256"] = compute_sha256(ROOT / "evaluate_physical.py")

    atomic_write_json(feedback_file, result)
    print(f"Training evaluation complete. Saved to {feedback_file}")
    print(f"  Median Energy Error: {med_err:.6f}")
    print(f"  Median Singlet Probability: {med_p:.4f}")
    print(f"  Regularized Utility: {utility:.4f}")
    return result


def inspect_status(output_dir=OUTPUT_DIR):
    """Reports status of the adaptive 2-call loop without sending calls."""
    output_dir = Path(output_dir)
    c7_marker = output_dir / "CALL_07.attempt_marker"
    c7_receipt = output_dir / "CALL_07_receipt.json"
    c7_feedback = output_dir / "CALL_07_training_feedback.json"
    c8_marker = output_dir / "CALL_08.attempt_marker"
    c8_receipt = output_dir / "CALL_08_receipt.json"

    print("=== Adaptive Muse Loop Status (Lambda=1.2 Training / Lambda=1.7 Holdout Prep) ===")
    print(f"Output directory: {output_dir}")

    # CALL_07
    if c7_receipt.exists():
        r7 = json.loads(c7_receipt.read_text(encoding="utf-8"))
        v7 = r7.get("validation", {}).get("verdict", "UNKNOWN")
        print(f"CALL_07: COMPLETED (verdict={v7}, tokens={r7.get('total_tokens')})")
    elif c7_marker.exists():
        print("CALL_07: IN-FLIGHT / UNKNOWN ATTEMPT (attempt marker exists, no receipt). Refusing automatic dispatch.")
    else:
        print("CALL_07: PENDING (not yet dispatched)")

    # Training feedback
    if c7_feedback.exists():
        fb = json.loads(c7_feedback.read_text(encoding="utf-8"))
        print(f"Training Feedback (lambda=1.2): AVAILABLE (utility={fb.get('regularized_utility', 0.0):.4f})")
    else:
        print("Training Feedback (lambda=1.2): NOT EVALUATED")

    # CALL_08
    if c8_receipt.exists():
        r8 = json.loads(c8_receipt.read_text(encoding="utf-8"))
        v8 = r8.get("validation", {}).get("verdict", "UNKNOWN")
        print(f"CALL_08: COMPLETED (verdict={v8}, tokens={r8.get('total_tokens')})")
    elif c8_marker.exists():
        print("CALL_08: IN-FLIGHT / UNKNOWN ATTEMPT (attempt marker exists, no receipt). Refusing automatic dispatch.")
    else:
        print("CALL_08: PENDING (not yet dispatched)")

    print("Target Holdout Coupling (lambda=1.7): UNTOUCHED (prohibited from this script)")


def execute_next(client, output_dir=OUTPUT_DIR, crash_before_receipt=False):
    """Dispatches at most ONE pending call in the adaptive sequence."""
    output_dir = Path(output_dir)
    c7_marker = output_dir / "CALL_07.attempt_marker"
    c7_receipt = output_dir / "CALL_07_receipt.json"
    c7_feedback = output_dir / "CALL_07_training_feedback.json"
    c8_marker = output_dir / "CALL_08.attempt_marker"
    c8_receipt = output_dir / "CALL_08_receipt.json"

    # Step 1: Check CALL_07
    if not c7_receipt.exists():
        if c7_marker.exists():
            print("[SAFETY STOP] CALL_07 attempt marker exists without receipt. Outcome unknown. Stop for Codex review.")
            return None, "MARKER_EXISTS_CALL07"
        print("[DISPATCHING CALL_07] Sending initial adaptive proposal request...")
        rec, act = execute_call(
            call_id="CALL_07",
            candidate_id="muse_adaptive_07",
            prompt_text=CALL_07_PROMPT,
            client=client,
            output_dir=output_dir,
            crash_before_receipt=crash_before_receipt,
            temperature=0.2,
            max_completion_tokens=1024,
            reasoning_effort="minimal",
        )
        print(f"CALL_07 finished. Action={act}, Verdict={rec.get('validation', {}).get('verdict')}")
        return rec, "DISPATCHED_CALL07"

    # CALL_07 is completed. Inspect verdict.
    r7 = json.loads(c7_receipt.read_text(encoding="utf-8"))
    val7 = r7.get("validation", {})
    verdict7 = val7.get("verdict")

    if verdict7 == "CALL_ERROR":
        print("[SAFETY STOP] CALL_07 encountered an API/network error. Outcome uncertain. Stop for Codex review.")
        return None, "STOPPED_CALL07_ERROR"
    if r7.get("finish_reason") == "length" or r7.get("raw_response") is None:
        print("[SAFETY STOP] CALL_07 exhausted its completion budget without usable content. CALL_08 remains unused.")
        return None, "STOPPED_CALL07_INCOMPLETE"

    # Step 2: Check CALL_08
    if c8_receipt.exists():
        print("[ALL CALLS COMPLETED] Both CALL_07 and CALL_08 have completed receipts. Zero calls dispatched.")
        return json.loads(c8_receipt.read_text(encoding="utf-8")), "ALL_COMPLETED"

    if c8_marker.exists():
        print("[SAFETY STOP] CALL_08 attempt marker exists without receipt. Stop for Codex review.")
        return None, "MARKER_EXISTS_CALL08"

    # Determine CALL_08 prompt payload
    if verdict7 == "PASSED":
        if not c7_feedback.exists():
            print("[GATE STOP] CALL_07 passed validation, but lambda=1.2 training feedback is not yet available.")
            print("Run with `--evaluate-call07` to compute training feedback before dispatching CALL_08.")
            return None, "AWAITING_TRAINING_FEEDBACK"

        fb = json.loads(c7_feedback.read_text(encoding="utf-8"))
        if (fb.get("call_id") != "CALL_07" or fb.get("candidate_id") != "muse_adaptive_07"
                or fb.get("lambda") != 1.2 or fb.get("max_total_occupation") != 4
                or fb.get("source_receipt_sha256") != compute_sha256(c7_receipt)
                or [t.get("seed") for t in fb.get("trials", [])] != [0, 1, 2]
                or any(t.get("evaluations") != 300 for t in fb.get("trials", []))):
            print("[SAFETY STOP] CALL_07 feedback is incomplete or does not match the frozen training protocol.")
            return None, "INVALID_TRAINING_FEEDBACK"
        c8_prompt = format_call08_prompt_valid(
            edges=val7.get("edges", []),
            trials=fb.get("trials", []),
            median_error=fb.get("median_energy_error", 0.0),
            median_overlap=fb.get("median_singlet_overlap_probability", 0.0),
            utility=fb.get("regularized_utility", 0.0),
        )
    elif verdict7 == "FAILED":
        print("[REVISION PATH] CALL_07 failed strict tree validation. Formatting structural correction prompt for CALL_08...")
        c8_prompt = format_call08_prompt_invalid(
            raw_response=r7.get("raw_response", ""),
            validation_error=val7.get("error", "Unknown validation error"),
        )
    else:
        print(f"[SAFETY STOP] CALL_07 has unexpected verdict: {verdict7}. Stop for Codex review.")
        return None, "UNEXPECTED_VERDICT_CALL07"

    print("[DISPATCHING CALL_08] Sending adaptive revision request...")
    rec, act = execute_call(
        call_id="CALL_08",
        candidate_id="muse_adaptive_08",
        prompt_text=c8_prompt,
        client=client,
        output_dir=output_dir,
        crash_before_receipt=crash_before_receipt,
        temperature=0.2,
        max_completion_tokens=1024,
        reasoning_effort="minimal",
    )
    print(f"CALL_08 finished. Action={act}, Verdict={rec.get('validation', {}).get('verdict')}")
    return rec, "DISPATCHED_CALL08"


def main():
    parser = argparse.ArgumentParser(description="Adaptive 2-call capped loop collector for Meta Muse Spark 1.3.")
    parser.add_argument("--dry-run", action="store_true", help="Inspect status and next action with zero network calls.")
    parser.add_argument("--execute-next", action="store_true", help="Authorize sending at most ONE pending API call.")
    parser.add_argument("--evaluate-call07", action="store_true", help="Locally evaluate CALL_07 at lambda=1.2 only (prohibits lambda=1.7).")
    args = parser.parse_args()

    out_dir = OUTPUT_DIR
    out_dir.mkdir(parents=True, exist_ok=True)

    if args.dry_run or (not args.execute_next and not args.evaluate_call07):
        inspect_status(output_dir=out_dir)
        print("\nPass --execute-next to dispatch at most one eligible call, or --evaluate-call07 to evaluate CALL_07.")
        return

    if args.evaluate_call07:
        evaluate_call07_training(output_dir=out_dir)
        return

    if args.execute_next:
        key = get_api_key()
        if not key:
            print("ERROR: MODEL_API_KEY not found in environment or .env.", file=sys.stderr)
            sys.exit(1)

        from openai import OpenAI
        client = OpenAI(base_url="https://api.meta.ai/v1", api_key=key, max_retries=0, timeout=30)
        execute_next(client, output_dir=out_dir)


if __name__ == "__main__":
    main()
"""Pre-declared, executable 3-call capped collector for Meta Muse Spark 1.3 proposals.

Strict collection safeguards:
1. Hard call cap: Exactly 3 HTTP calls maximum; zero automatic retries (max_retries=0, timeout=30).
2. Durable attempt markers: Before each HTTP request, an exclusive attempt marker is created.
   On restart, if a marker or receipt exists, that call ID is never re-sent.
3. Crash resilience: If execution stops after dispatching but before receipt write, outcome is marked
   unknown / in-flight and never automatically retried.
4. Atomic receipt write: The response receipt is written to disk before proposal files are created.
5. All token usage and finish reasons are preserved even for invalid responses.
6. Manifest generation: Writes model_cohort_manifest.json with file SHA256 hashes.
"""

import argparse
import hashlib
import json
import os
import sys
import tempfile
import time
from datetime import datetime, timezone
from pathlib import Path

from candidate_bench import validate_proposal

ROOT = Path(__file__).resolve().parent
MODEL = "muse-spark-1.3"
OUTPUT_DIR = ROOT / "muse_collection"

SCHEMA = {
    "type": "json_schema",
    "json_schema": {
        "name": "circuit_topology",
        "schema": {
            "type": "object",
            "properties": {
                "edges": {
                    "type": "array",
                    "items": {
                        "type": "array",
                        "items": {"type": "integer"},
                    },
                },
            },
            "required": ["edges"],
            "additionalProperties": False,
        },
    },
}

# EXACT FROZEN PROMPT PAYLOADS (3 CALLS) - FIXED TOPOLOGY-DIVERSITY BATCH
PROMPT_SPECS = [
    {
        "call_id": "CALL_04",
        "candidate_id": "muse_cand_03",
        "model": MODEL,
        "temperature": 0.2,
        "max_completion_tokens": 1024,
        "reasoning_effort": "minimal",
        "prompt_text": (
            "You are designing a 12-qubit, two-layer variational quantum circuit topology for an "
            "SU(2) two-matrix model. Qubits 0-5 encode matrix X1 modes; qubits 6-11 encode matrix X2 modes. "
            "Each layer applies RY on all 12 qubits, followed by the same ordered sequence of exactly 11 "
            "directed CNOT edges.\n\n"
            "TOPOLOGY GOAL - DUAL HUB STRUCTURE:\n"
            "Explore an ansatz where each matrix register (qubits 0-5 and qubits 6-11) is organized around "
            "an internal hub node (e.g. qubit 0 connects to 1,2,3,4,5, and qubit 6 connects to 7,8,9,10,11), "
            "with a single inter-matrix bridge between the registers. The undirected edges must form a "
            "connected spanning tree over all 12 qubits (no cycles, exactly 11 distinct edges, no self-edges).\n\n"
            "Return only the JSON object with the 'edges' array; no explanatory prose."
        )
    },
    {
        "call_id": "CALL_05",
        "candidate_id": "muse_cand_04",
        "model": MODEL,
        "temperature": 0.2,
        "max_completion_tokens": 1024,
        "reasoning_effort": "minimal",
        "prompt_text": (
            "You are designing a 12-qubit, two-layer variational quantum circuit topology for an "
            "SU(2) two-matrix model. Qubits 0-5 encode matrix X1 modes; qubits 6-11 encode matrix X2 modes. "
            "Each layer applies RY on all 12 qubits, followed by the same ordered sequence of exactly 11 "
            "directed CNOT edges.\n\n"
            "TOPOLOGY GOAL - DISTRIBUTED BRIDGES:\n"
            "Explore a tree topology with multiple short inter-matrix bridges between matrix X1 (qubits 0-5) "
            "and matrix X2 (qubits 6-11), connecting color modes across registers while maintaining a strict "
            "tree (acyclic, exactly 11 distinct edges, connected across all 12 qubits).\n\n"
            "Return only the JSON object with the 'edges' array; no explanatory prose."
        )
    },
    {
        "call_id": "CALL_06",
        "candidate_id": "muse_cand_05",
        "model": MODEL,
        "temperature": 0.4,
        "max_completion_tokens": 1024,
        "reasoning_effort": "minimal",
        "prompt_text": (
            "You are designing a 12-qubit, two-layer variational quantum circuit topology for an "
            "SU(2) two-matrix model. Qubits 0-5 encode matrix X1 modes; qubits 6-11 encode matrix X2 modes. "
            "Each layer applies RY on all 12 qubits, followed by the same ordered sequence of exactly 11 "
            "directed CNOT edges.\n\n"
            "TOPOLOGY GOAL - EXPLORATORY ANSATZ:\n"
            "Design an exploratory 11-CNOT spanning tree that balances intra-matrix entanglement within "
            "X1 and X2 with inter-matrix correlations. The undirected edges must form a connected spanning "
            "tree over all 12 qubits (no cycles, exactly 11 distinct edges, no self-edges).\n\n"
            "Return only the JSON object with the 'edges' array; no explanatory prose."
        )
    }
]


def compute_sha256(filepath):
    p = Path(filepath)
    if not p.exists():
        return None
    return hashlib.sha256(p.read_bytes()).hexdigest()


def atomic_write_json(filepath, data):
    """Write JSON atomically via temporary file and replace."""
    target = Path(filepath)
    temp_dir = target.parent
    temp_dir.mkdir(parents=True, exist_ok=True)
    temp_file = target.with_suffix(f".tmp_{os.getpid()}_{time.time_ns()}")
    temp_file.write_text(json.dumps(data, indent=2), encoding="utf-8")
    temp_file.replace(target)


def get_api_key():
    key = os.getenv("MODEL_API_KEY")
    if not key:
        env_file = ROOT / ".env"
        if env_file.exists():
            for line in env_file.read_text(encoding="utf-8").splitlines():
                if line.startswith("MODEL_API_KEY="):
                    key = line.split("=", 1)[1].strip()
                    break
    return key


def validate_tree(raw, qubits=12):
    """Enforces valid format, exactly qubits-1 edges, connected spanning tree (acyclic)."""
    edges = validate_proposal(raw, qubits)
    parent = list(range(qubits))

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    for control, target in edges:
        a, b = find(control), find(target)
        if a == b:
            raise ValueError("undirected CNOT graph contains a cycle or repeated edge")
        parent[a] = b
    if len({find(node) for node in range(qubits)}) != 1:
        raise ValueError("CNOT graph is disconnected")
    return edges


def execute_call(spec, client, output_dir=OUTPUT_DIR, crash_before_receipt=False):
    call_id = spec["call_id"]
    cand_id = spec["candidate_id"]
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    marker_file = output_dir / f"{call_id}.attempt_marker"
    receipt_file = output_dir / f"{call_id}_receipt.json"

    # 1. Check if receipt already exists
    if receipt_file.exists():
        try:
            return json.loads(receipt_file.read_text(encoding="utf-8")), "ALREADY_COMPLETED"
        except Exception:
            pass

    # 2. Check if attempt marker exists (fast path check)
    if marker_file.exists():
        marker_data = {}
        try:
            marker_data = json.loads(marker_file.read_text(encoding="utf-8"))
        except Exception:
            pass
        print(f"  [SAFETY STOP] Attempt marker found for {call_id} from {marker_data.get('timestamp_utc')}. Outcome unknown / call previously dispatched. Refusing automatic retry.")
        return {
            "call_id": call_id,
            "candidate_id": cand_id,
            "status": "UNKNOWN_ATTEMPT_STOPPED",
            "validation": {"verdict": "ABORTED_PREVENT_DOUBLE_SPEND"},
            "marker_info": marker_data
        }, "MARKER_EXISTS"

    # 3. Create durable attempt marker EXCLUSIVELY before dispatching HTTP request
    marker_payload = {
        "call_id": call_id,
        "candidate_id": cand_id,
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "status": "DISPATCHED_AWAITING_RESPONSE",
        "model": spec["model"]
    }
    try:
        with open(marker_file, "x", encoding="utf-8") as f:
            f.write(json.dumps(marker_payload, indent=2))
            f.flush()
            os.fsync(f.fileno())
    except FileExistsError:
        marker_data = {}
        try:
            marker_data = json.loads(marker_file.read_text(encoding="utf-8"))
        except Exception:
            pass
        print(f"  [SAFETY STOP] Attempt marker found for {call_id} from {marker_data.get('timestamp_utc')}. Outcome unknown / call previously dispatched. Refusing automatic retry.")
        return {
            "call_id": call_id,
            "candidate_id": cand_id,
            "status": "UNKNOWN_ATTEMPT_STOPPED",
            "validation": {"verdict": "ABORTED_PREVENT_DOUBLE_SPEND"},
            "marker_info": marker_data
        }, "MARKER_EXISTS"

    # 4. Dispatch call
    t0 = time.time()
    call_ts = datetime.now(timezone.utc).isoformat()
    receipt = {
        "call_id": call_id,
        "candidate_id": cand_id,
        "timestamp_utc": call_ts,
        "model": spec["model"],
        "temperature": spec["temperature"],
        "max_completion_tokens": spec["max_completion_tokens"],
        "prompt_text": spec["prompt_text"],
    }

    try:
        response = client.chat.completions.create(
            model=spec["model"],
            messages=[{"role": "user", "content": spec["prompt_text"]}],
            response_format=SCHEMA,
            max_completion_tokens=spec["max_completion_tokens"],
            reasoning_effort=spec["reasoning_effort"],
            temperature=spec["temperature"],
        )
        elapsed = round(time.time() - t0, 2)
        usage = response.usage
        choice = response.choices[0]
        raw_content = choice.message.content
        finish_reason = choice.finish_reason

        receipt["elapsed_seconds"] = elapsed
        receipt["prompt_tokens"] = usage.prompt_tokens if usage else None
        receipt["completion_tokens"] = usage.completion_tokens if usage else None
        receipt["total_tokens"] = usage.total_tokens if usage else None
        receipt["finish_reason"] = finish_reason
        receipt["raw_response"] = raw_content

        # Simulated crash point for offline testing: raises without writing receipt
        if crash_before_receipt:
            raise RuntimeError("SIMULATED_CRASH_BEFORE_RECEIPT")

        # Tree validation
        valid_edges = None
        try:
            parsed = json.loads(raw_content)
            valid_edges = validate_tree(parsed, 12)
            receipt["validation"] = {
                "verdict": "PASSED",
                "edges_count": len(valid_edges),
                "is_spanning_tree": True,
                "edges": valid_edges
            }
        except Exception as ve:
            receipt["validation"] = {
                "verdict": "FAILED",
                "error": str(ve)
            }

        # 5. ATOMIC WRITE OF RECEIPT FIRST
        atomic_write_json(receipt_file, receipt)

        # 6. Save proposal JSON only if validation passed
        if valid_edges is not None:
            prop_file = output_dir / f"{cand_id}.json"
            atomic_write_json(prop_file, {"edges": valid_edges})

        # Keep the exclusive marker immutable. The receipt records completion;
        # replacing an open marker can fail on Windows while another runner reads it.
        return receipt, "EXECUTED"

    except Exception as e:
        if isinstance(e, RuntimeError) and str(e) == "SIMULATED_CRASH_BEFORE_RECEIPT":
            raise
        receipt["elapsed_seconds"] = round(time.time() - t0, 2)
        receipt["error"] = str(e)
        receipt["validation"] = {"verdict": "CALL_ERROR"}
        atomic_write_json(receipt_file, receipt)
        # Keep the marker in place even when receipt writing fails. It prevents
        # an uncertain attempt from being dispatched again on restart.
        return receipt, "CALL_ERROR"


def verify_candidate_integrity(prop_file, rec_file, qubits=12):
    """Verifies that proposal and receipt both exist, proposal forms a valid tree,
    and proposal edges strictly equal the receipt's recorded edges.
    Returns (True, edges) on success, or (False, reason) on failure.
    """
    if prop_file is None or rec_file is None:
        return False, "File path is None"
    p_path = Path(prop_file)
    r_path = Path(rec_file)
    if not p_path.is_file():
        return False, f"Proposal file not found: {p_path}"
    if not r_path.is_file():
        return False, f"Receipt file not found: {r_path}"

    try:
        prop_data = json.loads(p_path.read_text(encoding="utf-8"))
        prop_edges = validate_tree(prop_data, qubits)
    except Exception as e:
        return False, f"Proposal is not a valid spanning tree: {e}"

    try:
        rec_data = json.loads(r_path.read_text(encoding="utf-8"))
    except Exception as e:
        return False, f"Receipt JSON invalid: {e}"

    verdict = rec_data.get("validation", {}).get("verdict")
    if verdict in ("FAILED", "CALL_ERROR"):
        return False, f"Receipt validation verdict is {verdict}"

    rec_edges = None
    if isinstance(rec_data.get("validation"), dict) and "edges" in rec_data["validation"]:
        rec_edges = rec_data["validation"]["edges"]
    elif "edges" in rec_data:
        rec_edges = rec_data["edges"]
    elif "raw_response" in rec_data:
        try:
            raw_obj = json.loads(rec_data["raw_response"])
            if isinstance(raw_obj, dict) and "edges" in raw_obj:
                rec_edges = raw_obj["edges"]
        except Exception:
            pass

    if rec_edges is None:
        return False, "No valid edges found in receipt"

    try:
        norm_prop_edges = [[int(u), int(v)] for u, v in prop_edges]
        norm_rec_edges = [[int(u), int(v)] for u, v in rec_edges]
    except Exception:
        return False, "Edges format invalid"

    if norm_prop_edges != norm_rec_edges:
        return False, "Proposal edges do not match receipt edges"

    return True, norm_prop_edges


def write_manifest(output_dir=OUTPUT_DIR):
    """Generate model_cohort_manifest.json with all valid model proposals.

    A candidate is included ONLY when:
    1. Proposal and receipt files both exist.
    2. Proposal edges form a valid tree (connected, acyclic, 11 edges across 12 qubits).
    3. Proposal edges strictly equal the receipt's recorded edges.
    Never substitutes hand-coded candidates into the Muse cohort.
    """
    output_dir = Path(output_dir)
    manifest_file = output_dir / "model_cohort_manifest.json"
    candidates = []

    # 1. Existing Muse Proposal 01 (CALL_02)
    p1_file = output_dir / "muse_proposal_01.json"
    if not p1_file.exists():
        p1_file = ROOT / "muse_proposal_01.json"
    p1_receipt = output_dir / "muse_proposal_01_receipt.json"
    if not p1_receipt.exists():
        p1_receipt = ROOT / "muse_proposal_01_receipt.json"

    valid1, reason1 = verify_candidate_integrity(p1_file, p1_receipt, 12)
    if valid1:
        prop_path_str = str(p1_file.relative_to(ROOT)) if p1_file.is_relative_to(ROOT) else str(p1_file.name)
        rec_path_str = str(p1_receipt.relative_to(ROOT)) if p1_receipt.is_relative_to(ROOT) else str(p1_receipt.name)
        candidates.append({
            "candidate_id": "muse_proposal_01",
            "name": "Muse Proposal 01 (Zero-Shot)",
            "call_id": "CALL_02",
            "proposal_file": prop_path_str,
            "proposal_sha256": compute_sha256(p1_file),
            "receipt_file": rec_path_str,
            "receipt_sha256": compute_sha256(p1_receipt),
            "validation_verdict": "PASSED"
        })
    else:
        print(f"  [MANIFEST EXCLUDE] muse_proposal_01: {reason1}")

    # 2. Existing Muse Critique Proposal 02 (CALL_03)
    p2_file = output_dir / "muse_critique_proposal_02.json"
    if not p2_file.exists():
        p2_file = OUTPUT_DIR / "muse_critique_proposal_02.json"
    p2_receipt = output_dir / "muse_critique_smoke_receipt.json"
    if not p2_receipt.exists():
        p2_receipt = OUTPUT_DIR / "muse_critique_smoke_receipt.json"

    valid2, reason2 = verify_candidate_integrity(p2_file, p2_receipt, 12)
    if valid2:
        prop_path_str = str(p2_file.relative_to(ROOT)) if p2_file.is_relative_to(ROOT) else str(p2_file.name)
        rec_path_str = str(p2_receipt.relative_to(ROOT)) if p2_receipt.is_relative_to(ROOT) else str(p2_receipt.name)
        candidates.append({
            "candidate_id": "muse_critique_proposal_02",
            "name": "Muse Critique Proposal 02 (Smoke Critique)",
            "call_id": "CALL_03",
            "proposal_file": prop_path_str,
            "proposal_sha256": compute_sha256(p2_file),
            "receipt_file": rec_path_str,
            "receipt_sha256": compute_sha256(p2_receipt),
            "validation_verdict": "PASSED"
        })
    else:
        print(f"  [MANIFEST EXCLUDE] muse_critique_proposal_02: {reason2}")

    # 3. New calls (CALL_04, CALL_05, CALL_06)
    for spec in PROMPT_SPECS:
        cid = spec["candidate_id"]
        call_id = spec["call_id"]
        prop_file = output_dir / f"{cid}.json"
        rec_file = output_dir / f"{call_id}_receipt.json"

        valid, reason = verify_candidate_integrity(prop_file, rec_file, 12)
        if valid:
            prop_path_str = str(prop_file.relative_to(ROOT)) if prop_file.is_relative_to(ROOT) else str(prop_file.name)
            rec_path_str = str(rec_file.relative_to(ROOT)) if rec_file.is_relative_to(ROOT) else str(rec_file.name)
            candidates.append({
                "candidate_id": cid,
                "name": f"Muse Candidate ({call_id})",
                "call_id": call_id,
                "proposal_file": prop_path_str,
                "proposal_sha256": compute_sha256(prop_file),
                "receipt_file": rec_path_str,
                "receipt_sha256": compute_sha256(rec_file),
                "validation_verdict": "PASSED"
            })
        else:
            print(f"  [MANIFEST EXCLUDE] {cid} ({call_id}): {reason}")

    manifest = {
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "model": MODEL,
        "valid_proposals_count": len(candidates),
        "target_cohort_size": 5,
        "is_complete_cohort": len(candidates) == 5,
        "cohort_policy": "If valid_proposals_count < 5, cohort is reported as smaller than 5. No hand-coded designs substituted.",
        "candidates": candidates
    }
    atomic_write_json(manifest_file, manifest)
    return manifest


def main():
    parser = argparse.ArgumentParser(description="Execute the frozen 3-call capped collection for Lambda=1.2.")
    parser.add_argument("--execute", action="store_true", help="Authorize sending exactly up to 3 bounded API calls.")
    args = parser.parse_args()

    OUTPUT_DIR.mkdir(exist_ok=True)
    summary_file = OUTPUT_DIR / "collection_run_summary.json"

    print("=== Meta Muse 3-Call Capped Collection Runner ===")
    print(f"Model: {MODEL} | Hard Call Cap: {len(PROMPT_SPECS)} requests | Max Tokens: 1024/req")

    if not args.execute:
        print("\n[DRY RUN MODE - ZERO API CALLS WILL BE SENT]")
        print("Pre-declared call queue:")
        for idx, spec in enumerate(PROMPT_SPECS, 1):
            prompt_hash = hashlib.sha256(spec["prompt_text"].encode("utf-8")).hexdigest()[:12]
            print(f"  {idx}. {spec['call_id']} -> {spec['candidate_id']} (temp={spec['temperature']}, hash={prompt_hash})")
            print(f"     Prompt preview: {spec['prompt_text'][:100]}...")
        print("\nPass --execute to execute the collection queue.")
        return

    key = get_api_key()
    if not key:
        print("ERROR: MODEL_API_KEY not found in environment or .env.", file=sys.stderr)
        sys.exit(1)

    from openai import OpenAI
    client = OpenAI(base_url="https://api.meta.ai/v1", api_key=key, max_retries=0, timeout=30)

    summary = {
        "timestamp_start_utc": datetime.now(timezone.utc).isoformat(),
        "model": MODEL,
        "call_cap": len(PROMPT_SPECS),
        "calls": []
    }

    for idx, spec in enumerate(PROMPT_SPECS, 1):
        call_id = spec["call_id"]
        receipt_file = OUTPUT_DIR / f"{call_id}_receipt.json"
        marker_file = OUTPUT_DIR / f"{call_id}.attempt_marker"

        if receipt_file.exists():
            print(f"[{idx}/{len(PROMPT_SPECS)}] {call_id}: Found existing receipt. Skipping duplicate call.")
            receipt = json.loads(receipt_file.read_text(encoding="utf-8"))
        elif marker_file.exists():
            print(f"[{idx}/{len(PROMPT_SPECS)}] {call_id}: Attempt marker exists without receipt. Skipping to prevent double spend.")
            receipt = {"call_id": call_id, "status": "STOPPED_DUE_TO_PRIOR_MARKER"}
        else:
            print(f"[{idx}/{len(PROMPT_SPECS)}] {call_id}: Creating marker & sending request to Meta API...", end=" ", flush=True)
            receipt, action = execute_call(spec, client)
            v = receipt.get("validation", {}).get("verdict", "UNKNOWN")
            tok = receipt.get("total_tokens", 0)
            print(f"Finished. Action={action}, Tokens={tok}, Verdict={v}")
        summary["calls"].append(receipt)

    summary["timestamp_end_utc"] = datetime.now(timezone.utc).isoformat()
    atomic_write_json(summary_file, summary)
    manifest = write_manifest()
    print(f"\nCollection run complete! Summary saved to {summary_file}")
    print(f"Manifest written with {manifest['valid_proposals_count']} valid model candidate(s).")


if __name__ == "__main__":
    main()
"""Deterministic, bounded 2D landing challenge for constrained controller designs.

The model is a point mass with horizontal wind acceleration and vertical gravity.
It is a simulation benchmark, not a flight dynamics or safety model.
"""

import json
import math
import random
from dataclasses import dataclass


DT = 0.05
GRAVITY = 9.81
MAX_TIME = 12.0
MAX_HORIZONTAL_ACCEL = 5.0
MAX_VERTICAL_THRUST = 2.0 * GRAVITY
FIELDS = {
    "kp_x": (0.1, 5.0),
    "kd_x": (0.1, 5.0),
    "kp_z": (0.1, 6.0),
    "kd_z": (0.1, 6.0),
    "descent_rate": (0.2, 2.0),
}
BASELINE = {"kp_x": 2.0, "kd_x": 2.2, "kp_z": 2.5, "kd_z": 2.8, "descent_rate": 0.65}


def validate_controller(raw):
    if not isinstance(raw, dict) or set(raw) != set(FIELDS):
        raise ValueError("controller must contain exactly five named gains")
    result = {}
    for key, (low, high) in FIELDS.items():
        value = raw[key]
        if type(value) not in (int, float) or not math.isfinite(value) or not low <= value <= high:
            raise ValueError(f"{key} must be a finite number from {low} to {high}")
        result[key] = float(value)
    return result


@dataclass(frozen=True)
class Scenario:
    seed: int
    initial_x: float
    initial_z: float
    wind_amplitude: float
    gust_start: float
    gust_end: float
    gust_accel: float
    phase: float


def make_scenario(seed, stress=False):
    rng = random.Random(seed)
    return Scenario(
        seed=seed,
        initial_x=rng.choice([-1.0, 1.0]) * rng.uniform(1.0, 2.5),
        initial_z=rng.uniform(4.5, 6.5),
        wind_amplitude=rng.uniform(0.2, 1.0 if not stress else 1.8),
        gust_start=rng.uniform(1.0, 3.0),
        gust_end=rng.uniform(4.0, 7.0),
        gust_accel=rng.choice([-1.0, 1.0]) * rng.uniform(0.3, 0.9 if not stress else 2.2),
        phase=rng.uniform(0.0, 2.0 * math.pi),
    )


def wind_at(scenario, t):
    smooth = scenario.wind_amplitude * math.sin(0.9 * t + scenario.phase)
    gust = scenario.gust_accel if scenario.gust_start <= t <= scenario.gust_end else 0.0
    return smooth + gust


def clip(value, low, high):
    return max(low, min(high, value))


def simulate(controller, scenario, include_trajectory=False):
    gains = validate_controller(controller)
    x, z = scenario.initial_x, scenario.initial_z
    vx = vz = 0.0
    effort = 0.0
    trajectory = []
    touchdown = False
    steps = int(MAX_TIME / DT)
    for step in range(steps):
        t = step * DT
        if include_trajectory:
            trajectory.append({"t": round(t, 3), "x": x, "z": z,
                               "vx": vx, "vz": vz, "wind": wind_at(scenario, t)})
        target_z = max(0.0, scenario.initial_z - gains["descent_rate"] * t)
        ux = clip(-gains["kp_x"] * x - gains["kd_x"] * vx,
                  -MAX_HORIZONTAL_ACCEL, MAX_HORIZONTAL_ACCEL)
        thrust = clip(GRAVITY + gains["kp_z"] * (target_z - z) - gains["kd_z"] * vz,
                      0.0, MAX_VERTICAL_THRUST)
        wind = wind_at(scenario, t)
        vx += (ux + wind) * DT
        vz += (thrust - GRAVITY) * DT
        x += vx * DT
        z += vz * DT
        effort += (abs(ux) / MAX_HORIZONTAL_ACCEL + abs(thrust - GRAVITY) / GRAVITY) * DT
        if z <= 0.0:
            touchdown = True
            z = 0.0
            break
    success = touchdown and abs(x) <= 0.35 and abs(vx) <= 0.6 and -0.8 <= vz <= 0.15
    time_value = min((step + 1) * DT, MAX_TIME)
    cost = (abs(x) + 0.5 * abs(vx) + 0.7 * abs(vz) + 0.02 * effort
            + (0.0 if success else 10.0) + (5.0 if not touchdown else 0.0))
    result = {"scenario_seed": scenario.seed, "touchdown": touchdown,
              "success": success, "landing_x": x, "landing_vx": vx,
              "landing_vz": vz, "time": time_value, "effort": effort,
              "cost": cost, "simulated_point_mass": True}
    if include_trajectory:
        trajectory.append({"t": time_value, "x": x, "z": z,
                           "vx": vx, "vz": vz, "wind": wind_at(scenario, time_value)})
        result["trajectory"] = trajectory
    return result


def evaluate(controller, seeds, stress=False):
    trials = [simulate(controller, make_scenario(seed, stress=stress)) for seed in seeds]
    return {"controller": validate_controller(controller), "seeds": list(seeds),
            "stress": stress, "trials": trials,
            "successes": sum(trial["success"] for trial in trials),
            "mean_cost": sum(trial["cost"] for trial in trials) / len(trials),
            "worst_cost": max(trial["cost"] for trial in trials)}


if __name__ == "__main__":
    print(json.dumps({"training": evaluate(BASELINE, range(20)),
                      "stress": evaluate(BASELINE, range(100, 120), stress=True)}, indent=2))
