"""Evaluate 12-qubit circuits against the gauge-singlet truncated model.

The raw 12-qubit state has a per-mode cutoff of 4. It is embedded in the
total-occupation <= 4 basis, then projected onto SU(2) singlets. Report the
projection probability separately; energy alone would hide postselection.
No Meta API calls.
"""

import argparse
import json
from pathlib import Path

import numpy as np
from scipy.optimize import minimize

from candidate_bench import baseline, circuit, validate_proposal
from gauge_invariant_benchmark import operators, physical_sector


ROOT = Path(__file__).resolve().parent


def encoded_indices(states, local_cutoff=4):
    result = []
    for position, state in enumerate(states):
        if max(state) < local_cutoff:
            index = sum(n * local_cutoff ** (5 - mode) for mode, n in enumerate(state))
            result.append((position, index))
    return result


def evaluate(edges, lam, max_total, seeds, budget):
    states, h, gs = operators(lam, max_total)
    singlets, h_phys, exact, _ = physical_sector(h, gs)
    mapping = encoded_indices(states)
    physical_rows = np.array([i for i, _ in mapping], dtype=int)
    circuit_columns = np.array([j for _, j in mapping], dtype=int)
    projector = singlets.conj().T[:, physical_rows]
    trials = []
    for seed in seeds:
        rng = np.random.default_rng(seed)
        initial = rng.uniform(-0.4, 0.4, 24)
        best = {"energy": float("inf"), "overlap": None, "evaluations": 0}

        def objective(params):
            state = circuit(params, edges, 12)
            coeff = projector @ state[circuit_columns]
            overlap = float(np.vdot(coeff, coeff).real)
            if overlap < 0.05:
                energy = 1e4 + 1e4 * (0.05 - overlap)
            else:
                energy = float(np.vdot(coeff, h_phys @ coeff).real / overlap)
            best["evaluations"] += 1
            if energy < best["energy"]:
                best["energy"] = energy
                best["overlap"] = overlap
            return energy

        minimize(objective, initial, method="COBYLA",
                 options={"maxiter": budget, "rhobeg": 0.5, "tol": 1e-5})
        trials.append({"seed": seed, "energy": best["energy"],
                       "energy_error": best["energy"] - exact,
                       "singlet_overlap_probability": best["overlap"],
                       "evaluations": best["evaluations"]})
    return {"lambda": lam, "max_total_occupation": max_total,
            "exact_physical_ground_energy": exact, "trials": trials,
            "median_energy_error": float(np.median([t["energy_error"] for t in trials])),
            "median_singlet_overlap_probability": float(np.median([
                t["singlet_overlap_probability"] for t in trials]))}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--budget", type=int, default=300)
    parser.add_argument("--seeds", type=int, default=3)
    parser.add_argument("--max-total", type=int, default=4)
    args = parser.parse_args()
    if args.max_total < 1 or args.budget < 1 or args.seeds < 1:
        parser.error("max-total, budget, and seeds must be positive")
    prior = json.loads((ROOT / "local_search_results.json").read_text(encoding="utf-8"))
    random_edges = next(x["edges"] for x in prior["search"] if x["name"] == "random_04")
    muse_edges = validate_proposal(json.loads((ROOT / "muse_proposal_01.json").read_text()), 12)
    layouts = {"cross_budget": baseline(12, "cross_budget"),
               "random_04": random_edges, "muse_proposal_01": muse_edges}
    output = {"method": "Gauge-singlet projection in total-occupation cutoff; no Muse API calls.",
              "budget_per_seed": args.budget, "seeds": list(range(args.seeds)), "rows": []}
    for lam in (0.5, 1.0, 2.0):
        for name, edges in layouts.items():
            row = evaluate(edges, lam, args.max_total, range(args.seeds), args.budget)
            row["layout"] = name
            output["rows"].append(row)
            (ROOT / "physical_results.json").write_text(json.dumps(output, indent=2))
            print(f"lambda={lam:g} {name}: error={row['median_energy_error']:.6f}, singlet probability={row['median_singlet_overlap_probability']:.3f}", flush=True)


if __name__ == "__main__":
    main()
"""Gauge diagnostic for the SU(2) two-matrix benchmark; classical statevectors."""

import argparse
import numpy as np
from scipy import sparse
from scipy.sparse.linalg import eigsh

from matrix_vqe_preflight import embed, hamiltonian


def generators(cutoff):
    a = sparse.diags(np.sqrt(np.arange(1, cutoff)), 1,
                     shape=(cutoff, cutoff), format="csr")
    x = [embed((a + a.T) / np.sqrt(2), i, cutoff) for i in range(6)]
    p = [embed(1j * (a.T - a) / np.sqrt(2), i, cutoff) for i in range(6)]
    result = []
    for alpha in range(3):
        b, c = [i for i in range(3) if i != alpha]
        sign = 1 if (b, c, alpha) in [(0, 1, 2), (1, 2, 0), (2, 0, 1)] else -1
        result.append(sign * sum((x[offset + b] @ p[offset + c]
                                  - x[offset + c] @ p[offset + b]
                                  for offset in (0, 3)),
                                 sparse.csr_matrix((cutoff**6, cutoff**6))))
    return result


def gauge_norm_squared(state, gs):
    return float(sum(np.vdot(g @ state, g @ state).real for g in gs))


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--cutoff", type=int, default=4)
    parser.add_argument("--lambda", dest="lam", type=float, default=1.0)
    args = parser.parse_args()
    h = hamiltonian(args.lam, args.cutoff)
    energy, vec = eigsh(h, k=1, which="SA", tol=1e-10)
    vacuum = np.zeros(h.shape[0]); vacuum[0] = 1
    gs = generators(args.cutoff)
    print({"cutoff": args.cutoff, "lambda": args.lam,
           "exact_energy": float(energy[0]),
           "exact_gauge_norm_squared": gauge_norm_squared(vec[:, 0], gs),
           "vacuum_gauge_norm_squared": gauge_norm_squared(vacuum, gs),
           "max_hermiticity_defect": max(float(sparse.linalg.norm(g-g.getH())) for g in gs)})
"""Finite SU(2) two-matrix benchmark with a symmetry-preserving cutoff.

Keep all six-mode Fock states with total occupation <= N. Unlike independent
per-mode cutoffs, this subspace is invariant under SU(2) color rotations.
Build the quartic Hamiltonian in a two-excitation buffer, then project back.
"""

import argparse
import itertools
import json
from pathlib import Path

import numpy as np
from scipy import sparse
from scipy.linalg import eigh
from scipy.sparse.linalg import norm


def basis(max_total):
    return [state for state in itertools.product(range(max_total + 1), repeat=6)
            if sum(state) <= max_total]


def annihilators(states):
    lookup = {state: i for i, state in enumerate(states)}
    ops = []
    for mode in range(6):
        rows, cols, values = [], [], []
        for col, state in enumerate(states):
            if state[mode]:
                lowered = list(state)
                lowered[mode] -= 1
                rows.append(lookup[tuple(lowered)])
                cols.append(col)
                values.append(np.sqrt(state[mode]))
        ops.append(sparse.csr_matrix((values, (rows, cols)), shape=(len(states), len(states))))
    return ops


def operators(lam, max_total, buffer_extra=2):
    if max_total < 1:
        raise ValueError("max_total must be >= 1")
    if buffer_extra < 2:
        raise ValueError("quartic Hamiltonian requires a buffer of at least two excitations")
    buffered = basis(max_total + buffer_extra)
    kept = [i for i, state in enumerate(buffered) if sum(state) <= max_total]
    states = [buffered[i] for i in kept]
    annihilation = annihilators(buffered)
    x = [(a + a.getH()) / np.sqrt(2) for a in annihilation]
    p = [1j * (a.getH() - a) / np.sqrt(2) for a in annihilation]
    number = sparse.diags([float(sum(state)) for state in buffered], format="csr")
    h = 3 * sparse.eye(len(buffered), format="csr") + number
    for gamma in range(3):
        a, b = [i for i in range(3) if i != gamma]
        cross = x[a] @ x[3 + b] - x[b] @ x[3 + a]
        h = h + (lam / 2) * (cross @ cross)
    generators = []
    for alpha in range(3):
        b, c = [i for i in range(3) if i != alpha]
        g = sum((x[offset + b] @ p[offset + c] - x[offset + c] @ p[offset + b]
                 for offset in (0, 3)), sparse.csr_matrix(h.shape, dtype=complex))
        generators.append(g[kept, :][:, kept].tocsr())
    return states, h[kept, :][:, kept].tocsr(), generators


def physical_sector(h, gs, tolerance=1e-9):
    casimir = sum((g.getH() @ g for g in gs), sparse.csr_matrix(h.shape, dtype=complex))
    values, vectors = eigh(casimir.toarray())
    singlets = vectors[:, values < tolerance]
    if singlets.shape[1] == 0:
        raise ValueError("No gauge-singlet states found")
    h_phys = singlets.conj().T @ (h @ singlets)
    energies = eigh(h_phys, eigvals_only=True)
    return singlets, h_phys, float(energies[0]), values


def integrity(lam, max_total):
    states, h, gs = operators(lam, max_total)
    singlets, _, ground, casimir_spectrum = physical_sector(h, gs)
    commutators = [float(norm(h @ g - g @ h)) for g in gs]
    algebra = []
    # With this orientation of the three generators, [G0,G1] = -i G2.
    for a, b, c in ((0, 1, 2), (1, 2, 0), (2, 0, 1)):
        algebra.append(float(norm(gs[a] @ gs[b] - gs[b] @ gs[a] + 1j * gs[c])))
    return {
        "lambda": lam, "max_total_occupation": max_total,
        "dimension": len(states), "singlet_dimension": singlets.shape[1],
        "exact_physical_ground_energy": ground,
        "H_G_commutator_frobenius_norms": commutators,
        "SU2_algebra_residual_frobenius_norms": algebra,
        "casimir_zero_eigenvalues": int(np.sum(casimir_spectrum < 1e-9)),
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--max-total", type=int, default=3)
    parser.add_argument("--lambda", dest="lam", type=float, default=1.0)
    args = parser.parse_args()
    result = integrity(args.lam, args.max_total)
    print(json.dumps(result, indent=2))
"""Generate and pre-lock the 5 uniform random spanning tree controls for lambda=1.2.

Protocol:
- Undirected sampling: NetworkX random_spanning_tree on K_12 using Kulkarni A8 algorithm
- Random Seeds: [202610271, 202610272, 202610273, 202610274, 202610275]
- Directed mapping: For each seed s, sort undirected pairs lexicographically.
  Then with default_rng(s), assign direction (u,v) vs (v,u) with probability 1/2.
  Finally shuffle the 11 directed edges with default_rng(s).
- Validated via validate_tree (12 qubits, 11 directed edges, connected, acyclic).
- Saved to muse_collection/frozen_random_controls_lambda12.json before simulation.
"""

import json
from pathlib import Path
import networkx as nx
import numpy as np

from run_iterative_benchmark import validate_tree

ROOT = Path(__file__).resolve().parent
OUTPUT_FILE = ROOT / "muse_collection" / "frozen_random_controls_lambda12.json"
SEEDS = [202610271, 202610272, 202610273, 202610274, 202610275]


def generate_controls():
    K12 = nx.complete_graph(12)
    controls = []
    
    for idx, s in enumerate(SEEDS, 1):
        # 1. Undirected uniform spanning tree (Kulkarni A8 algorithm in NetworkX)
        T = nx.random_spanning_tree(K12, weight=None, seed=s)
        raw_edges = [sorted(list(e)) for e in T.edges()]
        raw_edges.sort()
        
        # 2. Deterministic direction assignment and shuffle
        rng = np.random.default_rng(s)
        directed_edges = []
        for u, v in raw_edges:
            if rng.random() < 0.5:
                directed_edges.append([u, v])
            else:
                directed_edges.append([v, u])
        rng.shuffle(directed_edges)
        
        # 3. Validation
        valid_edges = validate_tree({"edges": directed_edges}, 12)
        
        entry = {
            "control_id": f"random_ust_{idx:02d}",
            "name": f"Uniform Random Spanning Tree #{idx:02d}",
            "seed": s,
            "algorithm": "NetworkX random_spanning_tree (Kulkarni A8 on K_12) + deterministic direction/shuffle",
            "edges": valid_edges
        }
        controls.append(entry)
        
    output = {
        "networkx_version": nx.__version__,
        "numpy_version": np.__version__,
        "controls_count": len(controls),
        "controls": controls
    }
    OUTPUT_FILE.write_text(json.dumps(output, indent=2), encoding="utf-8")
    print(f"Generated and verified {len(controls)} uniform random spanning tree controls.")
    print(f"Saved to {OUTPUT_FILE}")
    return controls


if __name__ == "__main__":
    generate_controls()
"""Generate and freeze two uniform random spanning tree controls for lambda=1.7.

Protocol:
- Undirected sampling: NetworkX random_spanning_tree on K_12 using Kulkarni A8 algorithm.
- Random Seeds: [2026102771, 2026102772].
- Directed mapping: For each seed s, sort undirected pairs lexicographically.
  Then with numpy.random.default_rng(s), assign direction (u, v) vs (v, u) with probability 1/2.
  Finally shuffle the 11 directed edges with default_rng(s).
- Validated via strict validate_tree (12 qubits, 11 directed edges, connected, acyclic).
- Saved to muse_collection/frozen_random_controls_lambda17.json.

NOTE: This script is prepared for Codex execution. Antigravity does not execute terminal commands,
does not run physics simulations, and does not fabricate random edges by hand.
"""

import json
from pathlib import Path
import networkx as nx
import numpy as np

from candidate_bench import validate_proposal

ROOT = Path(__file__).resolve().parent
OUTPUT_FILE = ROOT / "muse_collection" / "frozen_random_controls_lambda17.json"
SEEDS = [2026102771, 2026102772]


def validate_tree(raw, qubits=12):
    """Enforces valid format, exactly qubits-1 edges, connected spanning tree (acyclic)."""
    edges = validate_proposal(raw, qubits)
    parent = list(range(qubits))

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    for control, target in edges:
        a, b = find(control), find(target)
        if a == b:
            raise ValueError("undirected CNOT graph contains a cycle or repeated edge")
        parent[a] = b
    if len({find(node) for node in range(qubits)}) != 1:
        raise ValueError("CNOT graph is disconnected")
    return edges


def generate_controls(output_path=OUTPUT_FILE):
    K12 = nx.complete_graph(12)
    controls = []

    for idx, s in enumerate(SEEDS, 1):
        # 1. Undirected uniform spanning tree on K_12 (Kulkarni A8 algorithm in NetworkX)
        T = nx.random_spanning_tree(K12, weight=None, seed=s)
        raw_edges = [sorted(list(e)) for e in T.edges()]
        raw_edges.sort()

        # 2. Deterministic direction assignment (p=0.5) and shuffle with default_rng(s)
        rng = np.random.default_rng(s)
        directed_edges = []
        for u, v in raw_edges:
            if rng.random() < 0.5:
                directed_edges.append([u, v])
            else:
                directed_edges.append([v, u])
        rng.shuffle(directed_edges)

        # 3. Validation
        valid_edges = validate_tree({"edges": directed_edges}, 12)

        entry = {
            "control_id": f"random_ust_lambda17_{idx:02d}",
            "name": f"Uniform Random Spanning Tree #{idx:02d} (Lambda 1.7)",
            "seed": s,
            "algorithm": "NetworkX random_spanning_tree (Kulkarni A8 on K_12) + deterministic direction/shuffle",
            "edges": valid_edges,
        }
        controls.append(entry)

    output = {
        "networkx_version": nx.__version__,
        "numpy_version": np.__version__,
        "controls_count": len(controls),
        "controls": controls,
    }
    target = Path(output_path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(output, indent=2), encoding="utf-8")
    print(f"Generated and verified {len(controls)} uniform random spanning tree controls for lambda=1.7.")
    print(f"Saved to {target}")
    return controls


if __name__ == "__main__":
    generate_controls()
"""Credit-free topology search for the archived HorizonForge simulator.

This file and its results are exploratory preparation. It does not call a
model or make any network requests.
"""

import json
import time
from pathlib import Path

import numpy as np
from scipy.sparse.linalg import eigsh

from candidate_bench import baseline, evaluate, validate_proposal
from gauge_check import generators
from matrix_vqe_preflight import hamiltonian


ROOT = Path(__file__).parent
OUTPUT = ROOT / "local_search_results.json"
QUBITS = 12
SEARCH_BUDGET = 300
FINAL_BUDGET = 800
SEEDS = range(5)


def random_tree(rng):
    order = list(map(int, rng.permutation(QUBITS)))
    edges = []
    for pos in range(1, QUBITS):
        parent = order[int(rng.integers(pos))]
        child = order[pos]
        edges.append([parent, child] if rng.integers(2) else [child, parent])
    rng.shuffle(edges)
    return validate_proposal({"edges": edges}, QUBITS)


def save(data):
    OUTPUT.write_text(json.dumps(data, indent=2))


def main():
    start = time.time()
    rng = np.random.default_rng(20261026)
    data = {"methods": "No Meta API; noiseless classical simulator; random spanning trees have the same 11 CNOTs per layer and 24 RY parameters as fixed layouts.",
            "search_budget": SEARCH_BUDGET, "final_budget": FINAL_BUDGET,
            "seeds": list(SEEDS), "search": [], "final": []}

    h1 = hamiltonian(1.0, 4)
    gs = generators(4)
    fixed = {name: baseline(QUBITS, name) for name in ("ring", "cross_budget")}
    candidates = [(name, edges) for name, edges in fixed.items()]
    candidates += [(f"random_{i:02d}", random_tree(rng)) for i in range(16)]

    for name, edges in candidates:
        result = evaluate(edges, h1, gs, SEARCH_BUDGET, 0)
        data["search"].append({"name": name, "edges": edges, **result})
        save(data)
        print(f"search {name}: E={result['energy']:.6f}, G2={result['gauge_norm_squared']:.6f}", flush=True)

    best_random = sorted((row for row in data["search"] if row["name"].startswith("random_")),
                         key=lambda row: row["energy"])[:2]
    finalists = data["search"][:2] + best_random
    for lam in (1.0, 0.5, 2.0):
        h = h1 if lam == 1.0 else hamiltonian(lam, 4)
        exact = float(eigsh(h, k=1, which="SA", tol=1e-10)[0][0])
        for row in finalists:
            trials = [evaluate(row["edges"], h, gs, FINAL_BUDGET, seed) for seed in SEEDS]
            item = {"lambda": lam, "exact_energy": exact, "name": row["name"],
                    "edges": row["edges"], "trials": trials,
                    "median_energy_error": float(np.median([t["energy"] - exact for t in trials])),
                    "median_gauge_norm_squared": float(np.median([t["gauge_norm_squared"] for t in trials]))}
            data["final"].append(item)
            save(data)
            print(f"final lambda={lam} {row['name']}: dE={item['median_energy_error']:.6f}, G2={item['median_gauge_norm_squared']:.6f}", flush=True)

    data["elapsed_seconds"] = round(time.time() - start, 2)
    save(data)
    print(f"saved {OUTPUT}; elapsed {data['elapsed_seconds']}s", flush=True)


if __name__ == "__main__":
    main()
"""Small, reproducible preflight for the SU(2) two-matrix bosonic model.

This is a classical statevector simulation of a six-qubit Fock truncation,
not a quantum-hardware result or a Meta-agent run.
"""

import argparse
import json
import time

import numpy as np
from scipy import sparse
from scipy.optimize import minimize
from scipy.sparse.linalg import eigsh


def embed(op, site, cutoff=2, modes=6):
    result = sparse.csr_matrix([[1.0]])
    ident = sparse.eye(cutoff, format="csr")
    for i in range(modes):
        result = sparse.kron(result, op if i == site else ident, format="csr")
    return result


def hamiltonian(lam, cutoff=2):
    """Equation (20) of Rinaldi et al. (2021), m=1, g^2=lambda/2."""
    lowering = sparse.diags(np.sqrt(np.arange(1, cutoff)), 1, shape=(cutoff, cutoff), format="csr")
    number = sparse.diags(np.arange(cutoff, dtype=float), format="csr")
    x = [embed((lowering + lowering.T) / np.sqrt(2), i, cutoff) for i in range(6)]
    dimension = cutoff**6
    h = sparse.eye(dimension, format="csr") * 3.0
    for i in range(6):
        h = h + embed(number, i, cutoff)
    # C_gamma = epsilon_{alpha,beta,gamma} X_{1,alpha} X_{2,beta}
    for gamma in range(3):
        cross = sparse.csr_matrix((dimension, dimension))
        others = [i for i in range(3) if i != gamma]
        a, b = others
        sign = 1 if (a, b, gamma) in [(0, 1, 2), (1, 2, 0), (2, 0, 1)] else -1
        cross = sign * (x[a] @ x[3 + b] - x[b] @ x[3 + a])
        h = h + (lam / 2) * (cross @ cross)
    return h.tocsr()


def ry(state, theta, qubit, qubits=6):
    shaped = np.moveaxis(state.reshape([2] * qubits), qubit, 0)
    c, s = np.cos(theta / 2), np.sin(theta / 2)
    out = np.empty_like(shaped)
    out[0] = c * shaped[0] - s * shaped[1]
    out[1] = s * shaped[0] + c * shaped[1]
    return np.moveaxis(out, 0, qubit).reshape(-1)


def cnot(state, control, target, qubits=6):
    indices = np.arange(1 << qubits)
    select = (indices & (1 << (qubits - 1 - control))) != 0
    perm = indices.copy()
    perm[select] ^= 1 << (qubits - 1 - target)
    return state[perm]


def statevector(params, depth, layout, qubits=6):
    state = np.zeros(1 << qubits)
    state[0] = 1.0
    for layer in range(depth):
        for q in range(qubits):
            state = ry(state, params[layer * qubits + q], q, qubits)
        if layout == "ring":
            pairs = [(q, q + 1) for q in range(qubits - 1)]
        elif layout == "cross":
            half = qubits // 2
            pairs = [(q, q + half) for q in range(half)]
            pairs += [(q, q + 1) for q in range(half - 1)]
            pairs += [(q, q + 1) for q in range(half, qubits - 1)]
        elif layout == "cross_budget":
            half = qubits // 2
            pairs = [(q, q + half) for q in range(half)]
            within = [(q, q + 1) for q in range(half - 1)]
            within += [(q, q + 1) for q in range(half, qubits - 1)]
            pairs += within[::2][:half-1]
        else:
            raise ValueError(layout)
        for a, b in pairs:
            state = cnot(state, a, b, qubits)
    return state


def optimize(h, depth, layout, seed, max_evals, return_params=False):
    rng = np.random.default_rng(seed)
    qubits = int(np.log2(h.shape[0]))
    start = rng.uniform(-0.4, 0.4, size=qubits * depth)
    calls = 0
    best = np.inf
    best_params = None

    def objective(parameters):
        nonlocal calls, best, best_params
        state = statevector(parameters, depth, layout, qubits)
        value = float(state @ (h @ state))
        calls += 1
        if value < best:
            best = value
            best_params = parameters.copy()
        return value

    result = minimize(objective, start, method="COBYLA", options={"maxiter": max_evals, "rhobeg": 0.5, "tol": 1e-5})
    output = {"best_energy": float(best), "evaluations": calls, "success": bool(result.success)}
    if return_params:
        output["best_params"] = best_params
    return output


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--budget", type=int, default=300)
    p.add_argument("--seeds", type=int, default=3)
    args = p.parse_args()
    rows = []
    start = time.time()
    for lam in [0.5, 1.0, 2.0]:
        h = hamiltonian(lam)
        exact = float(eigsh(h, k=1, which="SA", tol=1e-11)[0][0])
        vacuum = float(h[0, 0])
        for depth, layout in [(1, "ring"), (2, "ring"), (2, "cross")]:
            trials = [optimize(h, depth, layout, seed, args.budget) for seed in range(args.seeds)]
            rows.append({"lambda": lam, "cutoff": 2, "exact": exact, "vacuum": vacuum,
                         "depth": depth, "layout": layout, "budget_per_seed": args.budget,
                         "trials": trials, "best": min(t["best_energy"] for t in trials)})
            print(json.dumps(rows[-1]), flush=True)
    print(json.dumps({"elapsed_seconds": round(time.time() - start, 2)}))


if __name__ == "__main__":
    main()
"""Single bounded Muse critique request (Step 1 Smoke Test).

Strict safety constraints:
- Exactly ONE HTTP request to Meta Muse API.
- Zero automatic retries (max_retries=0, timeout=30).
- Max completion tokens: 1024. Minimal reasoning effort.
- Requires explicit --execute flag.
- Logs full machine receipt (prompt, raw response, finish reason, usage, validation verdict, timestamp).
- Never prints or leaks the API key.
"""

import argparse
import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

from candidate_bench import validate_proposal

ROOT = Path(__file__).resolve().parent
MODEL = "muse-spark-1.3"

SCHEMA = {
    "type": "json_schema",
    "json_schema": {
        "name": "circuit_topology",
        "schema": {
            "type": "object",
            "properties": {
                "edges": {
                    "type": "array",
                    "items": {
                        "type": "array",
                        "items": {"type": "integer"},
                    },
                },
            },
            "required": ["edges"],
            "additionalProperties": False,
        },
    },
}

CRITIQUE_PROMPT = (
    "You are designing a 12-qubit, two-layer variational quantum circuit topology "
    "for an SU(2) two-matrix model. Qubits 0-5 encode matrix X1 modes; qubits 6-11 "
    "encode matrix X2 modes. Each layer applies RY on all 12 qubits, followed by "
    "the same ordered sequence of exactly 11 directed CNOT edges.\n\n"
    "PHYSICAL AUDIT OF PREVIOUS PROPOSAL:\n"
    "The previous proposal used an alternating bipartite ladder [0->6->1->7->2->8...]. "
    "While it achieved low raw energy error, independent physics verification revealed "
    "a severe failure: its gauge-singlet projection probability collapsed to 12.3% "
    "(compared to 34.0% for controls).\n\n"
    "REVISION OBJECTIVE:\n"
    "Revise the topology to balance intra-matrix entangling within each matrix block "
    "(qubits 0-5 and qubits 6-11) while maintaining necessary inter-matrix links. "
    "The undirected edges must form a connected spanning tree over all 12 qubits "
    "(no cycles, exactly 11 distinct edges, no self-edges). Aim to maximize physical "
    "gauge-singlet state overlap.\n\n"
    "Return only the JSON object with the 'edges' array; no explanatory prose."
)


def get_api_key():
    key = os.getenv("MODEL_API_KEY")
    if not key:
        env_file = ROOT / ".env"
        if env_file.exists():
            for line in env_file.read_text(encoding="utf-8").splitlines():
                if line.startswith("MODEL_API_KEY="):
                    key = line.split("=", 1)[1].strip()
                    break
    return key


def validate_tree(raw, qubits=12):
    """Enforces valid format, exactly qubits-1 edges, connected spanning tree (acyclic)."""
    edges = validate_proposal(raw, qubits)
    parent = list(range(qubits))

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    for control, target in edges:
        a, b = find(control), find(target)
        if a == b:
            raise ValueError("undirected CNOT graph contains a cycle or repeated edge")
        parent[a] = b
    if len({find(node) for node in range(qubits)}) != 1:
        raise ValueError("CNOT graph is disconnected")
    return edges


def main():
    parser = argparse.ArgumentParser(description="Run exactly one bounded Muse critique smoke test request.")
    parser.add_argument("--execute", action="store_true", help="Authorize spending tokens on exactly one API call.")
    args = parser.parse_args()

    request_spec = {
        "model": MODEL,
        "max_completion_tokens": 1024,
        "temperature": 0.2,
        "reasoning_effort": "minimal",
        "prompt_length_chars": len(CRITIQUE_PROMPT),
        "response_schema": "circuit_topology (edges array of [control, target])"
    }

    if not args.execute:
        print("=== DRY RUN (No network request sent, 0 tokens spent) ===")
        print("Request Specification:")
        print(json.dumps(request_spec, indent=2))
        print("\nCritique Prompt to be sent:")
        print("--------------------------------------------------")
        print(CRITIQUE_PROMPT)
        print("--------------------------------------------------")
        print("Run with --execute to perform this single bounded call.")
        return

    key = get_api_key()
    if not key:
        print("ERROR: MODEL_API_KEY not found in environment or .env.", file=sys.stderr)
        sys.exit(1)

    output_dir = ROOT / "muse_collection"
    output_dir.mkdir(exist_ok=True)
    receipt_file = output_dir / "muse_critique_smoke_receipt.json"
    proposal_file = output_dir / "muse_critique_proposal_02.json"

    if receipt_file.exists():
        print(f"Notice: Smoke receipt {receipt_file} already exists. Refusing to spend duplicate tokens.")
        print("To rerun, move or archive the previous receipt first.")
        sys.exit(0)

    print(f"Connecting to Meta API (https://api.meta.ai/v1) for model {MODEL}...")
    from openai import OpenAI
    client = OpenAI(base_url="https://api.meta.ai/v1", api_key=key, max_retries=0, timeout=30)

    start_time = time.time()
    call_timestamp = datetime.now(timezone.utc).isoformat()
    
    try:
        response = client.chat.completions.create(
            model=MODEL,
            messages=[{"role": "user", "content": CRITIQUE_PROMPT}],
            response_format=SCHEMA,
            max_completion_tokens=1024,
            reasoning_effort="minimal",
            temperature=0.2,
        )
        elapsed = round(time.time() - start_time, 2)
        usage = response.usage
        choice = response.choices[0]
        raw_content = choice.message.content
        finish_reason = choice.finish_reason

        receipt = {
            "timestamp_utc": call_timestamp,
            "model": MODEL,
            "elapsed_seconds": elapsed,
            "max_completion_tokens": 1024,
            "prompt_tokens": usage.prompt_tokens if usage else None,
            "completion_tokens": usage.completion_tokens if usage else None,
            "total_tokens": usage.total_tokens if usage else None,
            "finish_reason": finish_reason,
            "prompt_text": CRITIQUE_PROMPT,
            "raw_response": raw_content,
        }

        # Validate proposal with strict tree check
        try:
            parsed = json.loads(raw_content)
            edges = validate_tree(parsed, 12)
            receipt["validation"] = {
                "verdict": "PASSED",
                "edges_count": len(edges),
                "is_spanning_tree": True,
                "edges": edges
            }
            proposal_file.write_text(json.dumps({"edges": edges}, indent=2), encoding="utf-8")
            print(f"Validation PASSED: Received valid 11-CNOT spanning tree!")
        except Exception as ve:
            receipt["validation"] = {
                "verdict": "FAILED",
                "error": str(ve)
            }
            print(f"Validation FAILED: {ve}", file=sys.stderr)

        receipt_file.write_text(json.dumps(receipt, indent=2), encoding="utf-8")
        print(f"Receipt machine-logged to {receipt_file}")
        print(f"Token usage: {receipt['total_tokens']} total ({receipt['prompt_tokens']} prompt, {receipt['completion_tokens']} completion)")
        print(f"Finish reason: {finish_reason}")

    except Exception as e:
        elapsed = round(time.time() - start_time, 2)
        error_receipt = {
            "timestamp_utc": call_timestamp,
            "model": MODEL,
            "elapsed_seconds": elapsed,
            "error": str(e),
            "prompt_text": CRITIQUE_PROMPT,
            "validation": {"verdict": "CALL_ERROR"}
        }
        receipt_file.write_text(json.dumps(error_receipt, indent=2), encoding="utf-8")
        print(f"API call failed: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
"""One bounded Muse topology proposal. Dry-run by default; never retries calls.

Usage:
  python muse_one_shot.py
  python muse_one_shot.py --execute

Set MODEL_API_KEY in the environment or local .env for --execute. The key is never logged.
"""

import argparse
import json
import os
from datetime import datetime, timezone
from pathlib import Path

from candidate_bench import validate_proposal


ROOT = Path(__file__).resolve().parent
MODEL = "muse-spark-1.3"
PROMPT = (
    "Design one 12-qubit, two-layer variational circuit topology for a truncated "
    "SU(2) two-matrix Hamiltonian. Qubits 0-5 encode matrix X1 modes; 6-11 "
    "encode matrix X2 modes. Each layer applies RY on all 12 qubits, then the "
    "same ordered sequence of exactly 11 directed CNOT edges. Give exactly 11 "
    "distinct [control,target] edges with no self edge. The undirected edges "
    "must connect all 12 qubits as a spanning tree. Aim to represent "
    "inter-matrix correlations, but do not claim any measured advantage. "
    "Return only the edges; no prose."
)
SCHEMA = {
    "type": "json_schema",
    "json_schema": {
        "name": "circuit_topology",
        "schema": {
            "type": "object",
            "properties": {
                "edges": {
                    "type": "array",
                    "items": {
                        "type": "array",
                        "items": {"type": "integer"},
                    },
                },
            },
            "required": ["edges"],
            "additionalProperties": False,
        },
    },
}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--execute", action="store_true", help="Spend tokens on exactly one request")
    args = parser.parse_args()
    request = {
        "model": MODEL,
        "messages": [{"role": "user", "content": PROMPT}],
        "response_format": SCHEMA,
        "max_completion_tokens": 1024,
        "reasoning_effort": "minimal",
        "temperature": 0,
    }
    if not args.execute:
        print("DRY RUN: no request sent, no credits used")
        print(json.dumps({"model": MODEL, "max_output_tokens_including_reasoning": 1024,
                          "prompt_characters": len(PROMPT), "expected_output": "11 directed edges"}, indent=2))
        return
    output = ROOT / "muse_proposal_01.json"
    receipt = ROOT / "muse_proposal_01_receipt.json"
    if output.exists() or receipt.exists():
        raise FileExistsError("A first proposal already exists; refusing another paid request.")
    key = os.getenv("MODEL_API_KEY")
    if not key:
        env_file = ROOT / ".env"
        if env_file.exists():
            for line in env_file.read_text(encoding="utf-8").splitlines():
                if line.startswith("MODEL_API_KEY="):
                    key = line.split("=", 1)[1].strip()
                    break
    if not key:
        parser.error("MODEL_API_KEY is absent from the environment and local .env.")
    from openai import OpenAI

    client = OpenAI(base_url="https://api.meta.ai/v1", api_key=key,
                    max_retries=0, timeout=30)
    response = client.chat.completions.create(**request)
    usage = response.usage
    if not response.choices[0].message.content:
        failure = {
            "created_utc": datetime.now(timezone.utc).isoformat(),
            "model": MODEL,
            "finish_reason": response.choices[0].finish_reason,
            "prompt_tokens": usage.prompt_tokens if usage else None,
            "completion_tokens": usage.completion_tokens if usage else None,
            "note": "No visible proposal. No automatic retry.",
        }
        (ROOT / "muse_empty_response.json").write_text(json.dumps(failure, indent=2), encoding="utf-8")
        raise RuntimeError(f"Muse returned no visible proposal; finish_reason={failure['finish_reason']}")
    raw = json.loads(response.choices[0].message.content)
    edges = validate_proposal(raw, 12)
    reached = {edges[0][0]}
    while True:
        expanded = reached | {b for a, b in edges if a in reached} | {a for a, b in edges if b in reached}
        if expanded == reached:
            break
        reached = expanded
    if len(reached) != 12:
        raise ValueError("The paid response did not produce a connected topology; no automatic retry.")
    record = {
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "model": MODEL,
        "prompt": PROMPT,
        "edges": edges,
        "usage": {
            "prompt_tokens": usage.prompt_tokens if usage else None,
            "completion_tokens": usage.completion_tokens if usage else None,
            "total_tokens": usage.total_tokens if usage else None,
        },
        "evaluated": False,
        "note": "One model proposal only. No scientific result is implied.",
    }
    output.write_text(json.dumps({"edges": edges}, indent=2), encoding="utf-8")
    receipt.write_text(json.dumps(record, indent=2), encoding="utf-8")
    print(f"Saved one proposal to {output}; token usage: {record['usage']}")


if __name__ == "__main__":
    main()
"""Run an additional-coupling comparison of one Muse tree with random trees.

Protocol:
- Coupling: lambda = 1.5 (not used in the previous exploratory search)
- Exact symmetry-preserving benchmark: N_total <= 4 cutoff
- Matched resources per candidate, with unequal candidate counts:
  - 12 qubits, 11 CNOTs per layer, 24 RY parameters (depth 2)
  - 3 optimizer seeds (seeds: 0, 1, 2)
  - 300 evaluations per seed (COBYLA)
- Candidates:
  - Fixed Baseline: cross_budget
  - Random Trees: 5 random recursive trees under random relabeling from a fixed seed
  - Model Candidate(s): Muse Proposal 01 (and structured critique iterations if simulated)
- Reports both Physical Energy Error and Gauge-Singlet Projection Probability

This is not an independently pre-registered, blinded, or matched-search test.
"""

import json
from pathlib import Path
import numpy as np

from candidate_bench import baseline, validate_proposal
from evaluate_physical import evaluate
from local_search_test import random_tree

ROOT = Path(__file__).resolve().parent
HOLDOUT_LAMBDA = 1.5
BUDGET = 300
SEEDS = [0, 1, 2]
MAX_TOTAL = 4


def generate_matched_candidates():
    candidates = {}
    
    # 1. Fixed hand-designed
    candidates["cross_budget"] = {
        "name": "Fixed cross_budget",
        "type": "fixed",
        "edges": baseline(12, "cross_budget")
    }
    
    # 2. Muse proposal 01 (The one verified proposal obtained from Muse Spark 1.3)
    muse_proposal = json.loads((ROOT / "muse_proposal_01.json").read_text(encoding="utf-8"))
    candidates["muse_proposal_01"] = {
        "name": "Muse Proposal 01",
        "type": "muse",
        "edges": validate_proposal(muse_proposal, 12)
    }
    
    # 3. Five random recursive trees under random relabeling from a fixed RNG seed
    rng = np.random.default_rng(20261027)
    for i in range(1, 6):
        tree_edges = random_tree(rng)
        candidates[f"random_tree_{i:02d}"] = {
            "name": f"Random Tree #{i:02d}",
            "type": "random",
            "edges": tree_edges
        }
        
    return candidates


def run_holdout_benchmark():
    candidates = generate_matched_candidates()
    print(f"Running additional-coupling comparison at lambda={HOLDOUT_LAMBDA}...")
    print(f"Protocol: Cutoff N_total<={MAX_TOTAL}, Seeds={SEEDS}, Budget={BUDGET}/seed")
    
    results = {
        "benchmark_protocol": "Additional-coupling comparison with exact SU(2) gauge-singlet projection; matched per-candidate resources, unequal candidate counts; not blinded or pre-registered",
        "holdout_lambda": HOLDOUT_LAMBDA,
        "max_total_occupation": MAX_TOTAL,
        "budget_per_seed": BUDGET,
        "seeds": SEEDS,
        "gate_budget": "11 CNOTs per layer, 24 RY parameters, depth 2",
        "candidates": []
    }
    
    for key, info in candidates.items():
        print(f"  Evaluating {key} ({info['name']})...", end=" ", flush=True)
        res = evaluate(info["edges"], HOLDOUT_LAMBDA, MAX_TOTAL, SEEDS, BUDGET)
        res["candidate_id"] = key
        res["candidate_name"] = info["name"]
        res["candidate_type"] = info["type"]
        res["edges"] = info["edges"]
        results["candidates"].append(res)
        print(f"Energy Err={res['median_energy_error']:.6f}, Singlet P={res['median_singlet_overlap_probability']:.3f}")
        
    out_file = ROOT / "holdout_benchmark_results.json"
    out_file.write_text(json.dumps(results, indent=2), encoding="utf-8")
    print(f"Saved holdout benchmark results to {out_file}")
    return results


if __name__ == "__main__":
    run_holdout_benchmark()
"""Bounded candidate evaluation runner with an optional single Muse API call.

Adheres strictly to INDEPENDENT_REVIEW_2026-10-27.md:
- Pre-declared frozen protocol at lambda = 0.8
- Five non-random designs (one verified Muse proposal, four structured hypotheses) vs five random trees
- Historical event summaries are retrospective; only the saved Muse response has verified usage
- Explicit gatekeeper validation: 12 qubits, 11 edges, connected spanning tree
- Real evaluation on physical benchmark reporting median energy error and singlet probability
- Saves candidate results and any new API receipt to local JSON files
"""

import argparse
import json
import os
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import numpy as np

from candidate_bench import baseline, validate_proposal
from evaluate_physical import evaluate
from local_search_test import random_tree

ROOT = Path(__file__).resolve().parent
MODEL = "muse-spark-1.3"
TARGET_LAMBDA = 0.8
MAX_TOTAL = 4
BUDGET = 300
SEEDS = [0, 1, 2]

SCHEMA = {
    "type": "json_schema",
    "json_schema": {
        "name": "circuit_topology",
        "schema": {
            "type": "object",
            "properties": {
                "edges": {
                    "type": "array",
                    "items": {
                        "type": "array",
                        "items": {"type": "integer"},
                    },
                },
            },
            "required": ["edges"],
            "additionalProperties": False,
        },
    },
}

INITIAL_PROMPT = (
    "Design one 12-qubit, two-layer variational circuit topology for a truncated "
    "SU(2) two-matrix Hamiltonian. Qubits 0-5 encode matrix X1 modes; 6-11 "
    "encode matrix X2 modes. Each layer applies RY on all 12 qubits, then the "
    "same ordered sequence of exactly 11 directed CNOT edges. Give exactly 11 "
    "distinct [control,target] edges with no self edge. The undirected edges "
    "must connect all 12 qubits as a spanning tree. Aim to represent "
    "inter-matrix correlations, but do not claim any measured advantage. "
    "Return only the edges; no prose."
)


def validate_tree(raw, qubits=12):
    """Require an undirected spanning tree as well as valid directed CNOT pairs."""
    edges = validate_proposal(raw, qubits)
    parent = list(range(qubits))

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    for control, target in edges:
        a, b = find(control), find(target)
        if a == b:
            raise ValueError("undirected CNOT graph contains a cycle or repeated edge")
        parent[a] = b
    if len({find(node) for node in range(qubits)}) != 1:
        raise ValueError("CNOT graph is disconnected")
    return edges


def get_api_key():
    key = os.getenv("MODEL_API_KEY")
    if not key:
        env_file = ROOT / ".env"
        if env_file.exists():
            for line in env_file.read_text(encoding="utf-8").splitlines():
                if line.startswith("MODEL_API_KEY="):
                    key = line.split("=", 1)[1].strip()
                    break
    return key


def call_muse_api(prompt, key, max_tokens=1024):
    """Executes exactly one bounded call to Meta Muse API with zero retries."""
    from openai import OpenAI
    client = OpenAI(base_url="https://api.meta.ai/v1", api_key=key, max_retries=0, timeout=30)
    request = {
        "model": MODEL,
        "messages": [{"role": "user", "content": prompt}],
        "response_format": SCHEMA,
        "max_completion_tokens": max_tokens,
        "reasoning_effort": "minimal",
        "temperature": 0.2,
    }
    t0 = time.time()
    response = client.chat.completions.create(**request)
    elapsed = time.time() - t0
    usage = response.usage
    content = response.choices[0].message.content
    finish_reason = response.choices[0].finish_reason
    receipt = {
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "model": MODEL,
        "max_completion_tokens": max_tokens,
        "elapsed_seconds": round(elapsed, 2),
        "prompt_tokens": usage.prompt_tokens if usage else None,
        "completion_tokens": usage.completion_tokens if usage else None,
        "total_tokens": usage.total_tokens if usage else None,
        "finish_reason": finish_reason,
        "raw_content": content,
    }
    return receipt, content


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--execute-api", action="store_true", help="Send live bounded API requests to Muse (requires valid key)")
    parser.add_argument("--cap-requests", type=int, default=1, help="Hard maximum limit on API calls")
    args = parser.parse_args()

    print(f"=== HorizonForge Topology Comparison (lambda={TARGET_LAMBDA}) ===")
    
    # 1. Initialize Receipts / Trial Records
    trial_log_path = ROOT / "iterative_loop_receipts.json"
    if trial_log_path.exists():
        trial_records = json.loads(trial_log_path.read_text(encoding="utf-8"))
    else:
        trial_records = {
            "protocol": "FROZEN_PROTOCOL_LAMBDA_08.md",
            "model": MODEL,
            "trials": []
        }

    # 2. Candidate Storage
    muse_candidates = []
    
    # Check if we have existing Muse Proposal 01
    prop01_path = ROOT / "muse_proposal_01.json"
