DEFAULT_RESULTS_PATH = ROOT / "muse_collection" / "lambda12_holdout_results.json"


def compute_file_sha256(filepath: Path) -> str:
    """Compute the SHA256 hexadecimal digest of a file in streaming chunks."""
    target = Path(filepath)
    if not target.is_file():
        raise FileNotFoundError(f"File not found for SHA256 computation: {target}")
    hasher = hashlib.sha256()
    with open(target, "rb") as f:
        while chunk := f.read(65536):
            hasher.update(chunk)
    return hasher.hexdigest()


def atomic_write_json(filepath: Path, data: Any) -> None:
    """Atomically write JSON data using a temporary file and atomic replacement."""
    target = Path(filepath)
    target.parent.mkdir(parents=True, exist_ok=True)
    temp_file = target.with_suffix(f".tmp_{os.getpid()}_{time.time_ns()}.json")
    with open(temp_file, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
        f.flush()
        try:
            os.fsync(f.fileno())
        except OSError:
            pass
    temp_file.replace(target)


def sanitize_for_json(obj: Any) -> Any:
    """Recursively convert NumPy scalars and containers to standard Python types."""
    if isinstance(obj, bool):
        return obj
    if isinstance(obj, (np.integer, int)):
        return int(obj)
    if isinstance(obj, (np.floating, float)):
        return float(obj)
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, dict):
        return {k: sanitize_for_json(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [sanitize_for_json(x) for x in obj]
    return obj


def validate_spanning_tree(edges: Any, qubits: int = QUBITS) -> List[List[int]]:
    """Validate that edges form an acyclic, connected spanning tree on qubits.

    Enforces:
    - Exactly (qubits - 1) distinct directed edges [u, v].
    - Node indices within [0, qubits - 1].
    - No self-loops [u, u].
    - Connected and acyclic as an undirected graph.
    Returns normalized list of integer pairs [[int(u), int(v)], ...].
    """
    if not isinstance(edges, list) or len(edges) != qubits - 1:
        raise ValueError(f"Expected exactly {qubits - 1} edges, got {len(edges) if isinstance(edges, list) else type(edges)}")

    seen_directed = set()
    parent = list(range(qubits))

    def find(node: int) -> int:
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    normalized_edges: List[List[int]] = []
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            raise ValueError(f"Invalid edge representation (must be [u, v]): {edge}")
        try:
            u, v = int(edge[0]), int(edge[1])
        except (TypeError, ValueError) as err:
            raise ValueError(f"Non-integer node indices in edge {edge}: {err}") from err

        if u < 0 or u >= qubits or v < 0 or v >= qubits:
            raise ValueError(f"Qubit index out of range [0, {qubits - 1}]: [{u}, {v}]")
        if u == v:
            raise ValueError(f"Self-loop edge forbidden: [{u}, {v}]")
        if (u, v) in seen_directed:
            raise ValueError(f"Duplicate directed edge: [{u}, {v}]")
        seen_directed.add((u, v))
        normalized_edges.append([u, v])

        root_u, root_v = find(u), find(v)
        if root_u == root_v:
            raise ValueError(f"Cycle detected in undirected topology when adding edge [{u}, {v}]")
        parent[root_u] = root_v

    distinct_components = {find(node) for node in range(qubits)}
    if len(distinct_components) != 1:
        raise ValueError(f"Graph is disconnected into {len(distinct_components)} components")

    return normalized_edges


def verify_locked_files(root: Path = ROOT) -> Dict[str, str]:
    """Verify exact SHA256 of locked manifest, random controls, and evaluator.

    Fails closed on any hash mismatch or missing file.
    """
    actual_hashes: Dict[str, str] = {}
    for key, spec in LOCKED_HASHES.items():
        file_path = root / spec["rel_path"]
        if not file_path.is_file():
            raise FileNotFoundError(f"Locked file does not exist: {file_path}")
        computed = compute_file_sha256(file_path)
        expected = spec["expected_sha256"]
        if computed != expected:
            raise ValueError(
                f"SHA256 mismatch for locked {key} ({file_path}): expected {expected}, got {computed}"
            )
        actual_hashes[key] = computed
    return actual_hashes


def extract_receipt_edges(receipt_data: Dict[str, Any]) -> List[List[int]]:
    """Extract candidate edges recorded in a Muse receipt file."""
    if isinstance(receipt_data.get("validation"), dict) and "edges" in receipt_data["validation"]:
        return receipt_data["validation"]["edges"]
    if "edges" in receipt_data and isinstance(receipt_data["edges"], list):
        return receipt_data["edges"]
    if "raw_response" in receipt_data:
        try:
            parsed = json.loads(receipt_data["raw_response"])
            if isinstance(parsed, dict) and "edges" in parsed and isinstance(parsed["edges"], list):
                return parsed["edges"]
        except Exception:
            pass
    raise ValueError("No valid edges found in receipt structure")


def load_and_verify_manifest(root: Path = ROOT) -> List[Dict[str, Any]]:
    """Verify manifest contents, file hashes, and edge integrity for Muse cohort.

    Fails closed on unexpected candidate count, order, hash mismatch, or edge disparity.
    """
    manifest_path = root / LOCKED_HASHES["manifest"]["rel_path"]
    data = json.loads(manifest_path.read_text(encoding="utf-8"))

    if data.get("valid_proposals_count") != 5 or data.get("target_cohort_size") != 5:
        raise ValueError("Manifest valid_proposals_count or target_cohort_size is not 5")
    if not data.get("is_complete_cohort"):
        raise ValueError("Manifest is_complete_cohort flag is false")

    candidates = data.get("candidates", [])
    if len(candidates) != 5:
        raise ValueError(f"Expected exactly 5 candidates in manifest, found {len(candidates)}")

    actual_ids = [c.get("candidate_id") for c in candidates]
    if actual_ids != EXPECTED_MUSE_ORDER:
        raise ValueError(f"Manifest candidate order mismatch: expected {EXPECTED_MUSE_ORDER}, got {actual_ids}")

    verified_muse: List[Dict[str, Any]] = []
    for cand in candidates:
        cid = cand["candidate_id"]
        prop_rel = Path(cand["proposal_file"])
        rec_rel = Path(cand["receipt_file"])

        prop_path = root / prop_rel if (root / prop_rel).is_file() else root / "muse_collection" / prop_rel.name
        rec_path = root / rec_rel if (root / rec_rel).is_file() else root / "muse_collection" / rec_rel.name

        if not prop_path.is_file():
            raise FileNotFoundError(f"Proposal file missing for {cid}: {prop_path}")
        if not rec_path.is_file():
            raise FileNotFoundError(f"Receipt file missing for {cid}: {rec_path}")

        # Hash integrity check
        prop_sha = compute_file_sha256(prop_path)
        if prop_sha != cand["proposal_sha256"]:
            raise ValueError(f"Proposal SHA256 mismatch for {cid}: expected {cand['proposal_sha256']}, got {prop_sha}")

        rec_sha = compute_file_sha256(rec_path)
        if rec_sha != cand["receipt_sha256"]:
            raise ValueError(f"Receipt SHA256 mismatch for {cid}: expected {cand['receipt_sha256']}, got {rec_sha}")

        # Proposal edge integrity & tree check
        prop_json = json.loads(prop_path.read_text(encoding="utf-8"))
        prop_edges = validate_spanning_tree(prop_json.get("edges"), QUBITS)

        # Receipt edge comparison
        rec_json = json.loads(rec_path.read_text(encoding="utf-8"))
        rec_edges = validate_spanning_tree(extract_receipt_edges(rec_json), QUBITS)

        if prop_edges != rec_edges:
            raise ValueError(f"Edge mismatch between proposal file and receipt for {cid}")

        verified_muse.append({
            "candidate_id": cid,
            "name": cand.get("name", cid),
            "cohort": "muse",
            "edges": prop_edges,
            "provenance": {
                "source": "model_cohort_manifest.json",
                "call_id": cand.get("call_id"),
                "proposal_file": str(prop_rel),
                "proposal_sha256": prop_sha,
                "receipt_file": str(rec_rel),
                "receipt_sha256": rec_sha,
            },
        })

    return verified_muse


def load_and_verify_random_controls(root: Path = ROOT) -> List[Dict[str, Any]]:
    """Verify controls file, count, order, and validate all 5 trees as 12-node spanning trees."""
    controls_path = root / LOCKED_HASHES["random_controls"]["rel_path"]
    data = json.loads(controls_path.read_text(encoding="utf-8"))

    controls = data.get("controls", [])
    if len(controls) != 5:
        raise ValueError(f"Expected 5 controls in frozen random controls, found {len(controls)}")

    actual_ids = [c.get("control_id") for c in controls]
    if actual_ids != EXPECTED_CONTROL_ORDER:
        raise ValueError(f"Random controls order mismatch: expected {EXPECTED_CONTROL_ORDER}, got {actual_ids}")

    verified_controls: List[Dict[str, Any]] = []
    for ctrl in controls:
        cid = ctrl["control_id"]
        raw_edges = ctrl.get("edges")
        edges = validate_spanning_tree(raw_edges, QUBITS)
        verified_controls.append({
            "candidate_id": cid,
            "name": ctrl.get("name", cid),
            "cohort": "random_ust",
            "edges": edges,
            "provenance": {
                "source": "frozen_random_controls_lambda12.json",
                "seed": ctrl.get("seed"),
                "algorithm": ctrl.get("algorithm"),
            },
        })

    return verified_controls


def load_and_verify_reference() -> Dict[str, Any]:
    """Generate and validate the fixed cross_budget reference baseline."""
    raw_edges = baseline(QUBITS, "cross_budget")
    edges = validate_spanning_tree(raw_edges, QUBITS)
    return {
        "candidate_id": "cross_budget",
        "name": "Fixed Cross-Budget Baseline",
        "cohort": "reference",
        "edges": edges,
        "provenance": {
            "source": "candidate_bench.baseline(12, 'cross_budget')",
            "edges_count": len(edges),
            "excluded_from_cohort_summaries": True,
        },
    }


def assemble_all_layouts(root: Path = ROOT) -> List[Dict[str, Any]]:
    """Assemble all eleven locked topologies in exact evaluation order."""
    muse = load_and_verify_manifest(root)
    random_controls = load_and_verify_random_controls(root)
    reference = load_and_verify_reference()
    return muse + random_controls + [reference]


def calculate_utility(delta_e: float, p_phys: float, epsilon: float = REGULARIZATION_EPSILON) -> float:
    """Compute regularized ratio utility S = P_phys / (Delta E + 0.005).

    Computed strictly from the reported medians as defined in the protocol.
    """
    denom = delta_e + epsilon
    if denom <= 0:
        raise ValueError(f"Non-positive denominator in utility calculation: {denom}")
    return float(p_phys / denom)


def check_pareto_dominance(a: Dict[str, Any], b: Dict[str, Any]) -> bool:
    """Return True if candidate 'a' Pareto-dominates candidate 'b'.

    Objectives:
    - Delta E (median_energy_error): minimize
    - P_phys (median_singlet_overlap_probability): maximize
    Dominance: a is as good as b on both, and strictly better on at least one.
    """
    err_a, p_a = a["median_energy_error"], a["median_singlet_overlap_probability"]
    err_b, p_b = b["median_energy_error"], b["median_singlet_overlap_probability"]

    not_worse = (err_a <= err_b) and (p_a >= p_b)
    strictly_better = (err_a < err_b) or (p_a > p_b)
    return bool(not_worse and strictly_better)


def compute_cohort_statistics(candidates: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Compute best-of-cohort, median-of-cohort, underlying metrics, and per-seed spreads."""
    if not candidates:
        return {}

    utilities = [c["utility"] for c in candidates]
    delta_es = [c["median_energy_error"] for c in candidates]
    p_physes = [c["median_singlet_overlap_probability"] for c in candidates]

    # Best-of-cohort based on utility S
    best_idx = int(np.argmax(utilities))
    best_cand = candidates[best_idx]

    best_trials = best_cand["trials"]
    best_ee_spread = [float(t["energy_error"]) for t in best_trials]
    best_p_spread = [float(t["singlet_overlap_probability"]) for t in best_trials]

    # Detailed per-candidate spread information across cohort
    candidate_breakdown = []
    for c in candidates:
        c_trials = c["trials"]
        ee_vals = [float(t["energy_error"]) for t in c_trials]
        p_vals = [float(t["singlet_overlap_probability"]) for t in c_trials]
        candidate_breakdown.append({
            "candidate_id": c["candidate_id"],
            "utility": float(c["utility"]),
            "median_energy_error": float(c["median_energy_error"]),
            "energy_error_min": min(ee_vals),
            "energy_error_max": max(ee_vals),
            "median_singlet_overlap_probability": float(c["median_singlet_overlap_probability"]),
            "singlet_overlap_min": min(p_vals),
            "singlet_overlap_max": max(p_vals),
        })

    return {
        "candidate_count": len(candidates),
        "best_candidate_id": best_cand["candidate_id"],
        "best_candidate_name": best_cand["name"],
        "best_utility": float(utilities[best_idx]),
        "best_median_energy_error": float(best_cand["median_energy_error"]),
        "best_median_singlet_overlap_probability": float(best_cand["median_singlet_overlap_probability"]),
        "best_per_seed_energy_errors": best_ee_spread,
        "best_per_seed_singlet_probabilities": best_p_spread,
        "median_cohort_utility": float(np.median(utilities)),
        "median_cohort_energy_error": float(np.median(delta_es)),
        "median_cohort_singlet_overlap_probability": float(np.median(p_physes)),
        "candidate_breakdown": candidate_breakdown,
    }


def compute_pareto_analysis(
    muse_cands: List[Dict[str, Any]],
    random_cands: List[Dict[str, Any]],
    reference_cand: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Perform pairwise Pareto dominance and identify overall non-dominated layouts."""
    muse_dominates_random = []
    random_dominates_muse = []

    for m in muse_cands:
        for r in random_cands:
            if check_pareto_dominance(m, r):
                muse_dominates_random.append({
                    "dominator": m["candidate_id"],
                    "dominated": r["candidate_id"],
                    "delta_e_comparison": [m["median_energy_error"], r["median_energy_error"]],
                    "p_phys_comparison": [m["median_singlet_overlap_probability"], r["median_singlet_overlap_probability"]],
                })
            elif check_pareto_dominance(r, m):
                random_dominates_muse.append({
                    "dominator": r["candidate_id"],
                    "dominated": m["candidate_id"],
                    "delta_e_comparison": [r["median_energy_error"], m["median_energy_error"]],
                    "p_phys_comparison": [r["median_singlet_overlap_probability"], m["median_singlet_overlap_probability"]],
                })

    # Best-of-cohort Pareto comparison
    best_muse = max(muse_cands, key=lambda c: c["utility"]) if muse_cands else None
    best_random = max(random_cands, key=lambda c: c["utility"]) if random_cands else None
    best_muse_dominates_best_random = bool(best_muse and best_random and check_pareto_dominance(best_muse, best_random))
    best_random_dominates_best_muse = bool(best_muse and best_random and check_pareto_dominance(best_random, best_muse))

    # Global Pareto frontier across all 11 candidates (or all available)
    pool = list(muse_cands) + list(random_cands)
    if reference_cand:
        pool.append(reference_cand)

    frontier_ids = []
    for candidate in pool:
        dominated = False
        for competitor in pool:
            if candidate is not competitor and check_pareto_dominance(competitor, candidate):
                dominated = True
                break
        if not dominated:
            frontier_ids.append(candidate["candidate_id"])

    return {
        "muse_dominates_random_pairs": muse_dominates_random,
        "random_dominates_muse_pairs": random_dominates_muse,
        "best_muse_dominates_best_random": best_muse_dominates_best_random,
        "best_random_dominates_best_muse": best_random_dominates_best_muse,
        "pareto_frontier_candidate_ids": frontier_ids,
    }


def compute_all_summaries(candidates: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Compute separated cohort summaries and Pareto analysis."""
    muse = [c for c in candidates if c["cohort"] == "muse"]
    random_ust = [c for c in candidates if c["cohort"] == "random_ust"]
    reference_list = [c for c in candidates if c["cohort"] == "reference"]
    reference = reference_list[0] if reference_list else None

    muse_summary = compute_cohort_statistics(muse)
    random_summary = compute_cohort_statistics(random_ust)
    pareto_summary = compute_pareto_analysis(muse, random_ust, reference)

    ref_summary = None
    if reference:
        ref_trials = reference["trials"]
        ref_summary = {
            "candidate_id": reference["candidate_id"],
            "utility": float(reference["utility"]),
            "median_energy_error": float(reference["median_energy_error"]),
            "median_singlet_overlap_probability": float(reference["median_singlet_overlap_probability"]),
            "per_seed_energy_errors": [float(t["energy_error"]) for t in ref_trials],
            "per_seed_singlet_probabilities": [float(t["singlet_overlap_probability"]) for t in ref_trials],
            "note": "Reference baseline; excluded from Muse and Random UST cohort summary statistics.",
        }

    return {
        "muse_cohort": muse_summary,
        "random_ust_cohort": random_summary,
        "reference_baseline": ref_summary,
        "pareto_analysis": pareto_summary,
        "claim_notice": (
            "Observed sample results only (N=5 per cohort, 3 optimizer seeds). "
            "No claims of general superiority or statistical significance are made."
        ),
    }


def print_dry_run_report(candidates: List[Dict[str, Any]], locked_hashes: Dict[str, str]) -> None:
    """Print clean validation table for --dry-run without touching lambda = 1.2."""
    print("=" * 80)
    print("  LOCKED HOLDOUT INPUT VALIDATION (LAMBDA = 1.2) - DRY RUN")
    print("=" * 80)
    print("\n[Locked Input Hashes from HOLDOUT_EXECUTION_LOCK_LAMBDA_12.md]")
    for key, spec in LOCKED_HASHES.items():
        actual = locked_hashes[key]
        status = "PASSED" if actual == spec["expected_sha256"] else "FAILED"
        print(f"  {key:16s}: {actual} [{status}]")

    print("\n[Locked Topologies Queue (11 Candidates in Strict Call/File Order)]")
    print("-" * 80)
    print(f"{'#':2s}  {'Candidate ID':26s}  {'Cohort':12s}  {'Edges':5s}  {'Tree':6s}  {'Provenance Source'}")
    print("-" * 80)
    for idx, c in enumerate(candidates, 1):
        cid = c["candidate_id"]
        cohort = c["cohort"]
        n_edges = len(c["edges"])
        source = c["provenance"].get("source", "N/A")
        if "call_id" in c["provenance"]:
            source += f" ({c['provenance']['call_id']})"
        elif "seed" in c["provenance"]:
            source += f" (seed={c['provenance']['seed']})"
        print(f"{idx:2d}. {cid:26s}  {cohort:12s}  {n_edges:5d}  PASSED  {source}")

    print("-" * 80)
    print("[DRY RUN VERDICT] All 11 topologies verified as valid 12-qubit spanning trees.")
    print("[SAFETY CERTIFICATION] Zero lambda = 1.2 physics evaluations or Meta Muse calls executed.")
    print("=" * 80)


def print_live_summary_report(results: Dict[str, Any]) -> None:
    """Print complete summary table after live holdout evaluation."""
    print("\n" + "=" * 80)
    print("  LAMBDA = 1.2 HOLDOUT EVALUATION COMPLETE REPORT")
    print("=" * 80)
    cands = results.get("candidates", [])
    print(f"\n{'Candidate ID':26s}  {'Cohort':11s}  {'Delta E':11s}  {'P_phys':10s}  {'Utility S':10s}")
    print("-" * 80)
    for c in cands:
        cid = c["candidate_id"]
        cohort = c["cohort"]
        de = c["median_energy_error"]
        p = c["median_singlet_overlap_probability"]
        u = c["utility"]
        print(f"{cid:26s}  {cohort:11s}  {de:11.6f}  {p:10.4f}  {u:10.4f}")
    print("-" * 80)

    summaries = results.get("cohort_summaries", {})
    muse = summaries.get("muse_cohort", {})
    rand = summaries.get("random_ust_cohort", {})
    ref = summaries.get("reference_baseline", {})
    pareto = summaries.get("pareto_analysis", {})

    print("\n[Cohort Utility Metrics]")
    if muse:
        print(f"  Muse Best:         {muse.get('best_candidate_id')} with S = {muse.get('best_utility'):.4f} "
              f"(Delta E = {muse.get('best_median_energy_error'):.6f}, P_phys = {muse.get('best_median_singlet_overlap_probability'):.4f})")
        print(f"  Muse Median:       S = {muse.get('median_cohort_utility'):.4f} "
              f"(Delta E = {muse.get('median_cohort_energy_error'):.6f}, P_phys = {muse.get('median_cohort_singlet_overlap_probability'):.4f})")
    if rand:
        print(f"  Random UST Best:   {rand.get('best_candidate_id')} with S = {rand.get('best_utility'):.4f} "
              f"(Delta E = {rand.get('best_median_energy_error'):.6f}, P_phys = {rand.get('best_median_singlet_overlap_probability'):.4f})")
        print(f"  Random UST Median: S = {rand.get('median_cohort_utility'):.4f} "
              f"(Delta E = {rand.get('median_cohort_energy_error'):.6f}, P_phys = {rand.get('median_cohort_singlet_overlap_probability'):.4f})")
    if ref:
        print(f"  Reference Baseline (cross_budget): S = {ref.get('utility'):.4f} "
              f"(Delta E = {ref.get('median_energy_error'):.6f}, P_phys = {ref.get('median_singlet_overlap_probability'):.4f})")

    print("\n[Pareto Frontier]")
    frontier = pareto.get("pareto_frontier_candidate_ids", [])
    print(f"  Non-dominated layout IDs: {', '.join(frontier) if frontier else 'None'}")
    print(f"  Best Muse dominates Best Random UST? {pareto.get('best_muse_dominates_best_random')}")
    print(f"  Best Random UST dominates Best Muse? {pareto.get('best_random_dominates_best_muse')}")

    print("\n[Notice]")
    print(f"  {summaries.get('claim_notice')}")
    print("=" * 80)


def run_holdout(
    dry_run: bool = False,
    results_path: Optional[Path] = None,
    root: Path = ROOT,
) -> int:
    """Execute the holdout runner workflow."""
    results_path = results_path or DEFAULT_RESULTS_PATH

    # 1. Verification of all locked inputs
    locked_hashes = verify_locked_files(root)
    all_layouts = assemble_all_layouts(root)

    # 2. Dry-run mode: report and exit 0 without touching lambda = 1.2
    if dry_run:
        print_dry_run_report(all_layouts, locked_hashes)
        return 0

    # 3. Validate existing results before starting any live evaluation.
    existing_records: Dict[str, Dict[str, Any]] = {}
    started_timestamp = datetime.now(timezone.utc).isoformat()

    if results_path.exists() and not results_path.is_file():
        raise ValueError(f"Results path exists but is not a file: {results_path}")

    if results_path.is_file():
        try:
            prior_data = json.loads(results_path.read_text(encoding="utf-8"))
            expected_header = {
                "target_lambda": TARGET_LAMBDA,
                "max_total_occupation": MAX_TOTAL_OCCUPATION,
                "budget_per_seed": BUDGET_PER_SEED,
                "seeds": SEEDS,
                "locked_hashes": locked_hashes,
                "evaluator_version": f"evaluate_physical.py ({locked_hashes['evaluator']})",
                "total_candidates_count": len(all_layouts),
            }
            for field, expected in expected_header.items():
                if prior_data.get(field) != expected:
                    raise ValueError(f"Existing results have a different {field}; refusing overwrite")
            saved_candidates = prior_data.get("candidates")
            if not isinstance(saved_candidates, list) or len(saved_candidates) > len(all_layouts):
                raise ValueError("Existing results have an invalid candidate list")
            if prior_data.get("completed_candidates_count") != len(saved_candidates):
                raise ValueError("Existing results candidate count is inconsistent")
            expected_status = "COMPLETE" if len(saved_candidates) == len(all_layouts) else "IN_PROGRESS"
            if prior_data.get("status") != expected_status:
                raise ValueError("Existing results status is inconsistent")
            if expected_status == "COMPLETE" and not prior_data.get("cohort_summaries"):
                raise ValueError("Complete results are missing cohort summaries")
            for idx, rec in enumerate(saved_candidates):
                layout = all_layouts[idx]
                for field in ("candidate_id", "cohort", "edges", "provenance"):
                    if rec.get(field) != layout[field]:
                        raise ValueError(f"Existing result {idx + 1} has a different {field}; refusing overwrite")
                trials = rec.get("trials")
                if not isinstance(trials, list) or [trial.get("seed") for trial in trials] != SEEDS:
                    raise ValueError(f"Existing result {idx + 1} has incomplete optimizer trials")
                existing_records[rec["candidate_id"]] = rec
            started_timestamp = prior_data.get("timestamp_started_utc", started_timestamp)
            print(f"[RESTART] Found existing results file with {len(existing_records)} recorded candidates.")
        except Exception as err:
            raise RuntimeError(f"Failed to read existing results file at {results_path}: {err}") from err

    print("=" * 80)
    print("  EXECUTING SU(2) HOLDOUT BENCHMARK AT LAMBDA = 1.2")
    print(f"  Evaluating {len(all_layouts)} locked candidate layouts (COBYLA budget={BUDGET_PER_SEED}, seeds={SEEDS})")
    print("=" * 80)

    completed_candidates: List[Dict[str, Any]] = []

    for idx, layout in enumerate(all_layouts, 1):
        cid = layout["candidate_id"]
        cohort = layout["cohort"]
        edges = layout["edges"]

        if cid in existing_records:
            saved = existing_records[cid]
            # Safety check: saved input must strictly match locked input
            if saved.get("cohort") != cohort:
                raise ValueError(f"Saved cohort mismatch for {cid}: saved {saved.get('cohort')} != expected {cohort}")
            if saved.get("edges") != edges:
                raise ValueError(f"Saved edges mismatch for {cid}: refusing to silently overwrite or rerun")
            completed_candidates.append(saved)
            print(f"[{idx:2d}/11] {cid:26s} ({cohort:10s}): [REUSED CHECKPOINT] utility={saved.get('utility', 0.0):.4f}")
            continue

        print(f"[{idx:2d}/11] {cid:26s} ({cohort:10s}): Evaluating across seeds {SEEDS} (COBYLA {BUDGET_PER_SEED})...", flush=True)
        t_start = time.time()
        eval_result = evaluate_physical.evaluate(edges, TARGET_LAMBDA, MAX_TOTAL_OCCUPATION, SEEDS, BUDGET_PER_SEED)
        elapsed = round(time.time() - t_start, 2)

        delta_e = float(eval_result["median_energy_error"])
        p_phys = float(eval_result["median_singlet_overlap_probability"])
        utility = calculate_utility(delta_e, p_phys)

        record: Dict[str, Any] = {
            "candidate_id": cid,
            "name": layout["name"],
            "cohort": cohort,
            "edges": edges,
            "provenance": layout["provenance"],
            "exact_physical_ground_energy": float(eval_result["exact_physical_ground_energy"]),
            "trials": eval_result["trials"],
            "median_energy_error": delta_e,
            "median_singlet_overlap_probability": p_phys,
            "utility": utility,
            "evaluation_seconds": elapsed,
            "completed_timestamp_utc": datetime.now(timezone.utc).isoformat(),
        }
        completed_candidates.append(record)
        print(f"        Finished in {elapsed}s: Delta E={delta_e:.6f}, P_phys={p_phys:.4f}, Utility={utility:.4f}")

        # Safe checkpoint persist after each candidate
        is_all_done = (len(completed_candidates) == len(all_layouts))
        summaries = compute_all_summaries(completed_candidates) if is_all_done else {}

        payload: Dict[str, Any] = {
            "timestamp_started_utc": started_timestamp,
            "timestamp_updated_utc": datetime.now(timezone.utc).isoformat(),
            "target_lambda": TARGET_LAMBDA,
            "max_total_occupation": MAX_TOTAL_OCCUPATION,
            "budget_per_seed": BUDGET_PER_SEED,
            "seeds": SEEDS,
            "locked_hashes": {k: v["expected_sha256"] for k, v in LOCKED_HASHES.items()},
            "evaluator_version": f"evaluate_physical.py ({LOCKED_HASHES['evaluator']['expected_sha256']})",
            "status": "COMPLETE" if is_all_done else "IN_PROGRESS",
            "completed_candidates_count": len(completed_candidates),
            "total_candidates_count": len(all_layouts),
            "candidates": completed_candidates,
            "cohort_summaries": summaries,
        }
        atomic_write_json(results_path, sanitize_for_json(payload))

    final_data = json.loads(results_path.read_text(encoding="utf-8"))
    print_live_summary_report(final_data)
    print(f"\nAll results safely saved to {results_path}")
    return 0


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Locked local holdout runner for SU(2) benchmark at lambda = 1.2."
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Verify locked hashes and spanning tree integrity without running lambda = 1.2 simulations.",
    )
    parser.add_argument(
        "--results-path",
        type=Path,
        default=None,
        help="Optional destination path for holdout results JSON (defaults to muse_collection/lambda12_holdout_results.json).",
    )
    args = parser.parse_args()

    try:
        sys.exit(run_holdout(dry_run=args.dry_run, results_path=args.results_path, root=ROOT))
    except Exception as exc:
        print(f"\n[FATAL ERROR] Holdout runner failed closed: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
"""One-seed exploratory comparison frozen in LIVE_MUSE_PROTOCOL.md."""

import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path

from collect_muse_proposals import validate_tree
from evaluate_physical import evaluate


ROOT = Path(__file__).resolve().parent
RECEIPT = ROOT / "muse_collection" / "CALL_08_TRANSPORT_RECOVERY_receipt.json"
CONTROLS = ROOT / "muse_collection" / "frozen_random_controls_lambda17.json"
OUTPUT = ROOT / "muse_collection" / "live_muse_comparison_lambda10.json"


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    if OUTPUT.exists():
        raise RuntimeError("Comparison already exists; refusing to overwrite")
    receipt = json.loads(RECEIPT.read_text(encoding="utf-8"))
    if (receipt.get("validation", {}).get("verdict") != "PASSED" or
            receipt.get("finish_reason") != "stop"):
        raise RuntimeError("Muse output is not a completed valid tree")
    muse_edges = validate_tree({"edges": receipt["validation"]["edges"]})
    controls = json.loads(CONTROLS.read_text(encoding="utf-8"))
    control = controls["controls"][0]
    if control["control_id"] != "random_ust_lambda17_01":
        raise RuntimeError("Frozen random-control identity changed")
    random_edges = validate_tree({"edges": control["edges"]})
    rows = []
    for label, edges in (("muse_live_08", muse_edges), (control["control_id"], random_edges)):
        result = evaluate(edges, lam=1.0, max_total=4, seeds=[0], budget=100)
        result["candidate_id"] = label
        result["edges"] = edges
        result["regularized_utility"] = result["median_singlet_overlap_probability"] / (
            result["median_energy_error"] + 0.005)
        rows.append(result)
        print(label, "energy error", result["median_energy_error"],
              "overlap", result["median_singlet_overlap_probability"],
              "utility", result["regularized_utility"], flush=True)
    record = {
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "protocol": "LIVE_MUSE_PROTOCOL.md",
        "source_receipt_sha256": digest(RECEIPT),
        "source_controls_sha256": digest(CONTROLS),
        "lambda": 1.0, "max_total_occupation": 4, "seeds": [0],
        "budget_per_seed": 100, "utility_epsilon": 0.005,
        "exploratory_preview": True,
        "classical_noiseless_simulation": True,
        "rows": rows,
    }
    OUTPUT.write_text(json.dumps(record, indent=2), encoding="utf-8")


if __name__ == "__main__":
    main()
"""One in-window Muse request for the live lab; dry run unless --execute.

CALL_08 is a new exploratory demonstration request. It is not a continuation of
the failed CALL_07 adaptive study and does not touch the lambda=1.7 holdout.
"""

import argparse
import hashlib
import json

from collect_adaptive_loop import execute_call, get_api_key, OUTPUT_DIR


PROMPT = (
    "Design one ordered 11-CNOT spanning tree for a 12-qubit, two-layer RY+CNOT "
    "circuit. Qubits 0-5 encode matrix X1; 6-11 encode X2. Earlier alternating "
    "ladders had low SU(2) singlet overlap; block chains improved it. Explore a "
    "different tree with two cross-register bridges, while keeping its undirected "
    "graph connected and acyclic. Return only JSON with key edges: exactly 11 "
    "distinct directed [control,target] pairs using qubits 0-11. The simulator, "
    "not the graph, measures physical singlet overlap."
)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--execute", action="store_true")
    parser.add_argument("--execute-recovery", action="store_true")
    args = parser.parse_args()
    if args.execute and args.execute_recovery:
        parser.error("choose one execution mode")
    print("CALL_08 prompt SHA256:", hashlib.sha256(PROMPT.encode()).hexdigest())
    print("Model muse-spark-1.3; 1024 completion-token cap; zero retries; one request maximum.")
    if not args.execute and not args.execute_recovery:
        print("Dry run only. No Muse credits used.")
        return
    call_id = "CALL_08"
    if args.execute_recovery:
        prior = OUTPUT_DIR / "CALL_08_receipt.json"
        if not prior.exists():
            raise RuntimeError("Recovery requires the original transport-failure receipt")
        original = json.loads(prior.read_text(encoding="utf-8"))
        if (original.get("error") != "Connection error." or
                original.get("total_tokens") is not None or
                original.get("prompt_text") != PROMPT):
            raise RuntimeError("Prior outcome is not a verified matching transport failure")
        call_id = "CALL_08_TRANSPORT_RECOVERY"
    key = get_api_key()
    if not key:
        raise RuntimeError("MODEL_API_KEY unavailable")
    from openai import OpenAI
    client = OpenAI(base_url="https://api.meta.ai/v1", api_key=key, max_retries=0, timeout=30)
    receipt, state = execute_call(
        call_id=call_id, candidate_id="muse_live_08", prompt_text=PROMPT,
        client=client, output_dir=OUTPUT_DIR, temperature=0.2,
        max_completion_tokens=1024, reasoning_effort="minimal",
    )
    print("State:", state)
    print("Tokens:", receipt.get("total_tokens"))
    print("Finish:", receipt.get("finish_reason"))
    print("Validation:", receipt.get("validation", {}).get("verdict"))


if __name__ == "__main__":
    main()
"""Local, bounded experiment preview for the HorizonForge judge demo.

Only localhost is served. This module never loads credentials or calls Muse.
"""

import argparse
import json
import threading
import time
import uuid
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from collect_muse_proposals import validate_tree
from evaluate_physical import evaluate


ROOT = Path(__file__).resolve().parent
MAX_BODY = 8192
SETTINGS = {"lambda": 1.0, "max_total_occupation": 4, "seeds": [0], "evaluations_per_seed": 100}
EVALUATION_LOCK = threading.Lock()


class Handler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        # Avoid logging request contents or filesystem paths.
        pass

    def _headers(self, code, content_type="application/json; charset=utf-8", length=0):
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(length))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()

    def _json(self, code, payload):
        body = json.dumps(payload, allow_nan=False).encode("utf-8")
        self._headers(code, length=len(body))
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/api/status":
            self._json(200, {"ready": True, "muse_api_enabled": False,
                             "exploratory_preview": True,
                             "classical_noiseless_simulation": True, "settings": SETTINGS})
            return
        if self.path in ("/", "/proof_demo.html"):
            name = "index.html" if self.path == "/" else "proof_demo.html"
            body = (ROOT / name).read_bytes()
            self._headers(200, "text/html; charset=utf-8", len(body))
            self.wfile.write(body)
            return
        self._json(404, {"error": "not_found"})

    def do_POST(self):
        if self.path not in ("/api/validate", "/api/evaluate"):
            self._json(404, {"error": "not_found"})
            return
        if self.headers.get_content_type() != "application/json":
            self._json(415, {"error": "content_type_must_be_application_json"})
            return
        try:
            size = int(self.headers.get("Content-Length", ""))
        except ValueError:
            self._json(411, {"error": "content_length_required"})
            return
        if size < 1 or size > MAX_BODY:
            self._json(413, {"error": "body_size_out_of_range", "max_bytes": MAX_BODY})
            return
        try:
            payload = json.loads(self.rfile.read(size))
            edges = validate_tree(payload)
        except (ValueError, TypeError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            self._json(400, {"valid": False, "error": str(exc)})
            return
        if self.path == "/api/validate":
            self._json(200, {"valid": True, "edges": edges})
            return
        if not EVALUATION_LOCK.acquire(blocking=False):
            self._json(429, {"error": "busy"})
            return
        try:
            started = time.monotonic()
            result = evaluate(edges, lam=1.0, max_total=4, seeds=[0], budget=100)
            result.update({"valid": True, "edges": edges, "settings": SETTINGS,
                           "utility_epsilon": 0.005,
                           "utility": result["median_singlet_overlap_probability"] /
                           (result["median_energy_error"] + 0.005),
                           "elapsed_seconds": round(time.monotonic() - started, 3),
                           "exploratory_preview": True,
                           "classical_noiseless_simulation": True,
                           "timestamp_utc": datetime.now(timezone.utc).isoformat()})
            output_dir = ROOT / "live_trials"
            output_dir.mkdir(exist_ok=True)
            (output_dir / f"{uuid.uuid4()}.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
            self._json(200, result)
        except Exception:
            self._json(500, {"error": "preview_failed"})
        finally:
            EVALUATION_LOCK.release()


def create_server(port=0):
    return ThreadingHTTPServer(("127.0.0.1", port), Handler)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8765)
    args = parser.parse_args()
    with create_server(args.port) as server:
        print(f"HorizonForge local preview: http://127.0.0.1:{server.server_port}/", flush=True)
        server.serve_forever()
"""Offline tests for collect_adaptive_loop.py.

Verifies the adaptive collection safeguards without network requests or API keys:
1. Test 1: Dry-run / status inspection dispatches zero API calls.
2. Test 2: One-dispatch limit (first execute_next sends CALL_07 only; call count = 1).
3. Test 3: Refusal to dispatch CALL_08 before lambda=1.2 training feedback is saved.
4. Test 4: Dispatch of CALL_08 with correctly formatted prompt once training feedback exists.
5. Test 5: Restart idempotency (calling execute_next when both calls are complete sends 0 calls).
6. Test 6: Attempt marker double-spend prevention on simulated crash / interruption.
7. Test 7: Alternative branch: CALL_07 validation failure formats structural repair prompt for CALL_08.
8. Test 8: CALL_07 API error halts automatic loop and refuses CALL_08 dispatch.
"""

import json
import shutil
import tempfile
from pathlib import Path

import collect_adaptive_loop as cal


class FakeChoice:
    def __init__(self, content, finish_reason="stop"):
        self.message = type("Msg", (), {"content": content})()
        self.finish_reason = finish_reason


class FakeUsage:
    def __init__(self, prompt=250, completion=350):
        self.prompt_tokens = prompt
        self.completion_tokens = completion
        self.total_tokens = prompt + completion


class FakeChatCompletions:
    def __init__(self, response_generator=None):
        self.call_count = 0
        self.received_prompts = []
        self.response_generator = response_generator

    def create(self, **kwargs):
        self.call_count += 1
        prompt = kwargs["messages"][0]["content"]
        self.received_prompts.append(prompt)

        if self.response_generator:
            content = self.response_generator(self.call_count, prompt)
        else:
            # Default: valid 12-qubit spanning tree (11 edges)
            edges = [
                [0, 1], [1, 2], [2, 3], [3, 4], [4, 5],
                [6, 7], [7, 8], [8, 9], [9, 10], [10, 11],
                [0, 6]
            ]
            content = json.dumps({"edges": edges})

        return type("Resp", (), {
            "choices": [FakeChoice(content)],
            "usage": FakeUsage()
        })()


class FakeClient:
    def __init__(self, response_generator=None):
        self.chat = type("Chat", (), {"completions": FakeChatCompletions(response_generator)})()


def test_adaptive_collector_offline():
    test_dir = Path(tempfile.mkdtemp(prefix="test_adaptive_"))
    print(f"Running offline adaptive collector tests in isolated directory: {test_dir}")

    try:
        # TEST 1: Dry-run / status inspection does zero API calls
        fake_client = FakeClient()
        cal.inspect_status(output_dir=test_dir)
        assert fake_client.chat.completions.call_count == 0, "Dry run must dispatch zero API calls"
        print("[PASS] Test 1: Dry-run / status inspection dispatches zero API calls.")

        # TEST 2: One-dispatch limit (first execute_next sends CALL_07 only; call count = 1)
        rec7, act7 = cal.execute_next(fake_client, output_dir=test_dir)
        assert act7 == "DISPATCHED_CALL07", f"Expected DISPATCHED_CALL07, got {act7}"
        assert fake_client.chat.completions.call_count == 1, f"Expected exactly 1 call dispatched, got {fake_client.chat.completions.call_count}"
        assert rec7["call_id"] == "CALL_07"
        assert rec7["validation"]["verdict"] == "PASSED"
        print("[PASS] Test 2: One-dispatch limit successfully enforced (CALL_07 dispatched, count=1).")

        # TEST 3: Refusal to dispatch CALL_08 before training feedback is saved
        rec_halt, act_halt = cal.execute_next(fake_client, output_dir=test_dir)
        assert act_halt == "AWAITING_TRAINING_FEEDBACK", f"Expected AWAITING_TRAINING_FEEDBACK, got {act_halt}"
        assert fake_client.chat.completions.call_count == 1, "Call count must not increment when awaiting training feedback"
        print("[PASS] Test 3: Refusal to dispatch CALL_08 before training feedback is present.")

        # TEST 4: Dispatch of CALL_08 with correctly formatted prompt once training feedback exists
        feedback_data = {
            "call_id": "CALL_07",
            "candidate_id": "muse_adaptive_07",
            "lambda": 1.2,
            "max_total_occupation": 4,
            "source_receipt_sha256": cal.compute_sha256(test_dir / "CALL_07_receipt.json"),
            "median_energy_error": 0.000123,
            "median_singlet_overlap_probability": 0.2654,
            "regularized_utility": 51.7298,
            "trials": [
                {"seed": 0, "energy_error": 0.000150, "singlet_overlap_probability": 0.2500, "evaluations": 300},
                {"seed": 1, "energy_error": 0.000123, "singlet_overlap_probability": 0.2654, "evaluations": 300},
                {"seed": 2, "energy_error": 0.000110, "singlet_overlap_probability": 0.2800, "evaluations": 300},
            ]
        }
        tampered_feedback = dict(feedback_data, source_receipt_sha256="wrong-receipt-hash")
        cal.atomic_write_json(test_dir / "CALL_07_training_feedback.json", tampered_feedback)
        rec_bad, act_bad = cal.execute_next(fake_client, output_dir=test_dir)
        assert act_bad == "INVALID_TRAINING_FEEDBACK" and fake_client.chat.completions.call_count == 1
        print("[PASS] Mismatched training feedback cannot trigger CALL_08.")
        cal.atomic_write_json(test_dir / "CALL_07_training_feedback.json", feedback_data)

        rec8, act8 = cal.execute_next(fake_client, output_dir=test_dir)
        assert act8 == "DISPATCHED_CALL08", f"Expected DISPATCHED_CALL08, got {act8}"
        assert fake_client.chat.completions.call_count == 2, f"Expected 2 total calls dispatched, got {fake_client.chat.completions.call_count}"
        assert rec8["call_id"] == "CALL_08"

        # Verify frozen template formatting in CALL_08 prompt
        prompt8 = fake_client.chat.completions.received_prompts[1]
        assert "0.000123" in prompt8, "CALL_08 prompt must contain median energy error"
        assert "0.2654" in prompt8, "CALL_08 prompt must contain median singlet probability"
        assert "51.7298" in prompt8, "CALL_08 prompt must contain regularized utility"
        assert "Your previous valid 12-qubit tree was" in prompt8, "CALL_08 prompt must contain frozen preamble"
        print("[PASS] Test 4: CALL_08 dispatched with correct frozen template populated from training feedback.")

        # TEST 5: Restart idempotency (calling execute_next when both calls are complete sends 0 calls)
        rec_done, act_done = cal.execute_next(fake_client, output_dir=test_dir)
        assert act_done == "ALL_COMPLETED", f"Expected ALL_COMPLETED, got {act_done}"
        assert fake_client.chat.completions.call_count == 2, "Call count must remain 2 on restart"
        print("[PASS] Test 5: Restart idempotency verified (zero duplicate calls dispatched).")

    finally:
        shutil.rmtree(test_dir, ignore_errors=True)

    # TEST 6: Attempt marker double-spend prevention on simulated crash
    crash_dir = Path(tempfile.mkdtemp(prefix="test_adaptive_crash_"))
    try:
        client_crash = FakeClient()
        crashed = False
        try:
            cal.execute_call(
                call_id="CALL_07",
                candidate_id="muse_adaptive_07",
                prompt_text=cal.CALL_07_PROMPT,
                client=client_crash,
                output_dir=crash_dir,
                crash_before_receipt=True,
            )
        except RuntimeError as e:
            if "SIMULATED_CRASH_BEFORE_RECEIPT" in str(e):
                crashed = True
        assert crashed, "Expected simulated crash before receipt"
        assert (crash_dir / "CALL_07.attempt_marker").exists(), "Marker must exist after crash"
        assert not (crash_dir / "CALL_07_receipt.json").exists(), "Receipt must not exist after crash"

        # Restart runner on crash directory
        client_restart = FakeClient()
        rec_m, act_m = cal.execute_next(client_restart, output_dir=crash_dir)
        assert act_m == "MARKER_EXISTS_CALL07", f"Expected MARKER_EXISTS_CALL07, got {act_m}"
        assert client_restart.chat.completions.call_count == 0, "No duplicate calls allowed when attempt marker exists"
        print("[PASS] Test 6: Attempt marker successfully halts automatic retry on simulated crash.")
    finally:
        shutil.rmtree(crash_dir, ignore_errors=True)

    # TEST 7: Alternative branch: CALL_07 validation failure formats structural repair prompt for CALL_08
    val_fail_dir = Path(tempfile.mkdtemp(prefix="test_adaptive_val_fail_"))
    try:
        def invalid_tree_gen(call_count, prompt):
            if call_count == 1:
                # Return tree with cycle: [0, 1], [1, 2], [2, 0]
                return json.dumps({"edges": [[0, 1], [1, 2], [2, 0], [3, 4], [4, 5], [6, 7], [7, 8], [8, 9], [9, 10], [10, 11], [0, 6]]})
            else:
                # Valid tree for CALL_08
                return json.dumps({"edges": [[0, 1], [1, 2], [2, 3], [3, 4], [4, 5], [6, 7], [7, 8], [8, 9], [9, 10], [10, 11], [0, 6]]})

        client_repair = FakeClient(response_generator=invalid_tree_gen)
        # CALL_07 dispatch (will fail validation)
        rec_f7, act_f7 = cal.execute_next(client_repair, output_dir=val_fail_dir)
        assert act_f7 == "DISPATCHED_CALL07"
        assert rec_f7["validation"]["verdict"] == "FAILED"
        assert "cycle" in rec_f7["validation"]["error"].lower()

        # CALL_08 dispatch should immediately proceed without waiting for training feedback
        rec_f8, act_f8 = cal.execute_next(client_repair, output_dir=val_fail_dir)
        assert act_f8 == "DISPATCHED_CALL08"
        prompt8_repair = client_repair.chat.completions.received_prompts[1]
        assert "failed strict tree validation:" in prompt8_repair
        assert "Correct the structural error and return one valid 11-edge spanning tree" in prompt8_repair
        print("[PASS] Test 7: CALL_07 validation failure correctly triggers structural correction template for CALL_08.")
    finally:
        shutil.rmtree(val_fail_dir, ignore_errors=True)

    # TEST 8: CALL_07 API error halts automatic loop and refuses CALL_08 dispatch
    err_dir = Path(tempfile.mkdtemp(prefix="test_adaptive_err_"))
    try:
        receipt_err = {
            "call_id": "CALL_07",
            "candidate_id": "muse_adaptive_07",
            "validation": {"verdict": "CALL_ERROR"},
            "error": "Connection reset by peer"
        }
        cal.atomic_write_json(err_dir / "CALL_07_receipt.json", receipt_err)
        client_err = FakeClient()
        rec_e, act_e = cal.execute_next(client_err, output_dir=err_dir)
        assert act_e == "STOPPED_CALL07_ERROR", f"Expected STOPPED_CALL07_ERROR, got {act_e}"
        assert client_err.chat.completions.call_count == 0, "Must not dispatch CALL_08 after CALL_07 error"
        print("[PASS] Test 8: CALL_07 API error successfully halts automatic loop and refuses CALL_08 dispatch.")
    finally:
        shutil.rmtree(err_dir, ignore_errors=True)

    # A token-limited empty response is not a graph validation error that
    # should trigger another paid request automatically.
    length_dir = Path(tempfile.mkdtemp(prefix="test_adaptive_length_"))
    try:
        cal.atomic_write_json(length_dir / "CALL_07_receipt.json", {
            "call_id": "CALL_07", "finish_reason": "length", "raw_response": None,
            "validation": {"verdict": "FAILED", "error": "no JSON content"},
        })
        length_client = FakeClient()
        _, length_action = cal.execute_next(length_client, output_dir=length_dir)
        assert length_action == "STOPPED_CALL07_INCOMPLETE"
        assert length_client.chat.completions.call_count == 0
        print("[PASS] Empty length-limited output preserves CALL_08 budget.")
    finally:
        shutil.rmtree(length_dir, ignore_errors=True)

    print("\nALL ADAPTIVE COLLECTOR OFFLINE TESTS PASSED CLEANLY.")


if __name__ == "__main__":
    test_adaptive_collector_offline()
"""Offline test verifying the collection safeguards without network requests or API keys:

1. Test 1: First run with FakeClient sends at most 3 distinct calls.
2. Test 2: Second run on existing receipts calls production execute_call and sends 0 duplicate calls.
3. Test 3: Simulated crash after fake response and before receipt write leaves attempt marker
   without receipt; restart calls production execute_call and dispatches 0 additional fake requests.
4. Test 4: Two-runner concurrency test proving only one fake request is dispatched for a call ID.
5. Test 5: Manifest exclusion test proving missing receipts, missing proposals, mismatched receipts,
   and invalid proposal trees are strictly excluded from model_cohort_manifest.json.
6. Test 6: Full manifest generation from completed test run directory.
"""

import concurrent.futures
import json
import shutil
import tempfile
import threading
from pathlib import Path

import collect_muse_proposals as cmp


class FakeChoice:
    def __init__(self, content, finish_reason="stop"):
        self.message = type("Msg", (), {"content": content})()
        self.finish_reason = finish_reason


class FakeUsage:
    def __init__(self, prompt=250, completion=350):
        self.prompt_tokens = prompt
        self.completion_tokens = completion
        self.total_tokens = prompt + completion


class FakeChatCompletions:
    def __init__(self):
        self.call_count = 0
        self.received_prompts = []

    def create(self, **kwargs):
        self.call_count += 1
        prompt = kwargs["messages"][0]["content"]
        self.received_prompts.append(prompt)
        # Return valid spanning tree on 12 qubits (11 edges)
        edges = [
            [0, 1], [1, 2], [2, 3], [3, 4], [4, 5],
            [6, 7], [7, 8], [8, 9], [9, 10], [10, 11],
            [0, 6]
        ]
        return type("Resp", (), {
            "choices": [FakeChoice(json.dumps({"edges": edges}))],
            "usage": FakeUsage()
        })()


class FakeClient:
    def __init__(self):
        self.chat = type("Chat", (), {"completions": FakeChatCompletions()})()


def test_offline_safeguards():
    test_dir = Path(tempfile.mkdtemp(prefix="test_collector_"))
    print(f"Running offline tests in isolated directory: {test_dir}")
    try:
        # TEST 1: First run with FakeClient sends exactly 3 calls
        fake_client = FakeClient()
        summary = {"calls": []}
        for spec in cmp.PROMPT_SPECS:
            rec, act = cmp.execute_call(spec, fake_client, output_dir=test_dir)
            assert act == "EXECUTED", f"Expected EXECUTED, got {act}"
            summary["calls"].append(rec)
        assert fake_client.chat.completions.call_count == 3, f"Expected 3 calls, got {fake_client.chat.completions.call_count}"
        print("[PASS] Test 1: First run dispatches exactly 3 calls.")

        # TEST 2: Second run on existing receipts calls production execute_call and sends 0 duplicate calls
        fake_client_2 = FakeClient()
        for spec in cmp.PROMPT_SPECS:
            rec, act = cmp.execute_call(spec, fake_client_2, output_dir=test_dir)
            assert act == "ALREADY_COMPLETED", f"Expected ALREADY_COMPLETED, got {act}"
        assert fake_client_2.chat.completions.call_count == 0, f"Expected 0 calls on restart, got {fake_client_2.chat.completions.call_count}"
        print("[PASS] Test 2: Second run on existing receipts calls production execute_call and sends 0 duplicate calls.")

        # TEST 3: Simulated crash after fake response and before receipt write leaves attempt marker;
        # restart calls production execute_call and sends 0 duplicate calls.
        crash_dir = Path(tempfile.mkdtemp(prefix="test_crash_"))
        try:
            fake_client_3 = FakeClient()
            spec0 = cmp.PROMPT_SPECS[0]
            marker_file = crash_dir / f"{spec0['call_id']}.attempt_marker"
            receipt_file = crash_dir / f"{spec0['call_id']}_receipt.json"

            # Execute with crash_before_receipt=True; must raise RuntimeError without writing receipt
            crashed = False
            try:
                cmp.execute_call(spec0, fake_client_3, output_dir=crash_dir, crash_before_receipt=True)
            except RuntimeError as exc:
                if "SIMULATED_CRASH_BEFORE_RECEIPT" in str(exc):
                    crashed = True
            assert crashed, "Expected SIMULATED_CRASH_BEFORE_RECEIPT to propagate"
            assert fake_client_3.chat.completions.call_count == 1, "Fake response must have been generated"
            assert marker_file.exists(), "Attempt marker must exist after dispatch"
            assert not receipt_file.exists(), "Receipt file must NOT exist after crash before receipt"

            # Restart collector on same directory with fresh client calling production execute_call
            fake_client_4 = FakeClient()
            rec2, act2 = cmp.execute_call(spec0, fake_client_4, output_dir=crash_dir)
            assert act2 == "MARKER_EXISTS", f"Expected MARKER_EXISTS on restart, got {act2}"
            assert rec2.get("status") == "UNKNOWN_ATTEMPT_STOPPED", f"Expected UNKNOWN_ATTEMPT_STOPPED, got {rec2.get('status')}"
            assert fake_client_4.chat.completions.call_count == 0, "Zero additional fake requests must be dispatched on restart!"
            print("[PASS] Test 3: Crash after fake response leaves attempt marker without receipt; restart calls production execute_call and sends 0 duplicate calls.")
        finally:
            shutil.rmtree(crash_dir, ignore_errors=True)

        # TEST 4: Two-runner concurrency test proving only one fake request is dispatched for a call ID
        conc_dir = Path(tempfile.mkdtemp(prefix="test_concurrency_"))
        try:
            fake_client_a = FakeClient()
            fake_client_b = FakeClient()
            spec = cmp.PROMPT_SPECS[0]
            barrier = threading.Barrier(2)
            results = []

            def concurrent_runner(client):
                barrier.wait()
                res = cmp.execute_call(spec, client, output_dir=conc_dir)
                results.append(res)
                return res

            with concurrent.futures.ThreadPoolExecutor(max_workers=2) as executor:
                f1 = executor.submit(concurrent_runner, fake_client_a)
                f2 = executor.submit(concurrent_runner, fake_client_b)
                concurrent.futures.wait([f1, f2])
                f1.result()
                f2.result()

            total_calls = fake_client_a.chat.completions.call_count + fake_client_b.chat.completions.call_count
            assert total_calls == 1, f"Expected exactly 1 fake request across two runners, got {total_calls}"
            actions = [r[1] for r in results]
            assert "EXECUTED" in actions, f"Expected one runner to execute, got actions: {actions}"
            assert "MARKER_EXISTS" in actions, f"Expected other runner to see marker, got actions: {actions}"
            print("[PASS] Test 4: Two-runner concurrency test proves exactly 1 fake request is dispatched for a call ID.")
        finally:
            shutil.rmtree(conc_dir, ignore_errors=True)

        # TEST 5: Manifest candidate exclusion tests (missing, mismatched receipts, invalid tree)
        manifest_test_dir = Path(tempfile.mkdtemp(prefix="test_manifest_"))
        try:
            valid_tree = [
                [0, 1], [1, 2], [2, 3], [3, 4], [4, 5],
                [6, 7], [7, 8], [8, 9], [9, 10], [10, 11],
                [0, 6]
            ]
            cycle_tree = [
                [0, 1], [1, 2], [2, 0], [3, 4], [4, 5],
                [6, 7], [7, 8], [8, 9], [9, 10], [10, 11],
                [0, 6]
            ]
            mismatched_tree = [
                [0, 1], [1, 2], [2, 3], [3, 4], [4, 5],
                [6, 7], [7, 8], [8, 9], [9, 10], [10, 11],
                [1, 7]
            ]

            cand_id = cmp.PROMPT_SPECS[0]["candidate_id"]
            call_id = cmp.PROMPT_SPECS[0]["call_id"]
            prop_file = manifest_test_dir / f"{cand_id}.json"
            rec_file = manifest_test_dir / f"{call_id}_receipt.json"

            # 5a. Missing receipt excludes candidate
            prop_file.write_text(json.dumps({"edges": valid_tree}), encoding="utf-8")
            if rec_file.exists():
                rec_file.unlink()
            m = cmp.write_manifest(output_dir=manifest_test_dir)
            assert cand_id not in [c["candidate_id"] for c in m["candidates"]], "Candidate with missing receipt must be excluded"

            # 5b. Missing proposal excludes candidate
            rec_file.write_text(json.dumps({
                "call_id": call_id,
                "validation": {"verdict": "PASSED", "edges": valid_tree}
            }), encoding="utf-8")
            if prop_file.exists():
                prop_file.unlink()
            m = cmp.write_manifest(output_dir=manifest_test_dir)
            assert cand_id not in [c["candidate_id"] for c in m["candidates"]], "Candidate with missing proposal must be excluded"

            # 5c. Mismatched edges between proposal and receipt excludes candidate
            prop_file.write_text(json.dumps({"edges": valid_tree}), encoding="utf-8")
            rec_file.write_text(json.dumps({
                "call_id": call_id,
                "validation": {"verdict": "PASSED", "edges": mismatched_tree}
            }), encoding="utf-8")
            m = cmp.write_manifest(output_dir=manifest_test_dir)
            assert cand_id not in [c["candidate_id"] for c in m["candidates"]], "Candidate with mismatched receipt edges must be excluded"

            # 5d. Non-tree / cycle in proposal excludes candidate
            prop_file.write_text(json.dumps({"edges": cycle_tree}), encoding="utf-8")
            rec_file.write_text(json.dumps({
                "call_id": call_id,
                "validation": {"verdict": "PASSED", "edges": cycle_tree}
            }), encoding="utf-8")
            m = cmp.write_manifest(output_dir=manifest_test_dir)
            assert cand_id not in [c["candidate_id"] for c in m["candidates"]], "Candidate with cycle must be excluded"

            # 5e. Valid proposal matching receipt is included
            prop_file.write_text(json.dumps({"edges": valid_tree}), encoding="utf-8")
            rec_file.write_text(json.dumps({
                "call_id": call_id,
                "validation": {"verdict": "PASSED", "edges": valid_tree}
            }), encoding="utf-8")
            m = cmp.write_manifest(output_dir=manifest_test_dir)
            assert cand_id in [c["candidate_id"] for c in m["candidates"]], "Valid candidate matching receipt must be included"

            # 5f. Cohort policy verification
            assert m["target_cohort_size"] == 5
            assert "No hand-coded designs substituted" in m["cohort_policy"]
            print("[PASS] Test 5: Missing and mismatched receipts, and non-tree proposals, strictly exclude candidates from manifest.")
        finally:
            shutil.rmtree(manifest_test_dir, ignore_errors=True)

        # TEST 6: Test full manifest generation from Test 1 directory
        manifest = cmp.write_manifest(output_dir=test_dir)
        assert manifest["target_cohort_size"] == 5
        assert manifest["valid_proposals_count"] >= 3
        print(f"[PASS] Test 6: Full manifest generated with {manifest['valid_proposals_count']} valid candidates.")

    finally:
        shutil.rmtree(test_dir, ignore_errors=True)
    print("\nALL OFFLINE TESTS PASSED CLEANLY.")


if __name__ == "__main__":
    test_offline_safeguards()
"""Offline check that a mismatched checkpoint cannot trigger lambda=1.2 work."""

import json
from pathlib import Path
from unittest.mock import patch

import run_lambda12_holdout as holdout


def main():
    scratch = Path(__file__).resolve().parent / "agent_channel" / "test_tmp"
    scratch.mkdir(exist_ok=True)
    checkpoint = scratch / "resume_guard_check.json"
    try:
        for field, value in (("target_lambda", 1.0), ("budget_per_seed", 299)):
            payload = {
                "target_lambda": 1.2,
                "max_total_occupation": 4,
                "budget_per_seed": 300,
                "seeds": [0, 1, 2],
                "locked_hashes": {k: v["expected_sha256"] for k, v in holdout.LOCKED_HASHES.items()},
                "evaluator_version": f"evaluate_physical.py ({holdout.LOCKED_HASHES['evaluator']['expected_sha256']})",
                "total_candidates_count": 11,
                "completed_candidates_count": 0,
                "status": "IN_PROGRESS",
                "candidates": [],
            }
            payload[field] = value
            checkpoint.write_text(json.dumps(payload), encoding="utf-8")
            with patch.object(holdout.evaluate_physical, "evaluate", side_effect=AssertionError("Evaluator must not run")):
                try:
                    holdout.run_holdout(results_path=checkpoint)
                except RuntimeError as exc:
                    assert f"different {field}" in str(exc), str(exc)
                else:
                    raise AssertionError(f"Mismatched {field} was not rejected")
            assert json.loads(checkpoint.read_text(encoding="utf-8")) == payload
            print(f"[PASS] Mismatched {field} stops before evaluation and preserves checkpoint")
    finally:
        checkpoint.unlink(missing_ok=True)


if __name__ == "__main__":
    main()
"""Local HTTP contract checks. Run with: python test_serve_demo.py"""

import http.client
import json
import threading

from serve_demo import create_server


EDGES = [[i, i + 1] for i in range(11)]


def request(port, method, path, body=None, headers=None):
    connection = http.client.HTTPConnection("127.0.0.1", port, timeout=120)
    connection.request(method, path, body=body, headers=headers or {})
    response = connection.getresponse()
    raw = response.read()
    connection.close()
    return response.status, response.getheaders(), json.loads(raw) if path.startswith("/api/") else raw


def main():
    server = create_server(0)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    port = server.server_port
    try:
        code, headers, body = request(port, "GET", "/api/status")
        assert code == 200 and body["muse_api_enabled"] is False
        assert dict(headers)["Cache-Control"] == "no-store"
        assert request(port, "GET", "/.env")[0] == 404
        assert request(port, "GET", "/")[0] == 200
        good = json.dumps({"edges": EDGES})
        code, _, body = request(port, "POST", "/api/validate", good,
                                {"Content-Type": "application/json"})
        assert code == 200 and body["valid"] and body["edges"] == EDGES
        code, _, body = request(port, "POST", "/api/validate", json.dumps({"edges": [[0, 1]]}),
                                {"Content-Type": "application/json"})
        assert code == 400 and body["valid"] is False
        assert request(port, "POST", "/api/validate", "x" * 8193,
                       {"Content-Type": "application/json"})[0] == 413
        assert request(port, "POST", "/api/evaluate", good,
                       {"Content-Type": "application/json"})[0] == 200
        print("Local status, validation, security paths, and physics preview passed.")
    finally:
        server.shutdown()
        server.server_close()


if __name__ == "__main__":
    main()
