"""Initial, read-only LIGO data feasibility check; not a detection pipeline."""

import gzip
from pathlib import Path

import numpy as np
from scipy import signal


ROOT = Path(__file__).resolve().parent
FS = 4096
START_GPS = 1126259446
EVENT_GPS = 1126259462.4


def load(name):
    with gzip.open(ROOT / "data" / "raw" / name, "rt") as source:
        values = np.loadtxt(source)
    if len(values) != FS * 32:
        raise ValueError("unexpected file length")
    return values * 1e21


def whiten(values):
    frequencies, psd = signal.welch(values, FS, nperseg=FS * 4)
    fft = np.fft.rfft(values)
    target_frequencies = np.fft.rfftfreq(len(values), 1 / FS)
    noise = np.interp(target_frequencies, frequencies, psd)
    white = np.fft.irfft(fft / np.sqrt(np.maximum(noise, 1e-16)), len(values))
    sos = signal.butter(4, [35, 350], btype="bandpass", fs=FS, output="sos")
    return signal.sosfiltfilt(sos, white)


def normalized_corr(a, b):
    a = a - np.mean(a)
    b = b - np.mean(b)
    return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b)))


def main():
    h = whiten(load("H-H1_LOSC_4_V2-1126259446-32.txt.gz"))
    l = whiten(load("L-L1_LOSC_4_V2-1126259446-32.txt.gz"))
    delay_samples = round(0.0069 * FS)
    # L1 saw the published event first; H1 follows about 6.9 ms later.
    l_aligned = np.roll(l, delay_samples)
    window = int(0.2 * FS)
    results = []
    for center in np.arange(1.0, 31.0, 0.05):
        idx = round(center * FS)
        score = abs(normalized_corr(h[idx - window // 2:idx + window // 2],
                                    l_aligned[idx - window // 2:idx + window // 2]))
        results.append((score, center))
    results.sort(reverse=True)
    print("Published event center relative to file:", EVENT_GPS - START_GPS)
    print("Strongest 0.2 s aligned cross-detector correlations:")
    for score, center in results[:10]:
        print(f"  center={center:.2f}s  |correlation|={score:.3f}")
    for center in (5.0, 10.0, 16.4, 20.0, 25.0):
        idx = round(center * FS)
        print(f"center={center:.1f}s", "correlation=", round(abs(normalized_corr(
            h[idx - window // 2:idx + window // 2],
            l_aligned[idx - window // 2:idx + window // 2])), 3))


if __name__ == "__main__":
    main()
