"""Scan GWOSC H1/L1 strain without event time or prescribed inter-site lag.

This is a candidate-localization statistic, not an astrophysical false-alarm
rate or a detector validated by a blind benchmark.
"""

import numpy as np
from scipy import signal

from feasibility import FS, load, whiten


WINDOW_SECONDS = 0.2
STEP_SECONDS = 0.05
MAX_LAG_SECONDS = 0.01


def scan(h, l, start_seconds=1.0, end_seconds=31.0):
    window = round(WINDOW_SECONDS * FS)
    half = window // 2
    step = round(STEP_SECONDS * FS)
    max_lag = round(MAX_LAG_SECONDS * FS)
    candidates = []
    first = max(FS, round(start_seconds * FS))
    last = min(len(h) - FS, round(end_seconds * FS))
    for midpoint in range(first, last, step):
        a = h[midpoint - half:midpoint + half]
        a = a - a.mean()
        norm_a = np.linalg.norm(a)
        best = (0.0, 0)
        for lag in range(-max_lag, max_lag + 1):
            b = l[midpoint - half - lag:midpoint + half - lag]
            b = b - b.mean()
            score = abs(float(np.dot(a, b) / (norm_a * np.linalg.norm(b))))
            if score > best[0]:
                best = (score, lag)
        candidates.append({"score": best[0], "center_seconds": midpoint / FS,
                           "lag_seconds": best[1] / FS})
    candidates.sort(key=lambda row: row["score"], reverse=True)
    distinct = []
    for row in candidates:
        if all(abs(row["center_seconds"] - kept["center_seconds"]) > WINDOW_SECONDS
               for kept in distinct):
            distinct.append(row)
        if len(distinct) == 10:
            break
    return distinct


if __name__ == "__main__":
    h = whiten(load("H-H1_LOSC_4_V2-1126259446-32.txt.gz"))
    l = whiten(load("L-L1_LOSC_4_V2-1126259446-32.txt.gz"))
    for rank, row in enumerate(scan(h, l), 1):
        print(rank, {key: round(value, 4) for key, value in row.items()})
