"""Run frozen independent evaluation on GWOSC holdouts and independent negatives.

Do not alter preprocessing, window duration, or threshold after reading results.
"""

import gzip
import json
from pathlib import Path

import numpy as np
from scipy import signal

from feasibility import FS, whiten
from label_free_scan import scan, WINDOW_SECONDS, STEP_SECONDS, MAX_LAG_SECONDS


ROOT = Path(__file__).resolve().parent
RAW_DIR = ROOT / "data" / "raw"


def load_strain(filename):
    filepath = RAW_DIR / filename
    with gzip.open(filepath, "rt") as source:
        values = np.loadtxt(source)
    if len(values) != FS * 32:
        raise ValueError(f"Unexpected file length {len(values)} in {filename}")
    return values * 1e21


def scan_zero_lag(h, l, start_seconds=1.0, end_seconds=31.0):
    """Baseline scan with zero inter-detector lag (fixed lag = 0)."""
    window = round(WINDOW_SECONDS * FS)
    half = window // 2
    step = round(STEP_SECONDS * FS)
    candidates = []
    first = max(FS, round(start_seconds * FS))
    last = min(len(h) - FS, round(end_seconds * FS))
    for midpoint in range(first, last, step):
        a = h[midpoint - half:midpoint + half]
        a = a - a.mean()
        b = l[midpoint - half:midpoint + half]
        b = b - b.mean()
        norm_a = np.linalg.norm(a)
        norm_b = np.linalg.norm(b)
        score = abs(float(np.dot(a, b) / (norm_a * norm_b))) if norm_a > 0 and norm_b > 0 else 0.0
        candidates.append({"score": score, "center_seconds": midpoint / FS, "lag_seconds": 0.0})
    candidates.sort(key=lambda row: row["score"], reverse=True)
    distinct = []
    for row in candidates:
        if all(abs(row["center_seconds"] - kept["center_seconds"]) > WINDOW_SECONDS for kept in distinct):
            distinct.append(row)
        if len(distinct) == 10:
            break
    return distinct


def single_detector_max_snr(h):
    """Baseline: peak standardized amplitude in single detector."""
    h_std = np.std(h)
    return float(np.max(np.abs(h)) / h_std) if h_std > 0 else 0.0


