def run_benchmark():
    THRESHOLD = 0.50
    LOCALIZATION_TOLERANCE = 0.50

    results = []
    print("=" * 80)
    print("GWOSC INDEPENDENT EVALUATION RUNNER")
    print(f"Fixed Pre-declared Threshold: S >= {THRESHOLD:.2f}")
    print(f"Event Localization Tolerance: +/- {LOCALIZATION_TOLERANCE:.2f} s")
    print("=" * 80)

    for case in TEST_CASES:
        case_id = case["id"]
        category = case["category"]
        print(f"\nEvaluating [{category}] {case_id}...")

        h_raw = load_strain(case["h_file"])
        l_raw = load_strain(case["l_file"])

        h_white = whiten(h_raw)
        l_white = whiten(l_raw)

        # 1. Primary Scanner (Lag-optimized cross-correlation)
        candidates = scan(h_white, l_white)
        top = candidates[0] if candidates else {"score": 0.0, "center_seconds": 0.0, "lag_seconds": 0.0}

        # 2. Baseline 1: Zero-lag cross-correlation
        base_zero = scan_zero_lag(h_white, l_white)[0]

        # 3. Baseline 2: Single-detector peak amplitude / SNR
        h_snr = single_detector_max_snr(h_white)
        l_snr = single_detector_max_snr(l_white)

        # Check localization and pass/fail criteria
        target = case["target_seconds"]
        is_localized = False
        time_error = None
        if target is not None:
            time_error = abs(top["center_seconds"] - target)
            is_localized = time_error <= LOCALIZATION_TOLERANCE

        passes_criterion = False
        if category in ("development", "holdout_positive"):
            passes_criterion = (top["score"] >= THRESHOLD) and is_localized
        else:
            passes_criterion = top["score"] < THRESHOLD

        row = {
            "id": case_id,
            "category": category,
            "top_score": round(top["score"], 4),
            "top_center_s": round(top["center_seconds"], 3),
            "top_lag_ms": round(top["lag_seconds"] * 1000, 2),
            "target_center_s": target,
            "time_error_s": round(time_error, 3) if time_error is not None else None,
            "localized": is_localized,
            "passes_criterion": passes_criterion,
            "baseline_zero_lag_score": round(base_zero["score"], 4),
            "baseline_h1_peak_snr": round(h_snr, 2),
            "baseline_l1_peak_snr": round(l_snr, 2),
            "top_3_candidates": [
                {
                    "score": round(c["score"], 4),
                    "center_s": round(c["center_seconds"], 3),
                    "lag_ms": round(c["lag_seconds"] * 1000, 2),
                }
                for c in candidates[:3]
            ],
        }
        results.append(row)
        print(f"  Top statistic S: {row['top_score']:.4f} at {row['top_center_s']:.3f} s (lag: {row['top_lag_ms']:+.1f} ms)")
        if target is not None:
            print(f"  Target: {target:.2f} s | Time error: {row['time_error_s']:.3f} s | Localized: {is_localized}")
        print(f"  Passes Pre-declared Criterion: {passes_criterion}")
        print(f"  Baseline zero-lag: {row['baseline_zero_lag_score']:.4f} | H1 peak SNR: {row['baseline_h1_peak_snr']:.2f}")

    # Summary analysis
    holdout_pos = [r for r in results if r["category"] == "holdout_positive"]
    indep_neg = [r for r in results if r["category"] in ("independent_negative", "time_slide_control")]

    min_pos_score = min(r["top_score"] for r in holdout_pos)
    max_neg_score = max(r["top_score"] for r in indep_neg)
    all_pos_passed = all(r["passes_criterion"] for r in holdout_pos)
    all_neg_passed = all(r["passes_criterion"] for r in indep_neg)

    print("\n" + "=" * 80)
    print("EVALUATION SUMMARY")
    print("=" * 80)
    print(f"Holdout Positives: {len(holdout_pos)} cases")
    print(f"  Min positive score: {min_pos_score:.4f}")
    print(f"  All positive passed: {all_pos_passed}")
    print(f"Independent Negatives / Controls: {len(indep_neg)} cases")
    print(f"  Max negative score: {max_neg_score:.4f}")
    print(f"  All negative passed: {all_neg_passed}")
    print(f"Separation Margin (min_pos - max_neg): {min_pos_score - max_neg_score:+.4f}")

    if all_pos_passed and all_neg_passed and (min_pos_score > max_neg_score):
        verdict = "GO"
    elif not all_pos_passed and not all_neg_passed:
        verdict = "NO-GO"
    elif min_pos_score <= max_neg_score:
        verdict = "NO-GO"
    else:
        verdict = "INCONCLUSIVE"

    print(f"\nFINAL VERDICT: {verdict}")
    print("=" * 80)

    output_path = ROOT / "eval_results.json"
    with open(output_path, "w") as f:
        json.dump(
            {
                "verdict": verdict,
                "threshold": THRESHOLD,
                "localization_tolerance_s": LOCALIZATION_TOLERANCE,
                "min_pos_score": min_pos_score,
                "max_neg_score": max_neg_score,
                "margin": round(min_pos_score - max_neg_score, 4),
                "all_pos_passed": all_pos_passed,
                "all_neg_passed": all_neg_passed,
                "results": results,
            },
            f,
            indent=2,
        )
    print(f"\nResults saved to {output_path}")
    return results, verdict


if __name__ == "__main__":
    run_benchmark()
