"""Automated property test and fuzzing suite for matrix_vqe_preflight.py.

Tests standard physical properties (Hermiticity, Variational Principle, Parity Invariance, Spectral Continuity).
Standard property-based testing checks these invariants without domain-specific non-Abelian gauge algebra.
"""

import time
import numpy as np
from scipy import sparse
from scipy.sparse.linalg import eigsh

import matrix_vqe_preflight as target


def test_hermiticity(cutoff=2, lam=1.0) -> dict:
    """Property 1: Hamiltonian must be strictly Hermitian (H == H^dag)."""
    h = target.hamiltonian(lam=lam, cutoff=cutoff)
    hermitian_defect = float(sparse.linalg.norm(h - h.getH()))
    return {
        "property": "Hermiticity",
        "defect": hermitian_defect,
        "passed": hermitian_defect < 1e-12
    }


def test_variational_energy_bound(samples=50, cutoff=2, lam=1.0) -> dict:
    """Property 2: Variational energy <psi|H|psi> >= E_exact for arbitrary circuit states."""
    h = target.hamiltonian(lam=lam, cutoff=cutoff)
    exact_energy = float(eigsh(h, k=1, which="SA", tol=1e-10)[0][0])
    rng = np.random.default_rng(42)

    violations = 0
    min_observed_diff = float("inf")

    qubits = int(np.log2(h.shape[0]))
    depth = 2
    for _ in range(samples):
        params = rng.uniform(-np.pi, np.pi, size=qubits * depth)
        state = target.statevector(params, depth, "ring", qubits)
        energy = float(state @ (h @ state))
        diff = energy - exact_energy
        if diff < min_observed_diff:
            min_observed_diff = diff
        if diff < -1e-8:
            violations += 1

    return {
        "property": "VariationalBound",
        "exact_energy": exact_energy,
        "samples_tested": samples,
        "violations": violations,
        "min_delta_E": min_observed_diff,
        "passed": violations == 0
    }


def test_parity_symmetry(cutoff=2, lam=1.0) -> dict:
    """Property 3: Discrete spatial parity symmetry [H, Pi] == 0 under total inversion X -> -X."""
    # Parity operator Pi = exp(i * pi * sum_i N_i)
    # Under per-mode cutoff, parity is diagonal with (-1)^n
    lowering = sparse.diags(np.sqrt(np.arange(1, cutoff)), 1, shape=(cutoff, cutoff), format="csr")
    parity_1d = sparse.diags([(-1.0)**n for n in range(cutoff)], format="csr")

    parity_total = sparse.csr_matrix([[1.0]])
    for _ in range(6):
        parity_total = sparse.kron(parity_total, parity_1d, format="csr")

    h = target.hamiltonian(lam=lam, cutoff=cutoff)
    comm = h @ parity_total - parity_total @ h
    parity_defect = float(sparse.linalg.norm(comm))

    return {
        "property": "ParitySymmetry",
        "defect": parity_defect,
        "passed": parity_defect < 1e-10
    }


def test_spectral_continuity(cutoff=2) -> dict:
    """Property 4: Ground state energy is monotonically and smoothly increasing with lambda."""
    lambdas = np.linspace(0.1, 2.0, 10)
    energies = []
    for l in lambdas:
        h = target.hamiltonian(lam=l, cutoff=cutoff)
        e = float(eigsh(h, k=1, which="SA", tol=1e-10)[0][0])
        energies.append(e)

    monotonic = all(energies[i] <= energies[i+1] for i in range(len(energies)-1))
    return {
        "property": "SpectralContinuity",
        "lambdas": lambdas.tolist(),
        "energies": energies,
        "passed": monotonic
    }


def run_all_property_fuzzing():
    start = time.time()
    results = [
        test_hermiticity(),
        test_variational_energy_bound(),
        test_parity_symmetry(),
        test_spectral_continuity(),
    ]
    elapsed = time.time() - start
    all_passed = all(r["passed"] for r in results)
    return {
        "suite": "Automated_Property_Fuzzing",
        "elapsed_seconds": elapsed,
        "all_passed": all_passed,
        "reveals_gauge_flaw": False,  # None of these test the non-Abelian SU(2) gauge generator algebra
        "results": results
    }


if __name__ == "__main__":
    import json
    res = run_all_property_fuzzing()
    print(json.dumps(res, indent=2))
