"""Leak check and manifest generator for Case 01.

Ensures that the model-visible bundle does NOT leak:
1. Oracle answers or benchmark numbers (e.g. 1051.6, 13.064).
2. Prior audit document names or benchmark files (e.g. CLAIM_AUDIT, verify_gauge_invariant).
3. Explicit mentions of the known flaw solution.
Also computes SHA256 integrity hashes for all files in both bundles.
"""

import hashlib
import json
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parent
VISIBLE_DIR = ROOT / "visible"
ORACLE_DIR = ROOT / "oracle"
MANIFEST_FILE = ROOT / "manifest_sha256.json"

FORBIDDEN_LEAK_PATTERNS = [
    "claim_audit",
    "claim_audit_results",
    "gauge_invariant_benchmark",
    "verify_gauge_invariant",
    "review_handoff",
    "broken by finite fock",
    "not an overall physics win",
    "1051.6",
    "13.0641",
    "singlet projection probability",
    "total-occupation benchmark",
    "oracle_truth",
    "oracle_verifier",
]


def sha256_of_file(path: Path) -> str:
    h = hashlib.sha256()
    h.update(path.read_bytes())
    return h.hexdigest()


def check_no_leakage() -> dict:
    leak_report = {"clean": True, "scanned_files": [], "findings": []}
    for file_path in VISIBLE_DIR.rglob("*"):
        if file_path.is_file():
            rel_name = str(file_path.relative_to(VISIBLE_DIR))
            leak_report["scanned_files"].append(rel_name)
            content = file_path.read_text(encoding="utf-8", errors="ignore").lower()
            for pattern in FORBIDDEN_LEAK_PATTERNS:
                if pattern in content:
                    leak_report["clean"] = False
                    leak_report["findings"].append({
                        "file": rel_name,
                        "leaked_pattern": pattern
                    })
    return leak_report


def generate_manifest() -> dict:
    manifest = {
        "case_id": "case_01_matrix_gauge",
        "visible_bundle": {},
        "oracle_bundle": {},
    }
    for p in sorted(VISIBLE_DIR.glob("*")):
        if p.is_file():
            manifest["visible_bundle"][p.name] = {
                "sha256": sha256_of_file(p),
                "size_bytes": p.stat().st_size
            }
    for p in sorted(ORACLE_DIR.glob("*")):
        if p.is_file():
            manifest["oracle_bundle"][p.name] = {
                "sha256": sha256_of_file(p),
                "size_bytes": p.stat().st_size
            }
    return manifest


def main():
    print("=== NullLab Case 01 Leak Check & Integrity Manifest ===")
    leak_report = check_no_leakage()
    if not leak_report["clean"]:
        print("ERROR: Leak check FAILED! Leakage detected in visible bundle:", file=sys.stderr)
        for f in leak_report["findings"]:
            print(f"  - In {f['file']}: leaked pattern '{f['leaked_pattern']}'", file=sys.stderr)
        sys.exit(1)
    print(f"PASS: Scanned {len(leak_report['scanned_files'])} visible files. Zero leakage detected.")

    manifest = generate_manifest()
    manifest["leak_check"] = {"status": "PASSED", "scanned_files": leak_report["scanned_files"]}
    MANIFEST_FILE.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    print(f"PASS: Generated SHA256 manifest at {MANIFEST_FILE.name}")
    print(json.dumps(manifest, indent=2))


if __name__ == "__main__":
    main()
"""Independent mathematical oracle verifier for Case 01: SU(2) Matrix Model Gauge Invariance.

This oracle evaluates proposed counterexamples against mathematically verified criteria.
It does NOT execute untrusted code; it inspects structured sandbox execution results.
"""

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Optional


ORACLE_TRUTH_FILE = Path(__file__).resolve().parent / "oracle_truth.json"


@dataclass
class OracleVerdict:
    case_id: str
    verdict: str
    score: float
    falsification_confirmed: bool
    observed_metric_value: Optional[float]
    threshold: float
    explanation: str
    provenance: str = "NullLab independent oracle; strictly offline noiseless algebraic check"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "case_id": self.case_id,
            "verdict": self.verdict,
            "score": self.score,
            "falsification_confirmed": self.falsification_confirmed,
            "observed_metric_value": self.observed_metric_value,
            "threshold": self.threshold,
            "explanation": self.explanation,
            "provenance": self.provenance,
        }


def load_truth() -> Dict[str, Any]:
    return json.loads(ORACLE_TRUTH_FILE.read_text(encoding="utf-8"))


def evaluate_proposal_result(
    proposal_dict: Dict[str, Any],
    sandbox_result: Dict[str, Any]
) -> OracleVerdict:
    """Evaluate whether an executed proposal successfully falsified the author's claim."""
    truth = load_truth()
    conditions = truth["scientific_acceptance_conditions"]
    case_id = truth["case_id"]
    threshold = conditions["defect_threshold"]

    # 1. Execution status check
    if sandbox_result.get("status") != "SUCCESS":
        status = sandbox_result.get("status", "UNKNOWN")
        error_msg = sandbox_result.get("error", "Execution failed")
        return OracleVerdict(
            case_id=case_id,
            verdict="REJECT_EXECUTION_FAILURE",
            score=0.0,
            falsification_confirmed=False,
            observed_metric_value=None,
            threshold=threshold,
            explanation=f"Subprocess execution did not succeed. Status: {status}. Error: {error_msg}"
        )

    # 2. Citation check
    citation = str(proposal_dict.get("evidence_citation", ""))
    if conditions["required_citation"] not in citation:
        return OracleVerdict(
            case_id=case_id,
            verdict="REJECT_INVALID_CITATION",
            score=0.0,
            falsification_confirmed=False,
            observed_metric_value=None,
            threshold=threshold,
            explanation=f"Proposal must cite target source '{conditions['required_citation']}'. Provided: '{citation}'."
        )

    # 3. Hypothesis check
    hypothesis = str(proposal_dict.get("hypothesis", "")).lower()
    gauge_keywords = ["gauge", "su(2)", "symmetry", "commutator", "singlet", "invariance"]
    if not any(k in hypothesis for k in gauge_keywords):
        return OracleVerdict(
            case_id=case_id,
            verdict="REJECT_INVALID_HYPOTHESIS",
            score=0.0,
            falsification_confirmed=False,
            observed_metric_value=None,
            threshold=threshold,
            explanation=f"Hypothesis does not address gauge invariance or symmetry preservation: '{hypothesis}'."
        )

    # 4. Metric extraction
    metrics = sandbox_result.get("result_metrics", {})
    metric_name = conditions["observable_metric_name"]
    val = metrics.get(metric_name)

    # If alternative acceptable keys exist:
    if val is None:
        for alt_key in ["commutator_norm", "gauge_norm_squared", "frobenius_norm", "defect_value"]:
            if alt_key in metrics:
                val = metrics[alt_key]
                break

    if val is None or not isinstance(val, (int, float)):
        return OracleVerdict(
            case_id=case_id,
            verdict="REJECT_MISSING_METRIC",
            score=0.0,
            falsification_confirmed=False,
            observed_metric_value=None,
            threshold=threshold,
            explanation=f"Runnable test did not produce expected metric '{metric_name}' in result_metrics. Found: {list(metrics.keys())}"
        )

    val = float(val)

    # 5. Scientific acceptance test
    if val > threshold:
        return OracleVerdict(
            case_id=case_id,
            verdict="ACCEPT_FALSIFICATION",
            score=1.0,
            falsification_confirmed=True,
            observed_metric_value=val,
            threshold=threshold,
            explanation=(
                f"Defect of {val:.6e} exceeds threshold {threshold:.6e}. "
                "The counterexample empirically demonstrates non-zero gauge violation in the truncated model, "
                "falsifying the author's claim that per-mode truncation preserves physical SU(2) gauge invariance."
            )
        )
    else:
        return OracleVerdict(
            case_id=case_id,
            verdict="REJECT_NO_DEFECT",
            score=0.0,
            falsification_confirmed=False,
            observed_metric_value=val,
            threshold=threshold,
            explanation=f"Observed defect {val:.6e} did not exceed threshold {threshold:.6e}. Claim not falsified."
        )
"""External test fixture: Per-mode-cutoff SU(2) matrix model.
Origin: HorizonForge local test suite (Rinaldi et al. 2021 VQE preflight).
Attribution: Superseded baseline research code imported as an external, read-only test fixture.
Not part of NullLab's new implementation.
"""

import argparse
import json
import time

import numpy as np
from scipy import sparse
from scipy.optimize import minimize
from scipy.sparse.linalg import eigsh


def embed(op, site, cutoff=2, modes=6):
    result = sparse.csr_matrix([[1.0]])
    ident = sparse.eye(cutoff, format="csr")
    for i in range(modes):
        result = sparse.kron(result, op if i == site else ident, format="csr")
    return result


def hamiltonian(lam, cutoff=2):
    """Equation (20) of Rinaldi et al. (2021), m=1, g^2=lambda/2."""
    lowering = sparse.diags(np.sqrt(np.arange(1, cutoff)), 1, shape=(cutoff, cutoff), format="csr")
    number = sparse.diags(np.arange(cutoff, dtype=float), format="csr")
    x = [embed((lowering + lowering.T) / np.sqrt(2), i, cutoff) for i in range(6)]
    dimension = cutoff**6
    h = sparse.eye(dimension, format="csr") * 3.0
    for i in range(6):
        h = h + embed(number, i, cutoff)
    # C_gamma = epsilon_{alpha,beta,gamma} X_{1,alpha} X_{2,beta}
    for gamma in range(3):
        cross = sparse.csr_matrix((dimension, dimension))
        others = [i for i in range(3) if i != gamma]
        a, b = others
        sign = 1 if (a, b, gamma) in [(0, 1, 2), (1, 2, 0), (2, 0, 1)] else -1
        cross = sign * (x[a] @ x[3 + b] - x[b] @ x[3 + a])
        h = h + (lam / 2) * (cross @ cross)
    return h.tocsr()


def ry(state, theta, qubit, qubits=6):
    shaped = np.moveaxis(state.reshape([2] * qubits), qubit, 0)
    c, s = np.cos(theta / 2), np.sin(theta / 2)
    out = np.empty_like(shaped)
    out[0] = c * shaped[0] - s * shaped[1]
    out[1] = s * shaped[0] + c * shaped[1]
    return np.moveaxis(out, 0, qubit).reshape(-1)


def cnot(state, control, target, qubits=6):
    indices = np.arange(1 << qubits)
    select = (indices & (1 << (qubits - 1 - control))) != 0
    perm = indices.copy()
    perm[select] ^= 1 << (qubits - 1 - target)
    return state[perm]


def statevector(params, depth, layout, qubits=6):
    state = np.zeros(1 << qubits)
    state[0] = 1.0
    for layer in range(depth):
        for q in range(qubits):
            state = ry(state, params[layer * qubits + q], q, qubits)
        if layout == "ring":
            pairs = [(q, q + 1) for q in range(qubits - 1)]
        elif layout == "cross":
            half = qubits // 2
            pairs = [(q, q + half) for q in range(half)]
            pairs += [(q, q + 1) for q in range(half - 1)]
            pairs += [(q, q + 1) for q in range(half, qubits - 1)]
        elif layout == "cross_budget":
            half = qubits // 2
            pairs = [(q, q + half) for q in range(half)]
            within = [(q, q + 1) for q in range(half - 1)]
            within += [(q, q + 1) for q in range(half, qubits - 1)]
            pairs += within[::2][:half-1]
        else:
            raise ValueError(layout)
        for a, b in pairs:
            state = cnot(state, a, b, qubits)
    return state


def optimize(h, depth, layout, seed, max_evals, return_params=False):
    rng = np.random.default_rng(seed)
    qubits = int(np.log2(h.shape[0]))
    start = rng.uniform(-0.4, 0.4, size=qubits * depth)
    calls = 0
    best = np.inf
    best_params = None

    def objective(parameters):
        nonlocal calls, best, best_params
        state = statevector(parameters, depth, layout, qubits)
        value = float(state @ (h @ state))
        calls += 1
        if value < best:
            best = value
            best_params = parameters.copy()
        return value

    result = minimize(objective, start, method="COBYLA", options={"maxiter": max_evals, "rhobeg": 0.5, "tol": 1e-5})
    output = {"best_energy": float(best), "evaluations": calls, "success": bool(result.success)}
    if return_params:
        output["best_params"] = best_params
    return output


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--budget", type=int, default=300)
    p.add_argument("--seeds", type=int, default=3)
    args = p.parse_args()
    rows = []
    start = time.time()
    for lam in [0.5, 1.0, 2.0]:
        h = hamiltonian(lam)
        exact = float(eigsh(h, k=1, which="SA", tol=1e-11)[0][0])
        vacuum = float(h[0, 0])
        for depth, layout in [(1, "ring"), (2, "ring"), (2, "cross")]:
            trials = [optimize(h, depth, layout, seed, args.budget) for seed in range(args.seeds)]
            rows.append({"lambda": lam, "cutoff": 2, "exact": exact, "vacuum": vacuum,
                         "depth": depth, "layout": layout, "budget_per_seed": args.budget,
                         "trials": trials, "best": min(t["best_energy"] for t in trials)})
            print(json.dumps(rows[-1]), flush=True)
    print(json.dumps({"elapsed_seconds": round(time.time() - start, 2)}))


if __name__ == "__main__":
    main()
"""Bounded test proposal contract for NullLab scientific claim audits.

Defines the structured schema for falsification experiment proposals.
Allows rich, open-ended reasoning (hypothesis, citation, expected relation, runnable test)
rather than trivial parameter selection.
"""

import json
from dataclasses import asdict, dataclass
from typing import Any, Dict, Optional


@dataclass
class TestProposal:
    proposal_id: str
    target_case_id: str
    evidence_citation: str
    hypothesis: str
    test_type: str
    expected_relation: str
    runnable_code: str
    timeout_seconds: float = 10.0
    label: str = "SYNTHETIC_OFFLINE_FIXTURE_NO_API_CALLS"

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "TestProposal":
        return cls(
            proposal_id=data["proposal_id"],
            target_case_id=data["target_case_id"],
            evidence_citation=data["evidence_citation"],
            hypothesis=data["hypothesis"],
            test_type=data.get("test_type", "python_test_script"),
            expected_relation=data["expected_relation"],
            runnable_code=data["runnable_code"],
            timeout_seconds=float(data.get("timeout_seconds", 10.0)),
            label=data.get("label", "SYNTHETIC_OFFLINE_FIXTURE_NO_API_CALLS"),
        )

    def validate(self) -> None:
        """Validate the structural schema of the proposal."""
        if not self.proposal_id.strip():
            raise ValueError("proposal_id cannot be empty")
        if not self.target_case_id.strip():
            raise ValueError("target_case_id cannot be empty")
        if not self.evidence_citation.strip():
            raise ValueError("evidence_citation cannot be empty")
        if not self.hypothesis.strip():
            raise ValueError("hypothesis cannot be empty")
        if not self.runnable_code.strip():
            raise ValueError("runnable_code cannot be empty")
        if self.timeout_seconds <= 0 or self.timeout_seconds > 30:
            raise ValueError("timeout_seconds must be between 0 and 30 seconds")
"""Execution sandbox for NullLab test proposals.

Executes generated counterexample code in an isolated, no-network,
time-limited subprocess with read-only target source and scrubbed secrets.
"""

import ast
import json
import os
import subprocess
import sys
import tempfile
import time
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any, Dict, Optional, Set


FORBIDDEN_MODULES: Set[str] = {
    "socket",
    "requests",
    "urllib",
    "http",
    "httplib",
    "aiohttp",
    "ftplib",
    "smtplib",
    "subprocess",
    "ctypes",
    "multiprocessing",
    "pty",
    "posix",
    "webbrowser",
}

FORBIDDEN_CALLS: Set[str] = {
    "system",
    "popen",
    "spawn",
    "exec",
    "fork",
}


@dataclass
class SandboxResult:
    status: str  # SUCCESS, SECURITY_VIOLATION, TIMEOUT, RUNTIME_ERROR
    exit_code: int
    execution_time_seconds: float
    stdout: str
    stderr: str
    result_metrics: Dict[str, Any]
    error: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class SecurityASTValidator(ast.NodeVisitor):
    def __init__(self):
        self.violations = []

    def visit_Import(self, node):
        for alias in node.names:
            base_module = alias.name.split(".")[0]
            if base_module in FORBIDDEN_MODULES:
                self.violations.append(f"Forbidden module import: '{alias.name}'")
        self.generic_visit(node)

    def visit_ImportFrom(self, node):
        if node.module:
            base_module = node.module.split(".")[0]
            if base_module in FORBIDDEN_MODULES:
                self.violations.append(f"Forbidden module import from: '{node.module}'")
        self.generic_visit(node)

    def visit_Call(self, node):
        if isinstance(node.func, ast.Attribute):
            if node.func.attr in FORBIDDEN_CALLS:
                self.violations.append(f"Forbidden function call: '{node.func.attr}'")
        elif isinstance(node.func, ast.Name):
            if node.func.id in FORBIDDEN_CALLS:
                self.violations.append(f"Forbidden function call: '{node.func.id}'")
        self.generic_visit(node)


def static_security_check(code_str: str) -> Optional[str]:
    """Inspect code AST for malicious patterns or forbidden modules before execution."""
    try:
        tree = ast.parse(code_str)
    except SyntaxError as e:
        return f"Syntax error in proposal code: {e}"

    validator = SecurityASTValidator()
    validator.visit(tree)
    if validator.violations:
        return "; ".join(validator.violations)
    return None


def get_scrubbed_env(visible_source_dir: Path, temp_dir: Path) -> Dict[str, str]:
    """Build an execution environment completely stripped of all API keys or secrets."""
    safe_keys = {
        "SYSTEMROOT",
        "COMSPEC",
        "PATH",
        "WINDIR",
        "TMP",
        "TEMP",
        "NUMBER_OF_PROCESSORS",
        "OS",
    }
    clean_env: Dict[str, str] = {}
    for k, v in os.environ.items():
        k_upper = k.upper()
        # Strictly exclude anything resembling credentials, tokens, or private paths
        if any(secret_term in k_upper for secret_term in ["KEY", "SECRET", "TOKEN", "AUTH", "PASS", "MUSE", "OPENAI", "META", "GEMINI"]):
            continue
        if k_upper in safe_keys:
            clean_env[k] = v

    clean_env["PYTHONPATH"] = str(visible_source_dir.resolve())
    clean_env["TMP"] = str(temp_dir)
    clean_env["TEMP"] = str(temp_dir)
    clean_env["PYTHONIOENCODING"] = "utf-8"
    clean_env["PYTHONDONTWRITEBYTECODE"] = "1"
    return clean_env


def execute_proposal(
    code: str,
    visible_source_dir: Path,
    timeout_seconds: float = 10.0
) -> SandboxResult:
    """Run proposal code in an isolated temporary sandbox with timeout and scrubbed env."""
    # 1. Static security gate
    violation = static_security_check(code)
    if violation:
        return SandboxResult(
            status="SECURITY_VIOLATION",
            exit_code=126,
            execution_time_seconds=0.0,
            stdout="",
            stderr=violation,
            result_metrics={},
            error=violation
        )

    # 2. Setup isolated execution sandbox
    with tempfile.TemporaryDirectory(prefix="null_lab_sandbox_") as tmpdir:
        tmp_path = Path(tmpdir)
        script_file = tmp_path / "falsification_run.py"
        result_json_file = tmp_path / "result.json"

        # Instrument code wrapper to capture result.json if written
        script_file.write_text(code, encoding="utf-8")
        clean_env = get_scrubbed_env(visible_source_dir, tmp_path)

        cmd = [sys.executable, str(script_file)]
        start_time = time.time()

        try:
            proc = subprocess.run(
                cmd,
                cwd=str(tmp_path),
                env=clean_env,
                capture_output=True,
                text=True,
                timeout=timeout_seconds,
            )
            elapsed = time.time() - start_time
            stdout = proc.stdout
            stderr = proc.stderr
            exit_code = proc.returncode

            # Extract result metrics from result.json or stdout JSON
            metrics: Dict[str, Any] = {}
            if result_json_file.exists():
                try:
                    metrics = json.loads(result_json_file.read_text(encoding="utf-8"))
                except Exception:
                    pass

            if not metrics and stdout:
                # Attempt to parse last JSON object from stdout
                for line in reversed(stdout.splitlines()):
                    line = line.strip()
                    if line.startswith("{") and line.endswith("}"):
                        try:
                            parsed = json.loads(line)
                            if isinstance(parsed, dict):
                                metrics = parsed
                                break
                        except Exception:
                            continue

            if exit_code == 0:
                return SandboxResult(
                    status="SUCCESS",
                    exit_code=exit_code,
                    execution_time_seconds=elapsed,
                    stdout=stdout,
                    stderr=stderr,
                    result_metrics=metrics,
                    error=None
                )
            else:
                return SandboxResult(
                    status="RUNTIME_ERROR",
                    exit_code=exit_code,
                    execution_time_seconds=elapsed,
                    stdout=stdout,
                    stderr=stderr,
                    result_metrics=metrics,
                    error=f"Process exited with non-zero exit code: {exit_code}"
                )

        except subprocess.TimeoutExpired as e:
            elapsed = time.time() - start_time
            return SandboxResult(
                status="TIMEOUT",
                exit_code=124,
                execution_time_seconds=elapsed,
                stdout=e.stdout.decode() if isinstance(e.stdout, bytes) else (e.stdout or ""),
                stderr=f"Execution timed out after {timeout_seconds} seconds",
                result_metrics={},
                error=f"Execution timed out after {timeout_seconds}s"
            )
        except Exception as e:
            elapsed = time.time() - start_time
            return SandboxResult(
                status="RUNTIME_ERROR",
                exit_code=1,
                execution_time_seconds=elapsed,
                stdout="",
                stderr=str(e),
                result_metrics={},
                error=str(e)
            )
"""Synthetic fake client for NullLab offline replay.

Contains mock proposals unmistakably labeled SYNTHETIC_OFFLINE_FIXTURE_NO_API_CALLS.
Zero paid Meta/Muse calls are made.
"""

from typing import Dict
from contract.proposal import TestProposal


def get_synthetic_proposals() -> Dict[str, TestProposal]:
    """Return synthetic proposals for offline end-to-end replay."""

    # 1. Valid counterexample proposal
    valid_counterexample_code = """
import json
import numpy as np
from scipy import sparse
from scipy.sparse.linalg import norm
import matrix_vqe_preflight as target

def compute_gauge_defect():
    cutoff = 2
    lam = 1.0
    h = target.hamiltonian(lam=lam, cutoff=cutoff)
    
    # Construct mode operators X and P for the 6 modes
    lowering = sparse.diags(np.sqrt(np.arange(1, cutoff)), 1, shape=(cutoff, cutoff), format="csr")
    x = [target.embed((lowering + lowering.T) / np.sqrt(2), i, cutoff) for i in range(6)]
    p = [target.embed(1j * (lowering.T - lowering) / np.sqrt(2), i, cutoff) for i in range(6)]
    
    # SU(2) gauge generator G_0 = (X_1 P_2 - X_2 P_1) + (X_4 P_5 - X_5 P_4)
    g0 = (x[1] @ p[2] - x[2] @ p[1]) + (x[4] @ p[5] - x[5] @ p[4])
    
    # Commutator [H, G_0]
    comm = h @ g0 - g0 @ h
    defect = float(norm(comm))
    
    result = {
        "gauge_defect": defect,
        "commutator_norm": defect,
        "cutoff": cutoff,
        "lambda": lam,
        "dimension": int(h.shape[0])
    }
    with open("result.json", "w", encoding="utf-8") as f:
        json.dump(result, f)
    print(json.dumps(result))

if __name__ == "__main__":
    compute_gauge_defect()
"""

    proposal_valid = TestProposal(
        proposal_id="proposal_01_valid_counterexample",
        target_case_id="case_01_matrix_gauge",
        evidence_citation="matrix_vqe_preflight.py:hamiltonian",
        hypothesis="Truncating each of the 6 bosonic modes to independent Fock cutoff=2 breaks SU(2) gauge invariance because mode truncation truncates the raising operator non-uniformly across coupled quartic interactions. Therefore, the commutator of the Hamiltonian with the SU(2) gauge generators [H, G_a] is non-zero, violating physical gauge symmetry.",
        test_type="commutator_frobenius_norm",
        expected_relation="[H, G_a] == 0 for exact physical SU(2) gauge invariance",
        runnable_code=valid_counterexample_code.strip(),
        timeout_seconds=10.0,
        label="SYNTHETIC_OFFLINE_FIXTURE_NO_API_CALLS"
    )

    # 2. Invalid hypothesis proposal (testing an irrelevant property that doesn't falsify claim)
    invalid_hypothesis_code = """
import json
import matrix_vqe_preflight as target

def check_trace():
    h = target.hamiltonian(lam=1.0, cutoff=2)
    tr = float(h.diagonal().sum())
    result = {
        "trace_value": tr,
        "gauge_defect": 0.0  # Zero defect, does not falsify
    }
    with open("result.json", "w", encoding="utf-8") as f:
        json.dump(result, f)
    print(json.dumps(result))

if __name__ == "__main__":
    check_trace()
"""

    proposal_invalid_hypothesis = TestProposal(
        proposal_id="proposal_02_invalid_hypothesis",
        target_case_id="case_01_matrix_gauge",
        evidence_citation="matrix_vqe_preflight.py:embed",
        hypothesis="The truncation fails because the Hamiltonian trace is strictly zero.",
        test_type="trace_check",
        expected_relation="trace(H) == 0",
        runnable_code=invalid_hypothesis_code.strip(),
        timeout_seconds=5.0,
        label="SYNTHETIC_OFFLINE_FIXTURE_NO_API_CALLS"
    )

    # 3. Malicious / Unsafe proposal (attempts network access)
    unsafe_code = """
import socket
import matrix_vqe_preflight as target

s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
print("Attempting network connection")
"""

    proposal_unsafe = TestProposal(
        proposal_id="proposal_03_unsafe_code_import",
        target_case_id="case_01_matrix_gauge",
        evidence_citation="matrix_vqe_preflight.py:hamiltonian",
        hypothesis="Testing gauge invariance by contacting an external symmetry validation server.",
        test_type="network_probe",
        expected_relation="External server confirms symmetry",
        runnable_code=unsafe_code.strip(),
        timeout_seconds=5.0,
        label="SYNTHETIC_OFFLINE_FIXTURE_NO_API_CALLS"
    )

    # 4. Timeout / Infinite loop proposal
    timeout_code = """
import time
import matrix_vqe_preflight as target

while True:
    time.sleep(0.1)
"""

    proposal_timeout = TestProposal(
        proposal_id="proposal_04_timeout_loop",
        target_case_id="case_01_matrix_gauge",
        evidence_citation="matrix_vqe_preflight.py:hamiltonian",
        hypothesis="Testing non-terminating numerical state expansion.",
        test_type="infinite_loop",
        expected_relation="Convergence in infinite time",
        runnable_code=timeout_code.strip(),
        timeout_seconds=2.0,
        label="SYNTHETIC_OFFLINE_FIXTURE_NO_API_CALLS"
    )

    return {
        "valid": proposal_valid,
        "invalid_hypothesis": proposal_invalid_hypothesis,
        "unsafe_code": proposal_unsafe,
        "timeout": proposal_timeout,
    }
"""Independent verification of IBM Quantum environment and credentials.

Checks:
1. Python environment for qiskit and qiskit-ibm-runtime.
2. System configuration directories (~/.qiskit, ~/.ibm-quantum, etc.).
3. Environment variables (IBM_QUANTUM_TOKEN, QISKIT_IBM_TOKEN, IBMQ_TOKEN).
4. Official Open Plan limits and execution policies.

Safe: Never prints or logs sensitive tokens.
"""

import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path


def check_ibm_environment():
    home = Path.home()
    config_paths = [
        home / ".qiskit" / "qiskitrc",
        home / ".ibm-quantum" / "config",
        home / ".config" / "qiskit" / "qiskitrc",
        Path.cwd() / ".env"
    ]

    found_configs = []
    for p in config_paths:
        if p.exists():
            found_configs.append(str(p))

    env_token_keys = ["IBM_QUANTUM_TOKEN", "QISKIT_IBM_TOKEN", "IBMQ_TOKEN"]
    found_env_keys = [k for k in env_token_keys if os.getenv(k)]

    # Check package availability
    packages = {}
    for pkg in ["qiskit", "qiskit_ibm_runtime", "scipy", "numpy", "networkx"]:
        try:
            __import__(pkg)
            packages[pkg] = "available"
        except ImportError:
            packages[pkg] = "not installed"

    report = {
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "packages": packages,
        "config_files_found": found_configs,
        "env_token_variables_set": found_env_keys,
        "account_configured": len(found_configs) > 0 or len(found_env_keys) > 0,
        "open_plan_official_specs": {
            "monthly_quota_runtime": "10 minutes free QPU runtime per 28-day rolling window",
            "region": "us-east",
            "execution_mode": "Job mode (fair-share queue; sessions not supported on Open Plan)",
            "queue_behavior": "Global fair-share scheduler; open plan jobs share lowest priority tier; wait times fluctuate from 15 min to multi-hour backlogs",
            "hardware_scale": "Utility-scale systems (Eagle 127q, Heron 133q/156q)"
        }
    }
    return report


if __name__ == "__main__":
    rep = check_ibm_environment()
    out_file = Path(__file__).resolve().parent / "ibm_access_audit.json"
    out_file.write_text(json.dumps(rep, indent=2), encoding="utf-8")
    print(f"IBM Access Audit written to {out_file}")
    print(f"Account Configured: {rep['account_configured']}")
    print(f"Qiskit Installed: {rep['packages'].get('qiskit')}")
"""Local simulator for 10-qubit circuit benchmark with heavy-hex coupling and realistic calibration noise.

Circuits:
1. GHZ-10 (Greenberger-Horne-Zeilinger state preparation): Ideal output 50% |0000000000> and 50% |1111111111>.
2. Bernstein-Vazirani 10 (hidden bitstring '101010101'): Ideal output 100% |1010101010>.
3. Mirror Randomized Benchmarking 10 (Clifford layers + exact inverse): Ideal output 100% |0000000000>.

Layout Candidates (10 qubits mapped onto a 16-qubit heavy-hex patch):
- Layout A (Qiskit Default / Heuristic VF2 routing): Linear low-degree line on best reported 2Q errors.
- Layout B (Calibration-Aware Greedy): Chooses qubits minimizing sum of reported calibration Pauli errors.
- Layout C (Dispersed / Bridge-heavy Random Layout): Uniform random connected sub-graph.
- Layout D (Sub-optimal Edge Layout): Uses higher calibration error edges.

Noise Model:
Simulates realistic QPU noise:
- Reported calibration 2Q gate errors (1e-2 to 3e-2)
- Readout assignment errors (1e-2 to 4e-2)
- Coherence decay (T1/T2 dephasing)
- Real physical hardware drift: hidden spectator crosstalk & drift (+/- 40% deviation from calibration snapshot).
"""

import json
import numpy as np
from pathlib import Path


class QuantumMechanicSimulator:
    def __init__(self, seed=42):
        self.rng = np.random.default_rng(seed)
        self.num_qubits = 10
        
        # Heavy-hex 16-node coupling graph patch (representing physical qubits 0..15 on an IBM Heron/Eagle segment)
        # Edges form heavy-hex rungs
        self.edges = [
            (0, 1), (1, 2), (2, 3), (3, 4),
            (1, 5), (3, 7),
            (5, 6), (6, 7), (7, 8),
            (6, 10), (8, 12),
            (9, 10), (10, 11), (11, 12), (12, 13),
            (10, 14), (12, 15)
        ]
        
        # Static calibration report (what Qiskit transpiler sees)
        self.calibrations = {}
        for edge in self.edges:
            # Baseline 2Q error: mean 0.012, range 0.006 to 0.028
            err = float(self.rng.uniform(0.008, 0.024))
            self.calibrations[f"{edge[0]}_{edge[1]}"] = round(err, 4)
            self.calibrations[f"{edge[1]}_{edge[0]}"] = round(err, 4)
            
        self.readout_errors = {
            i: round(float(self.rng.uniform(0.012, 0.035)), 4) for i in range(16)
        }
        
        # Hidden true physical drift & spectator crosstalk (unknown to calibration snapshot)
        self.physical_drift = {}
        for edge in self.edges:
            # Some edges drift worse by +50% to +100% due to TLS defect or spectator traffic
            drift_factor = float(self.rng.uniform(0.7, 1.8))
            self.physical_drift[f"{edge[0]}_{edge[1]}"] = drift_factor
            self.physical_drift[f"{edge[1]}_{edge[0]}"] = drift_factor

    def get_candidate_layouts(self):
        """Define 4 candidate connected 10-qubit layouts on the 16-qubit heavy-hex patch."""
        layouts = {
            "layout_qiskit_default": {
                "name": "Qiskit Default (VF2 Calibration-Guided Line)",
                "description": "Standard Qiskit heuristic picking lowest calibration 2Q errors in a connected line",
                "physical_qubits": [0, 1, 2, 3, 4, 7, 8, 12, 11, 10],
                "circuit_depth_factor": 1.0,
                "swaps_required": 2
            },
            "layout_calibration_greedy": {
                "name": "Calibration-Aware Greedy Subtree",
                "description": "Greedy minimization of reported static calibration error",
                "physical_qubits": [1, 2, 3, 5, 6, 7, 8, 10, 11, 12],
                "circuit_depth_factor": 1.05,
                "swaps_required": 1
            },
            "layout_random_connected": {
                "name": "Random Valid Connected Layout",
                "description": "Uniform connected 10-qubit subgraph without calibration preference",
                "physical_qubits": [0, 1, 5, 6, 7, 8, 9, 10, 11, 14],
                "circuit_depth_factor": 1.30,
                "swaps_required": 6
            },
            "layout_stress_edge": {
                "name": "High-Connectivity Stress Layout",
                "description": "Uses central heavy-hex junctions with higher spectator crosstalk risk",
                "physical_qubits": [1, 3, 5, 6, 7, 8, 10, 12, 13, 15],
                "circuit_depth_factor": 1.20,
                "swaps_required": 4
            }
        }
        return layouts

    def simulate_circuit_family(self, circuit_name, shots=1000, seeds=(0, 1, 2)):
        """Simulate experimental trials with exact ideal targets."""
        layouts = self.get_candidate_layouts()
        results = {}
        
        # Base gate requirements
        if circuit_name == "GHZ_10":
            base_2q = 9
            base_depth = 10
            ideal_metric = "Fidelity / Parity Success (P(|00...0>) + P(|11...1>))"
        elif circuit_name == "Bernstein_Vazirani_10":
            base_2q = 5
            base_depth = 8
            ideal_metric = "Success Probability P(target bitstring)"
        elif circuit_name == "Mirror_RB_10":
            base_2q = 18
            base_depth = 22
            ideal_metric = "Ground State Survival P(|00...0>)"
        else:
            raise ValueError(f"Unknown circuit family {circuit_name}")

        for layout_key, layout in layouts.items():
            trials = []
            for seed in seeds:
                rng = np.random.default_rng(seed * 100 + hash(layout_key) % 1000)
                
                # QPU gate count after transpilation / routing SWAPs
                effective_2q = base_2q + layout["swaps_required"] * 3
                total_depth = int(base_depth * layout["circuit_depth_factor"])
                
                # 1. Calibration predicted fidelity (what offline tools expect)
                calib_errs = []
                qubits = layout["physical_qubits"]
                for i in range(len(qubits) - 1):
                    pair = f"{qubits[i]}_{qubits[i+1]}"
                    calib_errs.append(self.calibrations.get(pair, 0.020))
                
                mean_calib_2q = float(np.mean(calib_errs))
                predicted_fidelity = max(0.1, (1.0 - mean_calib_2q) ** effective_2q)
                
                # 2. True physical fidelity under hardware drift & crosstalk
                physical_errs = []
                for i in range(len(qubits) - 1):
                    pair = f"{qubits[i]}_{qubits[i+1]}"
                    drift = self.physical_drift.get(pair, 1.0)
                    physical_errs.append(self.calibrations.get(pair, 0.020) * drift)
                    
                mean_phys_2q = float(np.mean(physical_errs))
                
                # Add readout assignment noise
                mean_ro = float(np.mean([self.readout_errors[q] for q in qubits]))
                
                true_fidelity = max(0.05, ((1.0 - mean_phys_2q) ** effective_2q) * ((1.0 - mean_ro) ** 2))
                # Hardware measurement variance under binomial shots
                observed_success_count = rng.binomial(shots, true_fidelity)
                observed_metric = observed_success_count / shots
                std_err = float(np.sqrt(observed_metric * (1.0 - observed_metric) / shots))
                
                trials.append({
                    "seed": seed,
                    "measured_metric": round(float(observed_metric), 4),
                    "uncertainty_std_err": round(std_err, 4),
                    "predicted_calib_metric": round(float(predicted_fidelity), 4),
                    "calibration_disagreement": round(float(observed_metric - predicted_fidelity), 4),
                    "transpiled_2q_gates": effective_2q,
                    "circuit_depth": total_depth
                })
                
            metrics = [t["measured_metric"] for t in trials]
            disagreements = [t["calibration_disagreement"] for t in trials]
            results[layout_key] = {
                "name": layout["name"],
                "physical_qubits": layout["physical_qubits"],
                "median_measured_metric": round(float(np.median(metrics)), 4),
                "std_measured_metric": round(float(np.std(metrics)), 4),
                "median_calibration_disagreement": round(float(np.median(disagreements)), 4),
                "transpiled_2q_gates": trials[0]["transpiled_2q_gates"],
                "circuit_depth": trials[0]["circuit_depth"],
                "trials": trials
            }
            
        return {
            "circuit_family": circuit_name,
            "metric_name": ideal_metric,
            "shots": shots,
            "seeds": list(seeds),
            "estimated_qpu_seconds_per_circuit": round(shots * 0.0001 + base_depth * 0.0002, 3),
            "layouts": results
        }


def run_experiment_suite():
    sim = QuantumMechanicSimulator(seed=20261028)
    circuits = ["GHZ_10", "Bernstein_Vazirani_10", "Mirror_RB_10"]
    
    suite_results = {
        "execution_mode": "Local High-Fidelity Hardware Simulator (Noiseless + Drifted Calibration Patch)",
        "hardware_model": "IBM Heavy-Hex 16-qubit segment (Heron/Eagle architecture)",
        "shots_per_circuit": 1000,
        "seeds": [0, 1, 2],
        "circuits": {}
    }
    
    total_est_qpu_sec = 0.0
    for c in circuits:
        res = sim.simulate_circuit_family(c, shots=1000, seeds=(0, 1, 2))
        suite_results["circuits"][c] = res
        # 4 layouts * 3 seeds * estimated runtime
        total_est_qpu_sec += len(res["layouts"]) * len(res["seeds"]) * res["estimated_qpu_seconds_per_circuit"]

    suite_results["total_estimated_qpu_runtime_seconds"] = round(total_est_qpu_sec, 2)
    
    out_file = Path(__file__).resolve().parent / "dry_run_results.json"
    out_file.write_text(json.dumps(suite_results, indent=2), encoding="utf-8")
    print(f"Dry run experiment complete. Written to {out_file}")
    print(f"Total Estimated QPU Runtime: {suite_results['total_estimated_qpu_runtime_seconds']} seconds")
    return suite_results


if __name__ == "__main__":
    run_experiment_suite()
