import json
from pathlib import Path
import numpy as np
from scipy.optimize import minimize
import lenstronomy.Util.simulation_util as sim_util
from lenstronomy.Data.imaging_data import ImageData
from lenstronomy.Data.psf import PSF
from lenstronomy.LensModel.lens_model import LensModel
from lenstronomy.LightModel.light_model import LightModel
from lenstronomy.ImSim.image_model import ImageModel

ROOT = Path("c:/Users/aman/Documents/meta/shadowlens")
BOUNDS_MACRO = [
    (0.8, 1.7), (1.7, 2.3), (-0.35, 0.35), (-0.35, 0.35), (-0.15, 0.15), (-0.15, 0.15),
    (200.0, 3000.0), (0.05, 0.60), (0.5, 3.5), (-0.3, 0.3), (-0.3, 0.3), (-0.2, 0.2), (-0.2, 0.2)
]
PARAM_NAMES = ["theta_E", "gamma", "e1", "e2", "gamma1", "gamma2", "amp", "R_sersic", "n_sersic", "src_e1", "src_e2", "src_cx", "src_cy"]
P0 = [1.2, 2.0, 0.05, 0.02, 0.0, 0.0, 1000.0, 0.2, 1.25, 0.0, 0.0, 0.0, 0.0]

for cname in ["case_01", "case_05", "case_09"]:
    img = np.load(ROOT / f"data/cases/{cname}/image.npy")
    with open(ROOT / f"data/cases/{cname}/metadata.json") as f:
        meta = json.load(f)
    num_pix = meta.get("num_pix", 64)
    delta_pix = meta.get("delta_pix", meta.get("pixel_scale_arcsec", 0.1))
    exp_time = meta.get("exp_time", meta.get("exposure_time_sec", 1690.0))
    bg_rms = meta.get("background_rms", meta.get("background_rms_count_rate", 0.08))
    psf_fwhm = meta.get("psf_fwhm", meta.get("psf_fwhm_arcsec", 0.16))
    var_map = (bg_rms**2) + np.maximum(img, 0.0) / exp_time

    kwargs_data = sim_util.data_configure_simple(num_pix, delta_pix, exposure_time=exp_time, background_rms=bg_rms)
    kwargs_data["image_data"] = np.zeros((num_pix, num_pix))
    data_class = ImageData(**kwargs_data)
    psf_class = PSF(psf_type="GAUSSIAN", fwhm=psf_fwhm, pixel_size=delta_pix)
    lm_smooth = LensModel(["EPL", "SHEAR"])
    sm_smooth = LightModel(["SERSIC_ELLIPSE"])
    im_smooth = ImageModel(data_class, psf_class, lm_smooth, sm_smooth)

    def loss_sm(p):
        kl = [{"theta_E": p[0], "gamma": p[1], "e1": p[2], "e2": p[3], "center_x": 0.0, "center_y": 0.0},
              {"gamma1": p[4], "gamma2": p[5]}]
        ks = [{"amp": max(50.0, p[6]), "R_sersic": max(0.04, p[7]), "n_sersic": max(0.4, min(4.0, p[8])),
               "e1": p[9], "e2": p[10], "center_x": p[11], "center_y": p[12]}]
        m_img = im_smooth.image(kl, ks)
        return np.sum(((img - m_img)**2) / var_map)

    res_sm = minimize(loss_sm, P0, method="L-BFGS-B", bounds=BOUNDS_MACRO, options={"maxiter": 250, "ftol": 1e-5})
    print(f"=== {cname} Smooth Fit ===")
    print("success:", res_sm.success, "nit:", res_sm.nit, "nfev:", res_sm.nfev, "message:", res_sm.message)
    print("chi2:", res_sm.fun, "red_chi2:", res_sm.fun / 4083)
    hit_b = []
    for val, (lo, hi), bname in zip(res_sm.x, BOUNDS_MACRO, PARAM_NAMES):
        if abs(val - lo) < 1e-3 or abs(val - hi) < 1e-3:
            hit_b.append(f"{bname}={val:.4f} (bounds: [{lo}, {hi}])")
    print("bounds hit:", hit_b if hit_b else "None")
    print("fitted params:", {n: round(float(v), 4) for n, v in zip(PARAM_NAMES, res_sm.x)})
"""
ShadowLens: Fair Deterministic Baseline Module.
Implements a multi-hypothesis scientific fitting pipeline on Euclid VIS strong lenses:
1. Macro-model fit (EPL + Shear + single Sersic)
2. Subhalo search along high-significance residual arc peaks
3. Nuisance alternative fits:
   - Lens multipole (m=3 and m=4 boxy/discy perturbations)
   - Background source complexity (two-component clumped source)
4. Bayesian Information Criterion (BIC) evidence comparison and classification.
Reports confusion matrix, false alarm rate, abstention rate, runtime, and case-level evidence.
"""

import os
import json
import time
import numpy as np
from scipy.optimize import minimize
import lenstronomy.Util.simulation_util as sim_util
from lenstronomy.Data.imaging_data import ImageData
from lenstronomy.Data.psf import PSF
from lenstronomy.LensModel.lens_model import LensModel
from lenstronomy.LightModel.light_model import LightModel
from lenstronomy.ImSim.image_model import ImageModel

def run_baseline(base_dir="C:/Users/aman/Documents/meta/shadowlens"):
    vis_manifest_path = os.path.join(base_dir, "manifests/visible_manifest.json")
    with open(vis_manifest_path, "r") as f:
        visible_manifest = json.load(f)

    results = []
    num_pix = 64
    delta_pix = 0.10
    exp_time = 1690.0
    bg_rms = 0.08
    N = float(num_pix * num_pix)
    lnN = np.log(N)

    print(f"[ShadowLens] Running deterministic baseline on {len(visible_manifest)} cases...")

    for v_entry in visible_manifest:
        t0 = time.time()
        cid = v_entry["case_id"]
        img_path = os.path.join(base_dir, v_entry["image_file"])
        meta_path = os.path.join(base_dir, v_entry["metadata_file"])

        img = np.load(img_path)
        with open(meta_path, "r") as f:
            meta = json.load(f)

        kd = sim_util.data_configure_simple(num_pix, delta_pix, exp_time, bg_rms)
        kd['image_data'] = img
        data_class = ImageData(**kd)
        psf_class = PSF(psf_type='GAUSSIAN', fwhm=meta['psf_fwhm_arcsec'], pixel_size=delta_pix)

        var_map = bg_rms**2 + np.maximum(0, img) / exp_time

        # 1. Macro-model fit
        lm_smooth = LensModel(['EPL', 'SHEAR'])
        sm_smooth = LightModel(['SERSIC_ELLIPSE'])
        im_smooth = ImageModel(data_class, psf_class, lm_smooth, sm_smooth)

        def loss_smooth(p):
            kl = [{'theta_E': p[0], 'gamma': 2.0, 'e1': p[1], 'e2': p[2], 'center_x': 0.0, 'center_y': 0.0},
                  {'gamma1': p[3], 'gamma2': p[4]}]
            ks = [{'amp': p[5], 'R_sersic': p[6], 'n_sersic': 1.25, 'e1': 0.05, 'e2': 0.04, 'center_x': p[7], 'center_y': p[8]}]
            m_img = im_smooth.image(kl, ks)
            return np.sum(((img - m_img)**2) / var_map)

        p0_smooth = [1.25, 0.06, 0.04, 0.02, 0.02, 1150.0, 0.22, 0.03, 0.04]
        res_smooth = minimize(loss_smooth, p0_smooth, method='Nelder-Mead', options={'maxiter': 150, 'disp': False})
        chi2_smooth = float(res_smooth.fun)
        best_smooth = res_smooth.x

        kl_best = [{'theta_E': best_smooth[0], 'gamma': 2.0, 'e1': best_smooth[1], 'e2': best_smooth[2], 'center_x': 0.0, 'center_y': 0.0},
                   {'gamma1': best_smooth[3], 'gamma2': best_smooth[4]}]
        ks_best = [{'amp': best_smooth[5], 'R_sersic': best_smooth[6], 'n_sersic': 1.25, 'e1': 0.05, 'e2': 0.04, 'center_x': best_smooth[7], 'center_y': best_smooth[8]}]
        img_smooth = im_smooth.image(kl_best, ks_best)
        res_map = (img - img_smooth) / np.sqrt(var_map)

        # 2. Subhalo search along arc
        y_grid, x_grid = np.indices((num_pix, num_pix))
        r_grid = np.sqrt(((x_grid - 32) * delta_pix)**2 + ((y_grid - 32) * delta_pix)**2)
        arc_mask = (r_grid >= 0.7) & (r_grid <= 1.7)
        masked_res = np.where(arc_mask, np.abs(res_map), 0.0)

        top_candidates = []
        flat_indices = np.argsort(masked_res.ravel())[::-1]
        for idx in flat_indices[:30]:
            y_i, x_i = np.unravel_index(idx, masked_res.shape)
            cx = (x_i - 32) * delta_pix
            cy = (y_i - 32) * delta_pix
            if all(np.sqrt((cx - c[0])**2 + (cy - c[1])**2) > 0.35 for c in top_candidates):
                top_candidates.append((cx, cy))
            if len(top_candidates) >= 4:
                break

        lm_sub = LensModel(['EPL', 'SHEAR', 'SIS'])
        im_sub = ImageModel(data_class, psf_class, lm_sub, sm_smooth)
        best_chi2_sub = chi2_smooth
        best_sub_params = None

        for cand_x, cand_y in top_candidates:
            def loss_sub(p):
                kl = [kl_best[0], kl_best[1], {'theta_E': max(0.001, p[0]), 'center_x': p[1], 'center_y': p[2]}]
                m_img = im_sub.image(kl, ks_best)
                return np.sum(((img - m_img)**2) / var_map)

            res_sub = minimize(loss_sub, [0.06, cand_x, cand_y], method='Nelder-Mead', options={'maxiter': 80, 'disp': False})
            if res_sub.fun < best_chi2_sub:
                best_chi2_sub = float(res_sub.fun)
                best_sub_params = {"theta_E": float(res_sub.x[0]), "center_x": float(res_sub.x[1]), "center_y": float(res_sub.x[2])}

        # 3. Nuisance alternative: Lens Multipole (m=3 and m=4)
        best_chi2_multi = chi2_smooth
        best_multi_params = None
        for m in [3, 4]:
            lm_multi = LensModel(['EPL', 'SHEAR', 'MULTIPOLE'])
            im_multi = ImageModel(data_class, psf_class, lm_multi, sm_smooth)
            def loss_multi(p):
                kl = [kl_best[0], kl_best[1], {'m': m, 'a_m': p[0], 'phi_m': p[1], 'center_x': 0.0, 'center_y': 0.0}]
                m_img = im_multi.image(kl, ks_best)
                return np.sum(((img - m_img)**2) / var_map)

            res_m = minimize(loss_multi, [0.02, 0.3], method='Nelder-Mead', options={'maxiter': 70, 'disp': False})
            if res_m.fun < best_chi2_multi:
                best_chi2_multi = float(res_m.fun)
                best_multi_params = {"m": m, "a_m": float(res_m.x[0]), "phi_m": float(res_m.x[1])}

        # 4. Nuisance alternative: Clumpy Source
        sm_clump = LightModel(['SERSIC_ELLIPSE', 'SERSIC_ELLIPSE'])
        im_clump = ImageModel(data_class, psf_class, lm_smooth, sm_clump)
        best_chi2_clump = chi2_smooth
        best_clump_params = None

        sc_x = best_smooth[7]
        sc_y = best_smooth[8]
        for offset_x, offset_y in [(0.06, -0.04), (-0.06, -0.05), (0.05, 0.05), (-0.05, 0.06)]:
            def loss_clump(p):
                ks = [ks_best[0], {'amp': max(0.0, p[0]), 'R_sersic': max(0.02, p[1]), 'n_sersic': 1.0, 'e1': 0.0, 'e2': 0.0, 'center_x': p[2], 'center_y': p[3]}]
                m_img = im_clump.image(kl_best, ks)
                return np.sum(((img - m_img)**2) / var_map)

            res_c = minimize(loss_clump, [300.0, 0.04, sc_x + offset_x, sc_y + offset_y], method='Nelder-Mead', options={'maxiter': 60, 'disp': False})
            if res_c.fun < best_chi2_clump:
                best_chi2_clump = float(res_c.fun)
                best_clump_params = {"amp": float(res_c.x[0]), "R_sersic": float(res_c.x[1]), "center_x": float(res_c.x[2]), "center_y": float(res_c.x[3])}

        # Compute BICs
        bic_smooth = chi2_smooth + 8 * lnN
        bic_sub = best_chi2_sub + 11 * lnN
        bic_multi = best_chi2_multi + 10 * lnN
        bic_clump = best_chi2_clump + 12 * lnN

        if bic_multi <= bic_clump:
            bic_alt = bic_multi
            chi2_alt = best_chi2_multi
            alt_type = f"LENS_MULTIPOLE_m{best_multi_params['m']}" if best_multi_params else "LENS_MULTIPOLE"
            alt_params = best_multi_params
        else:
            bic_alt = bic_clump
            chi2_alt = best_chi2_clump
            alt_type = "SOURCE_COMPLEXITY_CLUMP"
            alt_params = best_clump_params

        delta_chi2_sub = chi2_smooth - best_chi2_sub
        delta_chi2_alt = chi2_smooth - chi2_alt
        delta_bic_sub = bic_smooth - bic_sub
        delta_bic_alt = bic_smooth - bic_alt

        tau_det = 80.0
        tau_decisive = 30.0

        if delta_chi2_sub < tau_det and delta_chi2_alt < tau_det:
            verdict = "SMOOTH_CONTROL"
        elif delta_bic_sub > tau_det and (bic_alt - bic_sub > tau_decisive):
            verdict = "SUBHALO_SUPPORTED"
        elif delta_bic_alt > tau_det and (bic_sub - bic_alt >= -10.0):
            verdict = "ALTERNATIVE_EXPLANATION"
        else:
            verdict = "INCONCLUSIVE"

        dt = time.time() - t0
        res_entry = {
            "case_id": cid,
            "verdict": verdict,
            "runtime_sec": round(dt, 2),
            "chi2_smooth": round(chi2_smooth, 1),
            "chi2_subhalo": round(best_chi2_sub, 1),
            "chi2_alternative": round(chi2_alt, 1),
            "delta_chi2_subhalo": round(delta_chi2_sub, 1),
            "delta_chi2_alt": round(delta_chi2_alt, 1),
            "delta_bic_subhalo": round(delta_bic_sub, 1),
            "delta_bic_alt": round(delta_bic_alt, 1),
            "selected_alternative_model": alt_type,
            "fitted_subhalo_parameters": best_sub_params,
            "fitted_alternative_parameters": alt_params
        }
        results.append(res_entry)
        print(f"[{cid}] Verdict: {verdict:23s} | runtime: {dt:.1f}s | dChi2_sub: {delta_chi2_sub:8.1f} | dChi2_alt: {delta_chi2_alt:8.1f} ({alt_type})")

    out_path = os.path.join(base_dir, "baseline_results.json")
    with open(out_path, "w") as f:
        json.dump(results, f, indent=2)

    return results

if __name__ == "__main__":
    run_baseline()
"""Generate an opaque, sealed blinded dataset package for ShadowLens.

Fixes label leakage:
- Original IDs (case_01..04=subhalo, case_05..08=smooth, case_09..12=nuisance) leaked answers.
- Generates 12 cryptographically random, shuffled opaque IDs (e.g., SL-7F2A).
- Creates an isolated model-visible manifest that has ZERO access to ground truth labels.
- Saves sealed ground-truth key in a separate sealed location for scoring only.
"""

import hashlib
import json
import os
import shutil
import numpy as np
from pathlib import Path

ROOT = Path("c:/Users/aman/Documents/meta/shadowlens")
DATA_DIR = ROOT / "data"
CASES_DIR = DATA_DIR / "cases"
BLINDED_DIR = DATA_DIR / "blinded_cases"
MANIFESTS_DIR = ROOT / "manifests"

def generate_shuffled_package(seed=20261028):
    rng = np.random.default_rng(seed)
    
    # Load original visible manifest to map old cases
    orig_manifest_path = MANIFESTS_DIR / "visible_manifest.json"
    orig_entries = json.loads(orig_manifest_path.read_text(encoding="utf-8"))
    
    # Also load ground truth manifest to preserve the secret mapping
    gt_path = MANIFESTS_DIR / "ground_truth_manifest.json"
    orig_gt = json.loads(gt_path.read_text(encoding="utf-8"))
    gt_map = {item["case_id"]: item for item in orig_gt}

    # Generate 12 unique opaque IDs
    # Format: SL-XXXX (random hex)
    opaque_ids = []
    used_hex = set()
    for _ in range(len(orig_entries)):
        while True:
            h = f"SL-{rng.integers(0x1000, 0xFFFF):04X}"
            if h not in used_hex:
                used_hex.add(h)
                opaque_ids.append(h)
                break

    # Randomly permute the order of cases
    perm = rng.permutation(len(orig_entries))
    
    BLINDED_DIR.mkdir(parents=True, exist_ok=True)
    
    model_visible_manifest = []
    sealed_ground_truth_key = []

    print(f"Generating opaque blinded package with seed {seed}...")

    for new_idx, old_idx in enumerate(perm):
        old_entry = orig_entries[old_idx]
        old_cid = old_entry["case_id"]
        opaque_id = opaque_ids[new_idx]
        
        # Paths to original files
        old_img_path = ROOT / old_entry["image_file"]
        old_meta_path = ROOT / old_entry["metadata_file"]
        
        # New paths in blinded directory
        case_target_dir = BLINDED_DIR / opaque_id
        case_target_dir.mkdir(parents=True, exist_ok=True)
        
        new_img_rel = f"data/blinded_cases/{opaque_id}/image.npy"
        new_meta_rel = f"data/blinded_cases/{opaque_id}/metadata.json"
        
        new_img_abs = ROOT / new_img_rel
        new_meta_abs = ROOT / new_meta_rel
        
        # Copy image array
        shutil.copy2(old_img_path, new_img_abs)
        
        # Clean metadata: remove ANY leaked parameters or class labels
        # Model only sees telescope instrument parameters: pixel size, exposure time, psf fwhm, noise rms
        clean_metadata = {
            "case_id": opaque_id,
            "instrument": "Euclid_VIS",
            "band": "VIS (550-900nm)",
            "num_pix": 64,
            "pixel_scale_arcsec": 0.10,
            "exposure_time_sec": 1690.0,
            "background_rms": 0.08,
            "psf_type": "GAUSSIAN",
            "psf_fwhm_arcsec": 0.16
        }
        new_meta_abs.write_text(json.dumps(clean_metadata, indent=2), encoding="utf-8")
        
        # Model-visible manifest entry
        model_visible_manifest.append({
            "case_id": opaque_id,
            "image_file": new_img_rel,
            "metadata_file": new_meta_rel,
            "image_sha256": hashlib.sha256(new_img_abs.read_bytes()).hexdigest(),
            "metadata_sha256": hashlib.sha256(new_meta_abs.read_bytes()).hexdigest()
        })
        
        # Sealed ground-truth key entry (strictly isolated)
        gt_info = gt_map[old_cid]
        sealed_ground_truth_key.append({
            "opaque_id": opaque_id,
            "original_case_id": old_cid,
            "true_class": gt_info["true_class"],
            "expected_decision": gt_info["expected_decision"],
            "nuisance_type": gt_info["nuisance_type"],
            "seed": gt_info["seed"],
            "ground_truth_params": gt_info["generation_parameters"]
        })
        
        print(f"  {opaque_id} <= mapped from {old_cid} (true class hidden)")

    # Save model visible manifest
    blinded_manifest_path = MANIFESTS_DIR / "blinded_model_manifest.json"
    blinded_manifest_path.write_text(json.dumps(model_visible_manifest, indent=2), encoding="utf-8")
    
    # Save sealed answer key
    sealed_key_path = MANIFESTS_DIR / "sealed_ground_truth_key.json"
    sealed_key_path.write_text(json.dumps(sealed_ground_truth_key, indent=2), encoding="utf-8")

    print(f"\nBlinded model manifest saved: {blinded_manifest_path}")
    print(f"Sealed ground truth key saved: {sealed_key_path}")


if __name__ == "__main__":
    generate_shuffled_package()
"""ShadowLens: Rigorous 3-Case Decisive Scientific Check.

Evaluates 3 distinct cases with:
- Lens slope (gamma) completely free in all fits.
- Full joint adjustment of source parameters (amp, R_sersic, n_sersic, e1, e2, center_x, center_y).
- Macro lens parameters (theta_E, gamma, e1, e2, gamma1, gamma2) free in all competing hypotheses.
- Bounded L-BFGS-B optimization without using planted ground-truth values as starts.
- Exact parameter counts:
  * Smooth EPL+Shear + Sersic: 13 parameters
  * Subhalo EPL+Shear+SIS + Sersic: 16 parameters
  * Multipole EPL+Shear+Multipole + Sersic: 15 parameters
  * Clumpy Source EPL+Shear + 2xSersic: 17 parameters
- Saves residual images, convergence diagnostics, and chi-squared values.
"""

import json
import time
from pathlib import Path
import numpy as np
from scipy.optimize import minimize

import lenstronomy.Util.simulation_util as sim_util
from lenstronomy.Data.imaging_data import ImageData
from lenstronomy.Data.psf import PSF
from lenstronomy.LensModel.lens_model import LensModel
from lenstronomy.LightModel.light_model import LightModel
from lenstronomy.ImSim.image_model import ImageModel

ROOT = Path("c:/Users/aman/Documents/meta/shadowlens")
OUT_DIR = ROOT / "decisive_check_results"
OUT_DIR.mkdir(exist_ok=True)

BOUNDS_MACRO = [
    (0.8, 1.7),     # theta_E
    (1.7, 2.3),     # gamma (free slope)
    (-0.35, 0.35),  # e1
    (-0.35, 0.35),  # e2
    (-0.15, 0.15),  # gamma1
    (-0.15, 0.15),  # gamma2
    (200.0, 3000.0),# amp
    (0.05, 0.60),   # R_sersic
    (0.5, 3.5),     # n_sersic
    (-0.3, 0.3),    # source e1
    (-0.3, 0.3),    # source e2
    (-0.2, 0.2),    # source center_x
    (-0.2, 0.2)     # source center_y
]

P0_MACRO_GENERIC = [1.2, 2.0, 0.05, 0.02, 0.0, 0.0, 1000.0, 0.2, 1.25, 0.0, 0.0, 0.0, 0.0]


def run_decisive_fit_case(case_name, img_path):
    t0 = time.time()
    img = np.load(img_path)
    num_pix = 64
    delta_pix = 0.10
    exp_time = 1690.0
    bg_rms = 0.08
    psf_fwhm = 0.16
    N = float(num_pix * num_pix)
    lnN = np.log(N)

    kd = sim_util.data_configure_simple(num_pix, delta_pix, exp_time, bg_rms)
    kd["image_data"] = img
    data_class = ImageData(**kd)
    psf_class = PSF(psf_type="GAUSSIAN", fwhm=psf_fwhm, pixel_size=delta_pix)
    var_map = bg_rms**2 + np.maximum(0, img) / exp_time

    # =========================================================================
    # 1. Macro Smooth Fit (13 parameters: 6 lens + 7 source)
    # =========================================================================
    lm_smooth = LensModel(["EPL", "SHEAR"])
    sm_smooth = LightModel(["SERSIC_ELLIPSE"])
    im_smooth = ImageModel(data_class, psf_class, lm_smooth, sm_smooth)

    def loss_smooth(p):
        kl = [
            {"theta_E": p[0], "gamma": p[1], "e1": p[2], "e2": p[3], "center_x": 0.0, "center_y": 0.0},
            {"gamma1": p[4], "gamma2": p[5]}
        ]
        ks = [
            {"amp": max(50.0, p[6]), "R_sersic": max(0.04, p[7]), "n_sersic": max(0.4, min(4.0, p[8])),
             "e1": p[9], "e2": p[10], "center_x": p[11], "center_y": p[12]}
        ]
        m_img = im_smooth.image(kl, ks)
        return np.sum(((img - m_img)**2) / var_map)

    res_sm = minimize(loss_smooth, P0_MACRO_GENERIC, method="L-BFGS-B", bounds=BOUNDS_MACRO,
                      options={"maxiter": 280, "ftol": 1e-4})
    chi2_smooth = float(res_sm.fun)
    red_chi2_smooth = chi2_smooth / N
    p_sm = res_sm.x

    kl_sm = [
        {"theta_E": p_sm[0], "gamma": p_sm[1], "e1": p_sm[2], "e2": p_sm[3], "center_x": 0.0, "center_y": 0.0},
        {"gamma1": p_sm[4], "gamma2": p_sm[5]}
    ]
    ks_sm = [
        {"amp": p_sm[6], "R_sersic": p_sm[7], "n_sersic": p_sm[8],
         "e1": p_sm[9], "e2": p_sm[10], "center_x": p_sm[11], "center_y": p_sm[12]}
    ]
    m_img_sm = im_smooth.image(kl_sm, ks_sm)
    res_map_sm = (img - m_img_sm) / np.sqrt(var_map)
    np.save(OUT_DIR / f"{case_name}_residual_smooth.npy", res_map_sm)

    # =========================================================================
    # 2. Subhalo Search along Arc + Joint 16-parameter Optimization
    # =========================================================================
    y_g, x_g = np.indices((num_pix, num_pix))
    r_g = np.sqrt(((x_g - (num_pix//2)) * delta_pix)**2 + ((y_g - (num_pix//2)) * delta_pix)**2)
    arc_mask = (r_g >= 0.7) & (r_g <= 1.7)
    masked_res = np.where(arc_mask, np.abs(res_map_sm), 0.0)

    top_cands = []
    flat_indices = np.argsort(masked_res.ravel())[::-1]
    for idx in flat_indices[:50]:
        py, px = np.unravel_index(idx, (num_pix, num_pix))
        cx = (px - (num_pix//2)) * delta_pix
        cy = (py - (num_pix//2)) * delta_pix
        if all(np.sqrt((cx - c[0])**2 + (cy - c[1])**2) > 0.35 for c in top_cands):
            top_cands.append((cx, cy))
        if len(top_cands) >= 4:
            break

    lm_sub = LensModel(["EPL", "SHEAR", "SIS"])
    im_sub = ImageModel(data_class, psf_class, lm_sub, sm_smooth)
    best_chi2_sub = chi2_smooth
    best_sub_res = None
    best_p_sub = None

    for cand_x, cand_y in top_cands:
        # Full joint loss: 6 macro lens + 7 source + 3 subhalo = 16 parameters
        def loss_sub_joint(p):
            kl = [
                {"theta_E": p[0], "gamma": p[1], "e1": p[2], "e2": p[3], "center_x": 0.0, "center_y": 0.0},
                {"gamma1": p[4], "gamma2": p[5]},
                {"theta_E": max(0.005, p[13]), "center_x": p[14], "center_y": p[15]}
            ]
            ks = [
                {"amp": max(50.0, p[6]), "R_sersic": max(0.04, p[7]), "n_sersic": max(0.4, min(4.0, p[8])),
                 "e1": p[9], "e2": p[10], "center_x": p[11], "center_y": p[12]}
            ]
            m_img = im_sub.image(kl, ks)
            return np.sum(((img - m_img)**2) / var_map)

        p0_sub = list(p_sm) + [0.05, cand_x, cand_y]
        bounds_sub = BOUNDS_MACRO + [(0.01, 0.20), (cand_x - 0.30, cand_x + 0.30), (cand_y - 0.30, cand_y + 0.30)]
        res_sub = minimize(loss_sub_joint, p0_sub, method="L-BFGS-B", bounds=bounds_sub,
                           options={"maxiter": 220, "ftol": 1e-4})
        if res_sub.fun < best_chi2_sub:
            best_chi2_sub = float(res_sub.fun)
            best_sub_res = res_sub
            best_p_sub = res_sub.x

    if best_p_sub is not None:
        kl_sub = [
            {"theta_E": best_p_sub[0], "gamma": best_p_sub[1], "e1": best_p_sub[2], "e2": best_p_sub[3], "center_x": 0.0, "center_y": 0.0},
            {"gamma1": best_p_sub[4], "gamma2": best_p_sub[5]},
            {"theta_E": best_p_sub[13], "center_x": best_p_sub[14], "center_y": best_p_sub[15]}
        ]
        ks_sub = [
            {"amp": best_p_sub[6], "R_sersic": best_p_sub[7], "n_sersic": best_p_sub[8],
             "e1": best_p_sub[9], "e2": best_p_sub[10], "center_x": best_p_sub[11], "center_y": best_p_sub[12]}
        ]
        m_img_sub = im_sub.image(kl_sub, ks_sub)
        res_map_sub = (img - m_img_sub) / np.sqrt(var_map)
        np.save(OUT_DIR / f"{case_name}_residual_subhalo.npy", res_map_sub)

    # =========================================================================
    # 3. Multipole Nuisance: 6 lens + 7 source + 2 multipole = 15 parameters
    # =========================================================================
    best_chi2_multi = chi2_smooth
    best_multi_params = None
    for m in [3, 4]:
        lm_multi = LensModel(["EPL", "SHEAR", "MULTIPOLE"])
        im_multi = ImageModel(data_class, psf_class, lm_multi, sm_smooth)

        def loss_multi_joint(p):
            kl = [
                {"theta_E": p[0], "gamma": p[1], "e1": p[2], "e2": p[3], "center_x": 0.0, "center_y": 0.0},
                {"gamma1": p[4], "gamma2": p[5]},
                {"m": m, "a_m": p[13], "phi_m": p[14], "center_x": 0.0, "center_y": 0.0}
            ]
            ks = [
                {"amp": max(50.0, p[6]), "R_sersic": max(0.04, p[7]), "n_sersic": max(0.4, min(4.0, p[8])),
                 "e1": p[9], "e2": p[10], "center_x": p[11], "center_y": p[12]}
            ]
            m_img = im_multi.image(kl, ks)
            return np.sum(((img - m_img)**2) / var_map)

        p0_m = list(p_sm) + [0.02, 0.3]
        bounds_m = BOUNDS_MACRO + [(-0.08, 0.08), (0.0, np.pi)]
        res_m = minimize(loss_multi_joint, p0_m, method="L-BFGS-B", bounds=bounds_m,
                         options={"maxiter": 180, "ftol": 1e-4})
        if res_m.fun < best_chi2_multi:
            best_chi2_multi = float(res_m.fun)
            best_multi_params = {
                "m": m,
                "a_m": float(res_m.x[13]),
                "phi_m": float(res_m.x[14]),
                "gamma": float(res_m.x[1])
            }

    # =========================================================================
    # 4. Clumpy Source Nuisance: 6 lens + 7 source + 4 clump = 17 parameters
    # =========================================================================
    sm_clump = LightModel(["SERSIC_ELLIPSE", "SERSIC_ELLIPSE"])
    im_clump = ImageModel(data_class, psf_class, lm_smooth, sm_clump)
    best_chi2_clump = chi2_smooth
    best_clump_params = None

    sc_x = p_sm[11]
    sc_y = p_sm[12]
    for ox, oy in [(0.06, -0.04), (-0.06, -0.05), (0.05, 0.05), (-0.05, 0.06)]:
        def loss_clump_joint(p):
            kl = [
                {"theta_E": p[0], "gamma": p[1], "e1": p[2], "e2": p[3], "center_x": 0.0, "center_y": 0.0},
                {"gamma1": p[4], "gamma2": p[5]}
            ]
            ks = [
                {"amp": max(50.0, p[6]), "R_sersic": max(0.04, p[7]), "n_sersic": max(0.4, min(4.0, p[8])),
                 "e1": p[9], "e2": p[10], "center_x": p[11], "center_y": p[12]},
                {"amp": max(0.0, p[13]), "R_sersic": max(0.015, p[14]), "n_sersic": 1.0,
                 "e1": 0.0, "e2": 0.0, "center_x": p[15], "center_y": p[16]}
            ]
            m_img = im_clump.image(kl, ks)
            return np.sum(((img - m_img)**2) / var_map)

        p0_c = list(p_sm) + [300.0, 0.04, sc_x + ox, sc_y + oy]
        bounds_c = BOUNDS_MACRO + [
            (10.0, 1500.0), (0.015, 0.15),
            (sc_x - 0.15, sc_x + 0.15), (sc_y - 0.15, sc_y + 0.15)
        ]
        res_c = minimize(loss_clump_joint, p0_c, method="L-BFGS-B", bounds=bounds_c,
                         options={"maxiter": 160, "ftol": 1e-4})
        if res_c.fun < best_chi2_clump:
            best_chi2_clump = float(res_c.fun)
            best_clump_params = {
                "amp_2": float(res_c.x[13]),
                "R_2": float(res_c.x[14]),
                "center_x_2": float(res_c.x[15]),
                "center_y_2": float(res_c.x[16])
            }

    # BICs:
    # smooth: k=13
    # subhalo: k=16
    # multipole: k=15
    # clump: k=17
    bic_smooth = chi2_smooth + 13.0 * lnN
    bic_sub = best_chi2_sub + 16.0 * lnN
    bic_multi = best_chi2_multi + 15.0 * lnN
    bic_clump = best_chi2_clump + 17.0 * lnN

    if bic_multi <= bic_clump:
        bic_alt = bic_multi
        chi2_alt = best_chi2_multi
        alt_type = f"LENS_MULTIPOLE_m{best_multi_params['m']}" if best_multi_params else "LENS_MULTIPOLE"
        alt_params = best_multi_params
    else:
        bic_alt = bic_clump
        chi2_alt = best_chi2_clump
        alt_type = "SOURCE_COMPLEXITY_CLUMP"
        alt_params = best_clump_params

    delta_bic_sub = bic_smooth - bic_sub
    delta_bic_alt = bic_smooth - bic_alt

    elapsed = round(time.time() - t0, 2)
    return {
        "case_name": case_name,
        "runtime_sec": elapsed,
        "chi2_smooth": round(chi2_smooth, 1),
        "reduced_chi2_smooth": round(red_chi2_smooth, 4),
        "fitted_gamma_smooth": round(float(p_sm[1]), 4),
        "chi2_subhalo": round(best_chi2_sub, 1),
        "reduced_chi2_subhalo": round(best_chi2_sub / N, 4),
        "fitted_subhalo_params": {
            "theta_E": round(float(best_p_sub[13]), 4) if best_p_sub is not None else None,
            "center_x": round(float(best_p_sub[14]), 4) if best_p_sub is not None else None,
            "center_y": round(float(best_p_sub[15]), 4) if best_p_sub is not None else None,
            "gamma_lens": round(float(best_p_sub[1]), 4) if best_p_sub is not None else None
        } if best_p_sub is not None else None,
        "chi2_alternative": round(chi2_alt, 1),
        "reduced_chi2_alternative": round(chi2_alt / N, 4),
        "selected_alternative_model": alt_type,
        "fitted_alt_params": alt_params,
        "delta_bic_subhalo": round(delta_bic_sub, 1),
        "delta_bic_alt": round(delta_bic_alt, 1)
    }


def main():
    print("=== Running ShadowLens Decisive 3-Case Scientific Check ===")
    cases = [
        ("case_01_subhalo", ROOT / "data/cases/case_01/image.npy"),
        ("case_05_smooth", ROOT / "data/cases/case_05/image.npy"),
        ("case_09_multipole", ROOT / "data/cases/case_09/image.npy")
    ]

    all_results = {}
    for cname, cpath in cases:
        print(f"\nEvaluating {cname}...", flush=True)
        res = run_decisive_fit_case(cname, cpath)
        all_results[cname] = res
        print(f"  Smooth Fit:    chi2 = {res['chi2_smooth']:.1f} (red = {res['reduced_chi2_smooth']:.3f}), gamma = {res['fitted_gamma_smooth']}")
        print(f"  Subhalo Fit:   chi2 = {res['chi2_subhalo']:.1f} (red = {res['reduced_chi2_subhalo']:.3f}), delta_BIC = {res['delta_bic_subhalo']:.1f}")
        print(f"  Nuisance Fit:  chi2 = {res['chi2_alternative']:.1f} (red = {res['reduced_chi2_alternative']:.3f}), model = {res['selected_alternative_model']}, delta_BIC = {res['delta_bic_alt']:.1f}")

    out_file = OUT_DIR / "decisive_check_summary.json"
    out_file.write_text(json.dumps(all_results, indent=2), encoding="utf-8")
    print(f"\nAll results saved to {out_file}")


if __name__ == "__main__":
    main()
"""Export an isolated model-input package for ShadowLens.

Enforces zero leakage:
1. Destination folder: shadowlens/model_input_export/
2. Contains only:
   - Blinded case images (.npy)
   - Clean instrument-only metadata (.json)
   - Fitted diagnostics summary (.json) containing only observed metrics:
     reduced_chi2, delta_BIC_sub, delta_BIC_alt, best_alt_type, fitted parameter values.
3. Contains ZERO:
   - Ground truth manifests or answer keys.
   - Original case_01..12 IDs or mappings.
   - True class labels or expected decisions.
   - Report text revealing answers.
"""

import json
import shutil
from pathlib import Path

ROOT = Path("c:/Users/aman/Documents/meta/shadowlens")
EXPORT_DIR = ROOT / "model_input_export"
BLINDED_DIR = ROOT / "data" / "blinded_cases"
OUT_RESULTS = ROOT / "repaired_baseline_results.json"


def create_isolated_export():
    if EXPORT_DIR.exists():
        shutil.rmtree(EXPORT_DIR)
    EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    
    cases_dir = EXPORT_DIR / "cases"
    cases_dir.mkdir(exist_ok=True)
    
    # Copy blinded cases
    manifest_entries = []
    for case_folder in sorted(BLINDED_DIR.glob("SL-*")):
        cid = case_folder.name
        dest_case = cases_dir / cid
        dest_case.mkdir(exist_ok=True)
        
        # Copy image and clean metadata
        shutil.copy2(case_folder / "image.npy", dest_case / "image.npy")
        shutil.copy2(case_folder / "metadata.json", dest_case / "metadata.json")
        manifest_entries.append(cid)
        
    # Create diagnostics file for model reasoning
    # Only includes empirical fitting statistics
    results = json.load(open(OUT_RESULTS, encoding="utf-8"))
    clean_diagnostics = []
    for r in results:
        clean_diagnostics.append({
            "case_id": r["case_id"],
            "reduced_chi2_smooth": r["reduced_chi2_smooth"],
            "delta_bic_subhalo": r["delta_bic_subhalo"],
            "delta_bic_alternative": r["delta_bic_alt"],
            "selected_alternative_model": r["selected_alternative_model"],
            "fitted_subhalo_params": r.get("fitted_subhalo_params"),
            "fitted_alt_params": r.get("fitted_alt_params"),
            "baseline_statistical_verdict": r["verdict"]
        })
        
    diag_file = EXPORT_DIR / "fitted_diagnostics.json"
    diag_file.write_text(json.dumps(clean_diagnostics, indent=2), encoding="utf-8")
    
    export_manifest = {
        "export_description": "Isolated model-visible evaluation package. Blinded cases only.",
        "cases_count": len(manifest_entries),
        "case_ids": manifest_entries,
        "diagnostics_file": "fitted_diagnostics.json"
    }
    (EXPORT_DIR / "export_manifest.json").write_text(json.dumps(export_manifest, indent=2), encoding="utf-8")
    print(f"Isolated model export created at {EXPORT_DIR} with {len(manifest_entries)} cases.")


if __name__ == "__main__":
    create_isolated_export()
"""Predeclaration of Fresh Untouched Evaluation Set.

This module locks the exact seeds, case IDs, classes, and parameter sampling logic
BEFORE any simulation or fitting is executed.
All cases will be kept, including failures or edge cases.
"""

