"""
ShadowLens Cryptographic Sealing & Anti-Leakage Verification Script.
Confirms:
1. All 12 simulated images and visible metadata files exist and match SHA256 checksums.
2. Ground-truth manifest hashes match visible files.
3. No secret labels, subhalo coordinates, seeds, or true classes leak into visible files.
"""

import os
import json
import hashlib

def compute_sha256(file_path):
    h = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):
            h.update(chunk)
    return h.hexdigest()

def verify_sealing(base_dir="C:/Users/aman/Documents/meta/shadowlens"):
    manifests_dir = os.path.join(base_dir, "manifests")
    vis_path = os.path.join(manifests_dir, "visible_manifest.json")
    gt_path = os.path.join(manifests_dir, "ground_truth_manifest.json")

    assert os.path.exists(vis_path), f"Missing visible manifest: {vis_path}"
    assert os.path.exists(gt_path), f"Missing ground truth manifest: {gt_path}"

    with open(vis_path, "r") as f:
        visible_manifest = json.load(f)
    with open(gt_path, "r") as f:
        gt_manifest = json.load(f)

    assert len(visible_manifest) == 12, f"Expected 12 visible cases, got {len(visible_manifest)}"
    assert len(gt_manifest) == 12, f"Expected 12 ground truth cases, got {len(gt_manifest)}"

    forbidden_tokens = ["TRUE_SUBHALO", "SMOOTH_CONTROL", "MULTIPOLE_NUISANCE", "SOURCE_COMPLEXITY_NUISANCE", "subhalo", "nuisance"]

    print("=== Cryptographic Integrity and Sealing Verification ===")
    leak_detected = False

    for v_entry, gt_entry in zip(visible_manifest, gt_manifest):
        cid = v_entry["case_id"]
        assert cid == gt_entry["case_id"], f"Mismatched case ID: {cid} vs {gt_entry['case_id']}"

        # Check image file hash
        img_full_path = os.path.join(base_dir, v_entry["image_file"])
        assert os.path.exists(img_full_path), f"Missing image file: {img_full_path}"
        actual_img_sha = compute_sha256(img_full_path)
        assert actual_img_sha == v_entry["image_sha256"], f"Image hash mismatch on {cid}"
        assert actual_img_sha == gt_entry["verification"]["image_sha256"], f"GT image hash mismatch on {cid}"

        # Check metadata file hash
        meta_full_path = os.path.join(base_dir, v_entry["metadata_file"])
        assert os.path.exists(meta_full_path), f"Missing metadata file: {meta_full_path}"
        actual_meta_sha = compute_sha256(meta_full_path)
        assert actual_meta_sha == v_entry["metadata_sha256"], f"Meta hash mismatch on {cid}"
        assert actual_meta_sha == gt_entry["verification"]["metadata_sha256"], f"GT meta hash mismatch on {cid}"

        # Check for visible answer leakage in metadata.json
        with open(meta_full_path, "r") as f:
            meta_content = f.read()
            for token in forbidden_tokens:
                if token.lower() in meta_content.lower():
                    print(f"LEAK WARNING: Forbidden token '{token}' found in {meta_full_path}")
                    leak_detected = True

    # Check visible manifest itself for leakage
    with open(vis_path, "r") as f:
        vis_text = f.read()
        for token in forbidden_tokens:
            if token.lower() in vis_text.lower():
                print(f"LEAK WARNING: Forbidden token '{token}' found in visible manifest!")
                leak_detected = True

    if not leak_detected:
        print("[PASS] Zero visible answer leakage. All 12 cases cryptographically sealed.")
        print(f"[PASS] 12 image SHA256 checksums verified.")
        print(f"[PASS] 12 metadata SHA256 checksums verified.")
        return True
    else:
        print("[FAIL] Leakage detected!")
        return False

if __name__ == "__main__":
    verify_sealing()
# ShadowLens package
"""Independent diagnostic: compare baseline loss with the planted model loss."""

import json
from pathlib import Path

import numpy as np
from lenstronomy.Data.imaging_data import ImageData
from lenstronomy.Data.psf import PSF
from lenstronomy.ImSim.image_model import ImageModel
from lenstronomy.LensModel.lens_model import LensModel
from lenstronomy.LightModel.light_model import LightModel
from lenstronomy.Util.simulation_util import data_configure_simple

root = Path(r"C:\Users\aman\Documents\meta\shadowlens")
truth = json.loads((root / "manifests/ground_truth_manifest.json").read_text())
baseline = {r["case_id"]: r for r in json.loads((root / "baseline_results.json").read_text())}

for record in truth:
    case = record["case_id"]
    params = record["generation_parameters"]
    image = np.load(root / "data/cases" / case / "image.npy")
    kwargs_data = data_configure_simple(64, 0.10, 1690.0, 0.08)
    kwargs_data["image_data"] = image
    data = ImageData(**kwargs_data)
    psf = PSF(psf_type="GAUSSIAN", fwhm=0.16, pixel_size=0.10)
    lens_types = ["EPL", "SHEAR"]
    lens_params = [params["macro_lens"], params["shear"]]
    if params["subhalo"] is not None:
        lens_types.append("SIS")
        lens_params.append({k: v for k, v in params["subhalo"].items() if k != "type"})
    if params["multipole"] is not None:
        lens_types.append("MULTIPOLE")
        lens_params.append(params["multipole"])
    source = params["source"]
    model = ImageModel(data, psf, LensModel(lens_types), LightModel(["SERSIC_ELLIPSE"] * len(source)))
    prediction = model.image(lens_params, source)
    variance = 0.08**2 + np.maximum(0, image) / 1690.0
    chi2_truth = float(np.sum((image - prediction) ** 2 / variance))
    b = baseline[case]
    print(f"{case} {record['true_class']:26s} true_model_chi2={chi2_truth:9.1f} baseline_best_chi2={min(b['chi2_smooth'],b['chi2_subhalo'],b['chi2_alternative']):9.1f}")
